// Same matcher shape as getInSituBaseline() above - nearest site whose own
// radius contains the click, or null. ES5 shallow copy, no Object.assign.
function getAcousticSite(lat, lon){
  var best=null, bestDist=Infinity;
  for(var key in ACOUSTIC_SITES){
    if(!Object.prototype.hasOwnProperty.call(ACOUSTIC_SITES,key)) continue;
    var st=ACOUSTIC_SITES[key];
    var d=haversineKm(lat,lon,st.lat,st.lon);
    if(d<=st.radius_km && d<bestDist){
      var _st={key:key, distance_km:d};
      for(var _sk in st){ if(Object.prototype.hasOwnProperty.call(st,_sk)) _st[_sk]=st[_sk]; }
      best=_st; bestDist=d;
    }
  }
  return best;
}

// SEASONAL (HIRSCH-SLACK) MANN-KENDALL.
// S and var(S) are computed WITHIN each calendar month across years, then
// summed. Nothing is deseasonalized, nothing is imputed, and no climatology is
// built - which is the point, because FK01 CANNOT build one (see S21 panel text).
//
// WHY THIS AND NOT THE PLAIN mannKendallTest() ABOVE. MEASURED on this exact
// table's underlying absolute levels: plain Mann-Kendall over the 29 pooled
// monthly snapping-shrimp means returns tau=+0.227, p=0.0878 - close enough to
// look like an emerging trend. It is sampling aliasing. FK01's deployments are
// seasonally unbalanced (July, August, September, October and November each
// occur in exactly ONE year), and the shrimp band runs ~4 dB hotter in summer,
// so the later-weighted summer coverage tilts the pooled series upward on its
// own. Comparing like with like kills it: April across 2019-2022 reads
// 109.32, 110.29, 109.21, 109.33 dB - tau exactly 0.000. One more summer
// deployment would have pushed that pooled p under 0.05 and meant nothing.
// The seasonal test cannot make that mistake: a value is only ever ranked
// against the SAME calendar month in another year.
//
// DISCLOSED LIMIT: with 3-4 years per season the per-season S values are tiny
// and the normal approximation to their SUM is the standard (Hirsch & Slack
// 1984) but not exact. The inter-season covariance correction for serially
// dependent seasons is NOT applied - at n=3-4 per season it is estimated far
// too noisily to help, and omitting it is the conventional choice. Treat a
// borderline p from this test as borderline.
//
// FALSE-POSITIVE RATE, MEASURED - not assumed, and not inherited from the plain
// Mann-Kendall's calibration. Monte Carlo in a Node harness against THIS
// function, at FK01's exact design (7 seasons of 3,4,4,4,3,3,3 years), pure
// uniform noise, 4000 draws: 4.05% of draws returned p<0.05, against a nominal
// 5%. Slightly CONSERVATIVE, which is the safe direction - this test does not
// over-trigger at the sample size it is actually being used at. Contrast S17's
// SNR>=2.0 rule, which is calibrated to no false-positive rate at all (see the
// S17b panel text, v10.145).
function seasonalMannKendall(rows){
  var bySeason={}, i;
  for(i=0;i<(rows||[]).length;i++){
    var r=rows[i];
    if(r===null||r===undefined||r.v===null||r.v===undefined||isNaN(r.v)) continue;
    var cm=parseInt(r.m.substring(5,7),10);
    if(!bySeason[cm]) bySeason[cm]=[];
    bySeason[cm].push(r.v);
  }
  var Stot=0, Vtot=0, nPairs=0, seasonsUsed=0, seasonsSkipped=0, detail=[];
  for(var cm2=1; cm2<=12; cm2++){
    var v=bySeason[cm2];
    if(!v||v.length<2){ if(v){ seasonsSkipped++; } continue; }
    var n=v.length, S=0, a, b;
    for(a=0;a<n-1;a++){
      for(b=a+1;b<n;b++){
        var diff=v[b]-v[a];
        if(diff>0) S++; else if(diff<0) S--;
      }
    }
    // per-season tie correction, same formula the main mannKendallTest() uses
    var sorted=v.slice().sort(function(x,y){return x-y;});
    var tieTerm=0, runLen=1;
    for(var s2=1;s2<=n;s2++){
      if(s2<n && sorted[s2]===sorted[s2-1]){ runLen++; }
      else { if(runLen>1){ tieTerm+=runLen*(runLen-1)*(2*runLen+5); } runLen=1; }
    }
    var V=(n*(n-1)*(2*n+5)-tieTerm)/18;
    Stot+=S; Vtot+=V; nPairs+=n*(n-1)/2; seasonsUsed++;
    detail.push({cm:cm2, n:n, S:S});
  }
  // TWO DISTINCT FAILURE MODES, and they must not share a message. Too few
  // seasons is a coverage problem; zero pooled variance is a TIE problem - every
  // season's values are identical across years, so the ranks carry no
  // information at all. Calling the second one "insufficient seasons" would
  // send a reader looking for more data when more data is not the issue.
  if(seasonsUsed<2){
    return {tau:null,S:null,z:null,p:null,seasonsUsed:seasonsUsed,
            seasonsSkipped:seasonsSkipped,nPairs:nPairs,slope:null,
            error:'insufficient seasons (need >=2 with >=2 years each; got '+seasonsUsed+')'};
  }
  if(Vtot<=0){
    return {tau:null,S:null,z:null,p:null,seasonsUsed:seasonsUsed,
            seasonsSkipped:seasonsSkipped,nPairs:nPairs,slope:null,
            error:'zero variance - every season is fully tied across years ('+
                  seasonsUsed+' season(s), '+nPairs+' pairs, all ties)'};
  }
  var z=0;
  if(Stot>0) z=(Stot-1)/Math.sqrt(Vtot); else if(Stot<0) z=(Stot+1)/Math.sqrt(Vtot);
  var p=2*(1-normalCDF(Math.abs(z)));
  if(p>1) p=1;
  // Pooled seasonal Sen slope: median of within-season year-normalised slopes.
  var slopes=[];
  for(var cm3=1; cm3<=12; cm3++){
    var rs=[];
    for(i=0;i<rows.length;i++){ if(parseInt(rows[i].m.substring(5,7),10)===cm3) rs.push(rows[i]); }
    for(a=0;a<rs.length;a++){
      for(b=a+1;b<rs.length;b++){
        var dy=parseInt(rs[b].m.substring(0,4),10)-parseInt(rs[a].m.substring(0,4),10);
        if(dy!==0) slopes.push((rs[b].v-rs[a].v)/dy);
      }
    }
  }
  var slope=null;
  if(slopes.length){
    slopes.sort(function(x,y){return x-y;});
    var mid=Math.floor(slopes.length/2);
    slope=(slopes.length%2)?slopes[mid]:(slopes[mid-1]+slopes[mid])/2;
  }
  return {tau:Stot/nPairs, S:Stot, z:z, p:p, seasonsUsed:seasonsUsed,
          seasonsSkipped:seasonsSkipped, nPairs:nPairs, slope:slope,
          nSlopes:slopes.length, detail:detail, error:null};
}

function getOISSTColl(startDate, endDate) {
  return ee.ImageCollection('NOAA/CDR/OISST/V2_1')
    .filterDate(startDate, endDate).select('sst')
    .map(function(img){ return img.multiply(0.01).copyProperties(img,['system:time_start']); });
}

var sstColl = getOISSTColl('2023-01-01','2024-12-31');
var sstRaw = ee.Image(ee.Algorithms.If(sstColl.size().gt(0),
  sstColl.mean(), ee.Image.constant(25).rename('sst'))).rename('sst');
var sst = sstRaw.updateMask(sstRaw.gt(-2).and(sstRaw.lt(40)).and(oceanMask));

// v10.93 FIX: 'Peak(Jun-Oct)' / DHW used a SINGLE hardcoded window
// (Jun-Oct 2023), which is Northern Hemisphere summer only. For Southern
// Hemisphere reefs (Great Barrier Reef, Ningaloo, Madagascar/S. Indian
// Ocean, S. Brazil, S. Africa - roughly half the world's reef area by
// latitude), the real hot/bleaching season is Nov-Apr and was being missed
// entirely. A real, independently-documented 2023-24 mass bleaching event
// at a Southern Hemisphere GBR test site showed DHW=0.00 (falsely "no
// stress") purely because the tool was reading winter SST as the "peak".
// This one number feeds the main DHW badge, the S4 cancer-score component
// (25% weight), the map's bleaching-risk layer, and the intervention
// engine's thermal-stress trigger - so this bug silently zeroed out heat-
// stress detection for every Southern Hemisphere reef in the tool.
// Fix: compute BOTH hemispheres' peak windows, then select per-click based
// on the clicked latitude's sign (see analyzeLocation() and loadLayers()).
var oisstPeakColl = getOISSTColl('2023-06-01','2023-10-31'); // Northern Hemisphere summer
var oisstPeakMax = ee.Image(ee.Algorithms.If(oisstPeakColl.size().gt(0),
  oisstPeakColl.max(), ee.Image.constant(28).rename('sst'))).rename('sst_peak');
var sstPeakNH = oisstPeakMax.updateMask(oisstPeakMax.gt(-2).and(oisstPeakMax.lt(40)).and(oceanMask));
var sstPeakFinalNH = sstPeakNH.unmask(sstRaw.updateMask(oceanMask));

var oisstPeakCollSH = getOISSTColl('2023-11-01','2024-04-30'); // Southern Hemisphere summer (same 2023-24 stress year)
var oisstPeakMaxSH = ee.Image(ee.Algorithms.If(oisstPeakCollSH.size().gt(0),
  oisstPeakCollSH.max(), ee.Image.constant(28).rename('sst'))).rename('sst_peak');
var sstPeakSH = oisstPeakMaxSH.updateMask(oisstPeakMaxSH.gt(-2).and(oisstPeakMaxSH.lt(40)).and(oceanMask));
var sstPeakFinalSH = sstPeakSH.unmask(sstRaw.updateMask(oceanMask));

// Default/legacy name kept pointing at the Northern Hemisphere version so
// the startup (unclicked) map view - centred near-equatorial at Bocas del
// Toro, Panama - still renders sensibly without needing a hemisphere choice.
var sstPeakFinal = sstPeakFinalNH;

var mmmColl = getOISSTColl('2003-01-01','2022-12-31');
var monthList = ee.List.sequence(1,12);
var monthlyMeans = ee.ImageCollection(monthList.map(function(mo){
  var moNum = ee.Number(mo);
  var col = mmmColl.filter(ee.Filter.calendarRange(moNum, moNum, 'month'));
  return ee.Image(ee.Algorithms.If(col.size().gt(0),
    col.mean().rename('sst'),
    ee.Image.constant(25).rename('sst').updateMask(ee.Image.constant(0))));
}));
var MMM_perpixel = monthlyMeans.max().rename('mmm').updateMask(oceanMask);
// dhwProper (NH) kept for the startup default view; dhwProperSH added for
// Southern Hemisphere clicks. Both share the same hemisphere-agnostic
// MMM_perpixel baseline (that part was already correct - it takes the max
// across all 12 calendar months per pixel, so it naturally picks the right
// "warm season" baseline regardless of hemisphere).
var dhwProper = sstPeakFinalNH.subtract(MMM_perpixel.add(1)).max(0).multiply(12).rename('dhw').updateMask(oceanMask);
var dhwProperSH = sstPeakFinalSH.subtract(MMM_perpixel.add(1)).max(0).multiply(12).rename('dhw').updateMask(oceanMask);


var chlColl = ee.ImageCollection('COPERNICUS/MARINE/SATELLITE_OCEAN_COLOR/V6')
  .filterDate('2023-01-01','2024-12-31').select('chlor_a');
var chlaRaw = ee.Image(ee.Algorithms.If(chlColl.size().gt(0),
  chlColl.mean(), ee.Image.constant(0).rename('chlor_a'))).rename('chlor_a');
var chla = chlaRaw.updateMask(chlaRaw.gt(0).and(chlaRaw.lt(100)).and(oceanMask));
var chlaCoastal = chlaRaw.updateMask(chlaRaw.gt(0).and(chlaRaw.lt(100)));

var s2Coll = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
  .filterDate('2023-01-01','2024-12-31')
  .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE',20)).select(['B4','B8']);
var turbRaw = ee.Image(ee.Algorithms.If(s2Coll.size().gt(0),
  s2Coll.mean().normalizedDifference(['B4','B8']).rename('turbidity'),
  ee.Image.constant(0).rename('turbidity').updateMask(ee.Image.constant(0))));
var turbImg = turbRaw.updateMask(shallowMask);

var s2_basic = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
  .filterDate('2023-01-01','2024-12-31').filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE',20)).select(['B4','B8']);
var s2_basic_mean = ee.Image(ee.Algorithms.If(s2_basic.size().gt(0),
  s2_basic.map(function(img){ return img.divide(10000); }).median(),
  ee.Image.constant(0.05).rename('B4').addBands(ee.Image.constant(0.05).rename('B8'))));

// v10.41 FIX: defensive band check before normalizedDifference()
var _s2basic_bandsOk = s2_basic_mean.bandNames().size().gte(2);
var ndviWater = ee.Image(ee.Algorithms.If(_s2basic_bandsOk,
  s2_basic_mean.select(['B8','B4']).normalizedDifference(['B8','B4']).rename('ndvi_water'),
  ee.Image.constant(0).rename('ndvi_water').updateMask(ee.Image.constant(0))));
var ndviAlgae = ndviWater.updateMask(ndviWater.gt(0.03).and(oceanMask));

var s2_ext = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
  .filterDate('2023-01-01','2024-12-31').filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE',20)).select(['B4','B5','B8','B11']);
var s2_ext_avail = s2_ext.size().gt(0);
var s2_ext_mean = ee.Image(ee.Algorithms.If(s2_ext_avail,
  s2_ext.map(function(img){ return img.divide(10000); }).median(),
  s2_basic_mean.addBands(ee.Image.constant(0.03).rename('B5')).addBands(ee.Image.constant(0.03).rename('B11'))));

var fai_step = (842-665)/(1610-665);
var faiImg = s2_ext_mean.expression('NIR - (RED + (SWIR - RED) * step)',
  {'NIR':s2_ext_mean.select('B8'),'RED':s2_ext_mean.select('B4'),'SWIR':s2_ext_mean.select('B11'),'step':fai_step}).rename('fai');
var faiMild = faiImg.updateMask(faiImg.gt(0.003).and(oceanMask));
var faiAlgae = faiImg.updateMask(faiImg.gt(0.01).and(oceanMask));

// v10.41 FIX: same defensive check for ndciImg
var _s2ext_bandsOk = s2_ext_mean.bandNames().size().gte(4);
var ndciImg = ee.Image(ee.Algorithms.If(_s2ext_bandsOk,
  s2_ext_mean.select(['B5','B4']).normalizedDifference(['B5','B4']).rename('ndci'),
  ee.Image.constant(0).rename('ndci').updateMask(ee.Image.constant(0))));
var ndciBloom = ndciImg.updateMask(ndciImg.gt(0.05).and(oceanMask));

var no2Coll = ee.ImageCollection('COPERNICUS/S5P/NRTI/L3_NO2').filterDate('2023-01-01','2024-12-31').select('NO2_column_number_density')
  .merge(ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2').filterDate('2023-01-01','2024-12-31').select('NO2_column_number_density'));
var no2Raw = ee.Image(ee.Algorithms.If(no2Coll.size().gt(0),
  no2Coll.mean(), ee.Image.constant(0.00003).rename('NO2_column_number_density'))).rename('NO2_column_number_density');
var no2 = no2Raw.updateMask(no2Raw.gt(0));

var yrList = ee.List.sequence(2003,2024), nYears = 22, SST_FLOOR_GLOBAL = 14.0;
var annSSTraw = ee.ImageCollection(yrList.map(function(yr){
  var yrN=ee.Number(yr), d=ee.Date.fromYMD(yrN,1,1), de=ee.Date.fromYMD(yrN,12,31), col=getOISSTColl(d,de);
  var sstY=ee.Image(ee.Algorithms.If(col.size().gt(3),
    col.mean().updateMask(col.mean().gt(SST_FLOOR_GLOBAL).and(col.mean().lt(40)).and(oceanMask)),
    ee.Image.constant(-9999).rename('sst').updateMask(ee.Image.constant(0)))).rename('sst');
  return sstY.set('system:time_start',d.millis()).set('year',yrN);
}));
var sstStats = annSSTraw.select('sst').reduce(ee.Reducer.mean().combine(ee.Reducer.stdDev(),'',true));
var sstMeanImg = sstStats.select('sst_mean'), sstStdImg = sstStats.select('sst_stdDev').max(0.3);
var annSSTcoll = ee.ImageCollection(annSSTraw.map(function(img){
  var z=img.subtract(sstMeanImg).divide(sstStdImg).abs();
  return img.updateMask(z.gt(2.5).not()).copyProperties(img,['system:time_start','year']);
}));
var annSSTlist = annSSTcoll.toList(nYears), allIdx = ee.List.sequence(0,nYears-1);
var pairSlopeImagesList = allIdx.map(function(i){
  var iN=ee.Number(i), jList=ee.List.sequence(iN.add(1),nYears-1);
  return jList.map(function(j){
    var jN=ee.Number(j), img_i=ee.Image(annSSTlist.get(iN)), img_j=ee.Image(annSSTlist.get(jN));
    return img_j.subtract(img_i).divide(jN.subtract(iN)).rename('slope').updateMask(img_i.mask().and(img_j.mask()));
  });
}).flatten();
var pairSlopes = ee.ImageCollection.fromImages(pairSlopeImagesList);
var sst_slope = pairSlopes.select('slope').median().unmask(0).updateMask(oceanMask).rename('scale');
var validYearCount = annSSTcoll.select('sst').map(function(img){ return img.mask(); }).sum().rename('validYears');

function isEBUS(lat,lon) {
  if(lat>20&&lat<40&&lon>-25&&lon<-10) return true;
  if(lat>30&&lat<50&&lon>-130&&lon<-115) return true;
  if(lat>-45&&lat<-5&&lon>-90&&lon<-70) return true;
  if(lat>-35&&lat<-15&&lon>10&&lon<20) return true;
  return false;
}

var annualSST = ee.ImageCollection(yrList.map(function(yr){
  var yrN=ee.Number(yr), d=ee.Date.fromYMD(yrN,1,1), de=ee.Date.fromYMD(yrN,12,31), col=getOISSTColl(d,de);
  return ee.Image(ee.Algorithms.If(col.size().gt(3),
    col.mean().updateMask(col.mean().gt(SST_FLOOR_GLOBAL).and(col.mean().lt(40))).rename('sst'),
    ee.Image.constant(-9999).rename('sst').updateMask(ee.Image.constant(0)))).set('system:time_start',d.millis());
}));

var mStart = ee.Date('2023-01-01'), mList24 = ee.List.sequence(0,23);
function mkMoSST() {
  return ee.ImageCollection(mList24.map(function(m){
    var d=mStart.advance(m,'month'), de=d.advance(1,'month'), col=getOISSTColl(d,de);
    return ee.Image(ee.Algorithms.If(col.size().gt(0),
      col.mean().updateMask(col.mean().gt(-2).and(col.mean().lt(40)).and(oceanMask)).rename('sst'),
      ee.Image.constant(0).rename('sst').updateMask(ee.Image.constant(0)))).set('system:time_start',d.millis());
  }));
}
// v10.104 NEW: monthly Sentinel-2 FAI time series - previously S7 only ever
// had ONE fixed 2023-2024 median composite (faiImg above), never a time
// series, so applying AC1/variance/Mann-Kendall/correlation statistics to
// algae data (as opposed to SST) was not possible without this. Mirrors
// mkMoSSTRange()'s exact pattern, reusing the same fai_step constant and
// FAI expression already established above. Sentinel-2 has heavier cloud-
// masking losses than OISST (a daily gap-filled thermal product), so some
// months may come back with little or no valid data - this is a genuine,
// untested-until-now data-availability question, which is exactly what the
// S7C proof-of-concept below is for.
function mkMoFAIRange(startDateStr, nMonths) {
  var startD=ee.Date(startDateStr), monthsList=ee.List.sequence(0,nMonths-1);
  return ee.ImageCollection(monthsList.map(function(m){
    var d=startD.advance(m,'month'), de=d.advance(1,'month');
    var col=ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterDate(d,de).filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE',20)).select(['B4','B5','B8','B11']);
    var avail=col.size().gt(0);
    var meanImg=ee.Image(ee.Algorithms.If(avail,
      col.map(function(img){ return img.divide(10000); }).median(),
      ee.Image.constant(0).rename('B4').addBands(ee.Image.constant(0).rename('B5'))
        .addBands(ee.Image.constant(0).rename('B8')).addBands(ee.Image.constant(0).rename('B11'))
        .updateMask(ee.Image.constant(0))));
    var faiMonth=meanImg.expression('NIR - (RED + (SWIR - RED) * step)',
      {'NIR':meanImg.select('B8'),'RED':meanImg.select('B4'),'SWIR':meanImg.select('B11'),'step':fai_step}).rename('fai');
    return faiMonth.set('system:time_start',d.millis());
  }));
}

// ============================================================
// v10.161 FIX 19 / S4 - FAI DATA-DENSITY PRE-CHECK.
// THE PROBLEM, from a live browser run at Bocas del Toro (9.175, -81.981):
//   Study data density: 11% (0/24 BEFORE, 4/12 AFTER valid months) - INSUFFICIENT
//   Reference data density: 11% (0/24 BEFORE, 4/12 AFTER valid months) - INSUFFICIENT
// ZERO valid Sentinel-2 months in the entire 24-month BEFORE window. The
// refusal itself is correct and well explained - but it arrived only AFTER
// S7D/S7E/S7F had fired their full Earth Engine call budget (3, 3 and 6 heavy
// reduceRegions graphs over 36 monthly composites) and the user had waited out
// the run. Nothing about that site could ever have produced an answer.
//
// THE PRE-CHECK: before committing the budget, ask ONE cheap question - which
// calendar months in the requested windows have ANY Sentinel-2 scene covering
// this point at all? That is a metadata/index query over the collection's
// scene footprints and CLOUDY_PIXEL_PERCENTAGE property: one filterBounds +
// filterDate + property filter, then aggregate_array('system:time_start'),
// evaluated once. It reads no pixels, runs no reducer and touches no imagery.
//
// WHY A SCENE COUNT IS THE RIGHT PROXY, and exactly how tight it is:
// mkMoFAIRange() builds each month from
//   S2_SR_HARMONIZED.filterDate(month).filter(CLOUDY_PIXEL_PERCENTAGE<20).median()
// with NO per-pixel cloud mask. So a month whose scene list (at this point) is
// EMPTY can only produce a masked FAI - zero valid months, guaranteed - while a
// month that HAS a qualifying scene will normally produce a number. The scene
// count is therefore an UPPER BOUND on valid months that is expected to be
// tight, and it can prove INSUFFICIENCY conclusively. It CANNOT prove
// sufficiency: a scene can still be masked at the exact 150 m buffer (scene
// nodata edge, or a band mask), so passing the pre-check is not a promise that
// the run will succeed. The gate is written accordingly - it only ever refuses,
// never guarantees.
//
// COST, stated honestly: this has NOT been measured against live Earth Engine
// from this session (no EE access from the Node harness - see RESIDUAL RISK).
// What can be said from the code is structural: one extra .evaluate() of a
// metadata aggregation, against 3-6 .evaluate()s of reduceRegions over 36
// monthly median composites at 20 m. It is one additional call, and the cheapest
// kind this file makes. If it turns out to cost real time at some site, the
// remedy is to narrow filterDate, not to remove the gate.
//
// FAIL-OPEN BY DESIGN: if the pre-check errors or returns nothing, the run
// proceeds and says the pre-check did not run. A diagnostic must never be the
// thing that blocks the analysis.
var FAI_MIN_VALID_MONTHS = 4;   // the same <4-valid-months floor S7D/S7E/S7F already refuse on
var FAI_CLOUD_PCT_MAX = 20;     // must match mkMoFAIRange()'s CLOUDY_PIXEL_PERCENTAGE filter

// 'YYYY-MM-DD' + n months -> 'YYYY-MM-01'. Pure string/integer arithmetic, so
// it cannot be knocked sideways by a local timezone the way Date parsing can.
function faiAddMonthsStr(startDateStr, n){
  var y=parseInt(String(startDateStr).substring(0,4),10);
  var m=parseInt(String(startDateStr).substring(5,7),10)-1;
  if(isNaN(y)||isNaN(m)) return null;
  var tot=y*12+m+n, yy=Math.floor(tot/12), mm=tot-yy*12;
  return yy+'-'+(mm+1<10?'0':'')+(mm+1)+'-01';
}
// The list of 'YYYY-MM' keys a window covers.
function faiMonthKeys(startDateStr, nMonths){
  var keys=[];
  for(var i=0;i<nMonths;i++){
    var s2=faiAddMonthsStr(startDateStr,i);
    if(s2===null) return keys;
    keys.push(s2.substring(0,7));
  }
  return keys;
}
// ============================================================
// v10.162 S1 - ONE COMBINED BEFORE..AFTER FETCH PER SITE, SLICED CLIENT-SIDE.
// THE BLOCKER, from a live browser run at Bocas del Toro (9.175, -81.981) -
// S7D's own diagnostic line, verbatim:
//   Raw features returned: BEFORE=0 | AFTER=108 | NDVI=9
//      (expect BEFORE=216, AFTER=108, NDVI=9 if fully populated)
//   NOTE: 1 of 3 batched calls returned no usable data.
// AFTER (12 months x 9 nodes = 108) came back. BEFORE (24 months x 9 nodes =
// 216) returned ZERO features. S7D rendered anyway, on half its data. S7E and
// S7F never rendered at all: both AWAIT their BEFORE fetch, so their progress
// labels sat on "Still waiting on: BEFORE FAI series" / "Still waiting on: S7D
// BEFORE series" indefinitely. There is no timer in this sandbox, so a callback
// that never fires can never be turned into a failure.
//
// THE FIX IS STRUCTURAL, not a retry: there is no longer a separate BEFORE
// fetch to fail. Each site now fetches ONE series spanning the union of the two
// windows (BEFORE start through AFTER end, INCLUDING any gap between them), and
// the BEFORE and AFTER halves are sliced out of it CLIENT-SIDE, by real
// timestamp. Two consequences that matter:
//   1. The per-module series-fetch count HALVES (S7D 3 -> 2 calls, S7E 3 -> 2,
//      S7F 6 -> 4).
//   2. The partial-arrival deadlock is GONE by construction. One series either
//      arrives or does not; there is no state in which one window is populated
//      and a module is still waiting on the other.
// This is exactly the pattern S13 STEP 4 has used since v10.123 - fetch each
// site's raw series ONCE over the longest span needed and slice the shorter
// windows out of it - with one deliberate difference: STEP 4 can slice by array
// position (slice(0,w)) because all its windows share ONE start date, whereas
// here the two windows have DIFFERENT starts and an arbitrary gap, so the slice
// must be by real timestamp. It is.
//
// HONEST ABOUT WHAT THIS DOES NOT FIX: the combined graph is HEAVIER than
// either window alone (it spans both windows plus the gap). If the live BEFORE
// failure was caused purely by graph weight, this could fail too - but it now
// fails as a single visible refusal instead of an invisible half-run that hangs
// two other panels. That is why the span is capped (S7_COMBINED_MAX_GAP_MONTHS)
// and why each module refuses up front when the union is too wide.
// Cannot be verified without a live Earth Engine session; traced, not run.

// Cap on the EXTRA imagery the combined fetch buys compared with the two
// separate fetches it replaces. The two separate fetches covered
// beforeMonths+afterMonths composites; the combined one covers the union, so the
// overhead is exactly the GAP between the windows. A relative cap says the real
// thing directly - "never spend more than 24 months of extra imagery to save a
// call" - where an absolute month cap would silently punish long windows and
// wave through a long gap on short ones. At the shipped 24+12 defaults with the
// example dates the span is 42 against a budget of 60; at the maximum 36+36 the
// budget is 96, which allows any gap up to two years.
var S7_COMBINED_MAX_GAP_MONTHS = 24;

// 'YYYY-MM-DD' -> UTC milliseconds. Pure integer arithmetic on the string, so
// it cannot be shifted by the browser's local timezone the way Date.parse of a
// bare date string historically could be.
function ymdToUTCms(dateStr){
  var str=String(dateStr||'');
  var y=parseInt(str.substring(0,4),10);
  var m=parseInt(str.substring(5,7),10)-1;
  var d=parseInt(str.substring(8,10),10);
  if(isNaN(y)||isNaN(m)) return null;
  if(isNaN(d)||d<1) d=1;
  return Date.UTC(y,m,d);
}
// ms + n whole months, clamping the day-of-month to the target month's length -
// the same convention ee.Date().advance(n,'month') uses. A plain
// setUTCMonth(+1) on 31 January OVERFLOWS to 2/3 March; this does not.
function addMonthsUTCms(ms, n){
  if(ms===null||ms===undefined||isNaN(ms)) return null;
  var d=new Date(ms), y=d.getUTCFullYear(), m=d.getUTCMonth(), day=d.getUTCDate();
  var tot=y*12+m+n, yy=Math.floor(tot/12), mm=tot-yy*12;
  var lastDay=new Date(Date.UTC(yy,mm+1,0)).getUTCDate();
  return Date.UTC(yy, mm, Math.min(day,lastDay), d.getUTCHours(), d.getUTCMinutes(), d.getUTCSeconds());
}
// Given the two windows, describe the ONE monthly collection that covers both.
// Returns {startDateStr, nMonths, startMs, endMs, spanMonths, tooWide} or null
// if a date could not be parsed. nMonths carries one month of deliberate slack
// past the later window's end: mkMoFAIRange() anchors its monthly grid on the
// EARLIER window's day-of-month, so when the two starts fall on different days
// of the month the later window's last composite can sit one grid step beyond
// the plain month difference. One spare composite costs one month of imagery
// and removes an off-by-one that would otherwise silently shorten a window.
function combinedWindowSpan(beforeStart, beforeMonths, afterStart, afterMonths){
  var bS=ymdToUTCms(beforeStart), aS=ymdToUTCms(afterStart);
  if(bS===null||aS===null) return null;
  var bE=addMonthsUTCms(bS,beforeMonths), aE=addMonthsUTCms(aS,afterMonths);
  var startMs=Math.min(bS,aS), endMs=Math.max(bE,aE);
  var startStr=(bS<=aS)?beforeStart:afterStart;
  var sD=new Date(startMs), eD=new Date(endMs);
  var monthDiff=(eD.getUTCFullYear()-sD.getUTCFullYear())*12 + (eD.getUTCMonth()-sD.getUTCMonth());
  var nMonths=Math.max(beforeMonths, afterMonths, monthDiff+1);
  // +1 for the deliberate slack composite nMonths carries (see above).
  var budget=beforeMonths+afterMonths+S7_COMBINED_MAX_GAP_MONTHS+1;
  return {startDateStr:startStr, nMonths:nMonths, startMs:startMs, endMs:endMs,
          spanMonths:nMonths, budgetMonths:budget, tooWide:(nMonths>budget)};
}
// Select the entries of a combined {t,v} series that fall inside one window,
// BY REAL TIMESTAMP - never by array position. The window is the half-open
// interval [start, start + nMonths months), which contains exactly one point of
// a monthly grid per month regardless of where the grid is anchored.
function sliceSeriesByWindow(seriesTV, startDateStr, nMonths){
  var s=ymdToUTCms(startDateStr);
  if(s===null) return [];
  var e=addMonthsUTCms(s,nMonths);
  var out=[];
  (seriesTV||[]).forEach(function(pt){
    if(!pt) return;
    var t=pt.t;
    if(t===null||t===undefined||isNaN(t)) return;
    if(t>=s && t<e) out.push(pt);
  });
  out.sort(function(a,b){ return a.t-b.t; });
  return out;
}
// Slice a whole groupSeriesByLabel() result at once: {label:[{t,v}..]} in,
// {label:[{t,v}..]} out, one window's worth per label.
function sliceSeriesMapByWindow(byLabel, startDateStr, nMonths){
  var out={};
  if(!byLabel) return out;
  Object.keys(byLabel).forEach(function(k){
    out[k]=sliceSeriesByWindow(byLabel[k], startDateStr, nMonths);
  });
  return out;
}
// Up-front refusal, BEFORE any Earth Engine call is spent: is the union of the
// two windows narrow enough for one combined fetch to be worth making? Returns
// null when the run may proceed, otherwise the message to show. Called by S7D,
// S7E and S7F from their existing input-validation blocks.
function combinedSpanRefusal(span, beforeMonths, afterMonths){
  if(!span) return 'Could not parse one of the BEFORE/AFTER start dates - use YYYY-MM-DD.';
  if(!span.tooWide) return null;
  return 'BEFORE and AFTER are too far apart. v10.162 fetches ONE combined series spanning '+
    'BEFORE-start through AFTER-end (including the gap) and slices the two windows out of it client-side, '+
    'which halves the Earth Engine call count. Your two windows ('+beforeMonths+'mo + '+afterMonths+
    'mo) span '+span.spanMonths+' months end to end, against a budget of '+span.budgetMonths+' ('+beforeMonths+'+'+afterMonths+
    ' window months, at most '+S7_COMBINED_MAX_GAP_MONTHS+' months of gap, and 1 alignment month). Beyond that the single combined fetch '+
    'buys more extra imagery than the call it saves is worth, so it is refused rather than silently spent. '+
    'Move the two windows closer together, or shorten them.';
}

// The refusal text a module shows when the ONE combined fetch came back but did
// not actually cover one of the two windows. Deliberately reuses the existing
// insufficient-data wording rather than inventing a new failure vocabulary, so
// the user sees the same sentence they would have seen from a short fetch.
// minPerWindow is the <4-valid-months floor S7C-S7F already refuse on.
function combinedSliceShortfall(beforeTV, afterTV, minPerWindow){
  var need=(minPerWindow===undefined||minPerWindow===null)?FAI_MIN_VALID_MONTHS:minPerWindow;
  var nB=(beforeTV||[]).length, nA=(afterTV||[]).length;
  if(nB>=need && nA>=need) return null;
  return 'INSUFFICIENT DATA - the single combined BEFORE..AFTER fetch returned, but it does not cover '+
    'both windows: '+nB+' month(s) landed in the BEFORE window and '+nA+' in the AFTER window, against a '+
    'floor of '+need+' each. v10.162 replaced the two separate fetches with one combined fetch sliced by '+
    'real timestamp, so this is a refusal, NOT a module left waiting on a call that never returns.';
}

// Pure, unit-testable half of the pre-check: given the raw scene timestamps
// Earth Engine returned and the requested windows, how many months of each
// window have at least one qualifying scene? Split out from the async wrapper
// so the decision logic can be tested in Node without an EE session.
function faiPrecheckSummary(tsArr, windows, refuseBelow, warnBelow){
  var seen={}, j;
  for(j=0;j<tsArr.length;j++){
    var dObj=new Date(tsArr[j]);
    var mo=dObj.getUTCMonth()+1;
    var key=dObj.getUTCFullYear()+'-'+(mo<10?'0':'')+mo;
    seen[key]=(seen[key]||0)+1;
  }
  var sums=[], anyRefuse=false, anyWarn=false, detail=[], w2, q;
  for(w2=0; w2<windows.length; w2++){
    var keys=faiMonthKeys(windows[w2].start, windows[w2].months), n=0;
    for(q=0;q<keys.length;q++){ if(seen[keys[q]]) n++; }
    sums.push({name:windows[w2].name, n:n, months:windows[w2].months});
    detail.push(windows[w2].name+' '+n+' of '+windows[w2].months+' months');
    if(n<refuseBelow) anyRefuse=true;
    else if(n<warnBelow) anyWarn=true;
  }
  return {sums:sums, anyRefuse:anyRefuse, anyWarn:anyWarn, detailTxt:detail.join(' | ')};
}
// cfg: {lat, lon, moduleName, statusLbl, windows:[{name,start,months}],
//       refuseBelow (default FAI_MIN_VALID_MONTHS), warnBelow (default same),
//       cannotRunTxt}
// Calls onPass(preInfo) if and only if the run should go ahead. preInfo.note is
// a one-or-two-line string the caller should show with its results.
function faiPrecheckThenRun(cfg, onPass){
  var lbl=cfg.statusLbl, mod=cfg.moduleName||'S7', wins=cfg.windows||[];
  var refuseBelow=(cfg.refuseBelow===undefined)?FAI_MIN_VALID_MONTHS:cfg.refuseBelow;
  var warnBelow=(cfg.warnBelow===undefined)?FAI_MIN_VALID_MONTHS:cfg.warnBelow;
  function proceed(info){ try{ onPass(info); }catch(eOn){ print('=== '+mod+' run error after pre-check === '+eOn); } }
  var lo=null, hi=null, wi;
  for(wi=0; wi<wins.length; wi++){
    var a=faiAddMonthsStr(wins[wi].start,0), b=faiAddMonthsStr(wins[wi].start,wins[wi].months);
    if(a===null||b===null){ proceed({skipped:true, note:'FAI PRE-CHECK skipped: could not parse a window start date.'}); return; }
    if(lo===null||a<lo) lo=a;
    if(hi===null||b>hi) hi=b;
  }
  if(lo===null){ proceed({skipped:true, note:'FAI PRE-CHECK skipped: no windows given.'}); return; }
  var req;
  try{
    req = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(ee.Geometry.Point([cfg.lon, cfg.lat]))
      .filterDate(ee.Date(lo), ee.Date(hi))
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', FAI_CLOUD_PCT_MAX))
      .aggregate_array('system:time_start');
  } catch(ePreBuild){
    print('=== '+mod+' FAI pre-check could not be built === '+ePreBuild);
    proceed({skipped:true, note:'FAI PRE-CHECK skipped (could not be built) - the full run proceeded without it.'});
    return;
  }
  // The module's own `resultV.setValue('')` sits inside the body this gate can
  // refuse to enter, so the gate clears it here. Without this a refusal would
  // leave the PREVIOUS run's full result table on screen underneath it - the
  // same stale-render class this fix is about.
  if(cfg.resultLbl) cfg.resultLbl.setValue('');
  if(lbl){
    lbl.setValue(mod+' FAI PRE-CHECK: 1 cheap Earth Engine metadata call (Sentinel-2 scene index at this\n'+
      'point, '+lo.substring(0,7)+' to '+hi.substring(0,7)+', cloud < '+FAI_CLOUD_PCT_MAX+'%) BEFORE spending the full call budget.\n'+
      'If this site cannot clear '+refuseBelow+' valid months per window, you will be told now instead of\n'+
      'after the wait.');
    lbl.style().set('color','#334466'); lbl.style().set('backgroundColor','#eeeeee');
    lbl.style().set('border','2px solid #aaaaaa'); lbl.style().set('whiteSpace','pre'); lbl.style().set('fontWeight','bold');
  }
  req.evaluate(function(tsArr, ePre){
    if(ePre || !tsArr || typeof tsArr.length!=='number'){
      print('=== '+mod+' FAI pre-check unavailable === '+(ePre||'no scene list returned'));
      proceed({skipped:true, note:'FAI PRE-CHECK: did not run ('+(ePre?'Earth Engine error':'no scene list returned')+
        ') - the full run went ahead without it. A refusal below, if any, is the post-hoc one.'});
      return;
    }
    var summary=faiPrecheckSummary(tsArr, wins, refuseBelow, warnBelow);
    var sums=summary.sums, anyRefuse=summary.anyRefuse, anyWarn=summary.anyWarn, detailTxt=summary.detailTxt;
    if(anyRefuse){
      var msg=mod+' CANNOT RUN AT THIS SITE/WINDOW - refused BEFORE spending the Earth Engine call budget.\n'+
        'Sentinel-2 scene availability at '+cfg.lat.toFixed(4)+', '+cfg.lon.toFixed(4)+' (cloud < '+FAI_CLOUD_PCT_MAX+'%):\n'+
        '  '+detailTxt+'\n'+
        'The FAI statistics need at least '+refuseBelow+' valid months in EACH window. A month with no\n'+
        'qualifying Sentinel-2 scene over this point cannot produce a valid FAI value, so the\n'+
        'window(s) above cannot reach that floor however long the run takes. '+
        (cfg.cannotRunTxt||('So '+mod+' cannot run here.'))+'\n'+
        'WHAT TO CHANGE: move the window(s) to a period with scenes, or pick a less persistently\n'+
        'cloudy site. This is a real property of the satellite record here, not a tool failure.\n'+
        'NOTE ON THIS CHECK: it counts SCENES, which is an upper bound on valid months (mkMoFAIRange\n'+
        'applies no per-pixel cloud mask, so it is normally a tight one). It can prove that a window\n'+
        'is insufficient; it never promises that a passing window will succeed.';
      if(lbl){
        lbl.setValue(msg);
        lbl.style().set('color','#cc0000'); lbl.style().set('backgroundColor','#ffd0d0');
        lbl.style().set('border','2px solid #cc0000'); lbl.style().set('whiteSpace','pre'); lbl.style().set('fontWeight','bold');
      }
      print('=== '+mod+' FAI PRE-CHECK REFUSAL ==='); print(msg);
      return;
    }
    proceed({skipped:false, refused:false, warn:anyWarn, sums:sums,
      note:'FAI PRE-CHECK (1 metadata call, before the run): Sentinel-2 scene-months at this point, '+
        'cloud < '+FAI_CLOUD_PCT_MAX+'% - '+detailTxt+'. Upper bound on valid months; the figures below are '+
        'the real counts.'+(anyWarn?' MARGINAL: at least one window is close to the '+warnBelow+
        '-valid-month floor, so expect NOT TESTABLE results.':'')});
  });
}

function mkMoSSTRange(startDateStr, nMonths) {
  var startD=ee.Date(startDateStr), monthsList=ee.List.sequence(0,nMonths-1);
  return ee.ImageCollection(monthsList.map(function(m){
    var d=startD.advance(m,'month'), de=d.advance(1,'month'), col=getOISSTColl(d,de);
    return ee.Image(ee.Algorithms.If(col.size().gt(0),
      col.mean().updateMask(col.mean().gt(-2).and(col.mean().lt(40)).and(oceanMask)).rename('sst'),
      ee.Image.constant(0).rename('sst').updateMask(ee.Image.constant(0)))).set('system:time_start',d.millis());
  }));
}
function mkMoCHL() {
  return ee.ImageCollection(mList24.map(function(m){
    var d=mStart.advance(m,'month'), de=d.advance(1,'month');
    var col=ee.ImageCollection('COPERNICUS/MARINE/SATELLITE_OCEAN_COLOR/V6').filterDate(d,de).select('chlor_a');
    return ee.Image(ee.Algorithms.If(col.size().gt(0),
      col.mean().updateMask(col.mean().gt(0).and(oceanMask)).rename('chlor_a'),
      ee.Image.constant(0).rename('chlor_a').updateMask(ee.Image.constant(0)))).set('system:time_start',d.millis());
  }));
}
function mkMoDHW() {
  return ee.ImageCollection(mList24.map(function(m){
    var d=mStart.advance(m,'month'), de=d.advance(1,'month'), col=getOISSTColl(d,de);
    return ee.Image(ee.Algorithms.If(col.size().gt(0),
      col.max().subtract(MMM_perpixel.add(1)).max(0).multiply(4.33).updateMask(oceanMask).rename('dhw'),
      ee.Image.constant(0).rename('dhw').updateMask(ee.Image.constant(0)))).set('system:time_start',d.millis());
  }));
}
function mkMoNO2() {
  return ee.ImageCollection(mList24.map(function(m){
    var d=mStart.advance(m,'month'), de=d.advance(1,'month');
    var col=ee.ImageCollection('COPERNICUS/S5P/NRTI/L3_NO2').filterDate(d,de).select('NO2_column_number_density')
      .merge(ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2').filterDate(d,de).select('NO2_column_number_density'));
    return ee.Image(ee.Algorithms.If(col.size().gt(0),
      col.mean().updateMask(col.mean().gt(0)).rename('NO2_column_number_density'),
      ee.Image.constant(0).rename('NO2_column_number_density').updateMask(ee.Image.constant(0)))).set('system:time_start',d.millis());
  }));
}

function computeRealCSD(monthlyColl, study, bandName, scale) {
  var valsFC = ee.FeatureCollection(monthlyColl.map(function(img){
    var v = img.reduceRegion({reducer:ee.Reducer.mean(),geometry:study,scale:scale,maxPixels:1e9}).get(bandName);
    return ee.Feature(null, {v:v, t:img.get('system:time_start')});
  })).sort('t');
  var validVals = valsFC.aggregate_array('v').removeAll([null]);
  var nValid = validVals.size();
  return ee.Algorithms.If(nValid.gte(4),
    (function(){
      var arr=ee.Array(validVals), idxArr=ee.Array(ee.List.sequence(0,nValid.subtract(1)));
      var meanIdx=idxArr.reduce(ee.Reducer.mean(),[0]).get([0]), meanVal=arr.reduce(ee.Reducer.mean(),[0]).get([0]);
      var idxDev=idxArr.subtract(meanIdx), valDev=arr.subtract(meanVal);
      var cov=idxDev.multiply(valDev).reduce(ee.Reducer.sum(),[0]).get([0]);
      var varIdx=idxDev.pow(2).reduce(ee.Reducer.sum(),[0]).get([0]);
      var slope=ee.Number(cov).divide(ee.Number(varIdx));
      var intercept=ee.Number(meanVal).subtract(slope.multiply(meanIdx));
      var trendArr=idxArr.multiply(slope).add(intercept), residArr=arr.subtract(trendArr);
      var n=nValid;
      var resid0=residArr.slice(0,0,n.subtract(1)), resid1=residArr.slice(0,1,n);
      var mean0=resid0.reduce(ee.Reducer.mean(),[0]).get([0]), mean1=resid1.reduce(ee.Reducer.mean(),[0]).get([0]);
      var dev0=resid0.subtract(mean0), dev1=resid1.subtract(mean1);
      var num=dev0.multiply(dev1).reduce(ee.Reducer.sum(),[0]).get([0]);
      var den0=ee.Number(dev0.pow(2).reduce(ee.Reducer.sum(),[0]).get([0])).sqrt();
      var den1=ee.Number(dev1.pow(2).reduce(ee.Reducer.sum(),[0]).get([0])).sqrt();
      var realAC1=ee.Number(num).divide(den0.multiply(den1).max(1e-6));
      var half=n.divide(2).floor();
      var firstHalf=residArr.slice(0,0,half), secondHalf=residArr.slice(0,half,n);
      var varFirst=ee.Number(firstHalf.reduce(ee.Reducer.sampleVariance(),[0]).get([0]));
      var varSecond=ee.Number(secondHalf.reduce(ee.Reducer.sampleVariance(),[0]).get([0]));
      var varTrendRatio=varSecond.divide(varFirst.max(1e-6));
      // v10.88 NEW: skewness of the detrended residuals - a third classic
      // EWS indicator alongside AC1 and variance (Dakos et al. 2012 generic
      // early-warning-signal toolkit). Its DIRECTION of change is
      // system-dependent (unlike AC1/variance, which both rise consistently
      // near a fold bifurcation), so it is reported for the toolkit but not
      // auto-scored as "CSD-consistent" in either direction.
      var meanResidAll=residArr.reduce(ee.Reducer.mean(),[0]).get([0]);
      var stdAll=ee.Number(residArr.reduce(ee.Reducer.sampleVariance(),[0]).get([0])).max(1e-9).sqrt();
      var cubedDev=residArr.subtract(meanResidAll).pow(3);
      var meanCubed=cubedDev.reduce(ee.Reducer.mean(),[0]).get([0]);
      var skewness=ee.Number(meanCubed).divide(stdAll.pow(3).max(1e-9));
      return ee.Dictionary({realAC1:realAC1,varFirstHalf:varFirst,varSecondHalf:varSecond,
        varTrendRatio:varTrendRatio,trendSlope:slope,nValidMonths:n,skewness:skewness});
    })(),
    ee.Dictionary({realAC1:null,varFirstHalf:null,varSecondHalf:null,varTrendRatio:null,trendSlope:null,nValidMonths:nValid,skewness:null}));
}

// v10.150 FIX: computeRealCSD() above never deseasonalizes before computing
// AC1/variance server-side via ee.Array - the same confirmed structural gap
// as jsNodeStats(). Rather than write new, untested EE ee.Array grouping-
// by-calendar-month logic (which cannot be verified without a live GEE
// session), this converts to the SAME "fetch raw values once via one real
// EE call, then compute everything client-side" pattern this file's own
// v10.107 comments already document as proven-safe (used for S7D's
// rebuild). This is a genuine interface change - a callback instead of a
// returned ee.Dictionary - since it needs a real round trip before it can
// compute anything. Reuses jsNodeStatsFixed() (the already-validated,
// deseasonalizing-first function above) for all the actual math, so both
// server-side and client-side callers now get identical, correct
// statistics from one single, tested implementation.
// v10.151 FIX 4: now returns the raw {t,v} series alongside the stats, so
// COMPARE can pool BEFORE + AFTER into ONE climatology and recompute both
// windows consistently. Without this, STEP 2's two windows are
// deseasonalized independently and their delta is not like-for-like.
// Optional 6th arg passes a shared climatology straight through.
function computeRealCSDDeseasonalized(monthlyColl, study, bandName, scale, onDone, sharedClimatology) {
  var valsFC = ee.FeatureCollection(monthlyColl.map(function(img) {
    var v = img.reduceRegion({reducer: ee.Reducer.mean(), geometry: study, scale: scale, maxPixels: 1e9}).get(bandName);
    return ee.Feature(null, {v: v, t: img.get('system:time_start')});
  })).sort('t');

  valsFC.evaluate(function(fcResult, err) {
    if (err) { onDone({error: String(err)}); return; }
    var feats = (fcResult && fcResult.features) ? fcResult.features : [];
    var seriesTV = feats.map(function(f) { return {t: f.properties.t, v: f.properties.v}; });
    var result = jsNodeStatsFixed(seriesTV, sharedClimatology);
    result.seriesTV = seriesTV;   // v10.151: carried through for pooling
    onDone(result);
  });
}

// v10.96 NEW: the actual Dakos et al. 2012 sliding-window method, as
// opposed to the discrete BEFORE/AFTER chunk comparisons used elsewhere in
// S13. Instead of cutting the series into isolated blocks and asking a
// pass/fail question about each one, this detrends the WHOLE requested
// series ONCE (same linear-detrend approach as computeRealCSD - see the
// disclosed simplification note in the UI: Dakos et al.'s own toolbox
// typically uses Gaussian kernel smoothing instead of a single linear
// detrend, which is a more flexible but heavier method not implemented
// here), then slides a fixed-size window forward ONE MONTH AT A TIME across
// the residuals, computing AC1 and variance at every position. This
// produces a continuous AC1(t)/variance(t) trajectory rather than a single
// number, which is what actually lets a trend "build up" visibly instead
// of being judged by an arbitrary chunk boundary.
// Built as ONE server-side ee.List.map() graph (not N separate calls), so
// the whole scan costs a single .evaluate() round trip regardless of how
// many window positions it contains.
function computeSlidingWindowCSD(monthlyColl, study, bandName, scale, windowSize) {
  var valsFC = ee.FeatureCollection(monthlyColl.map(function(img){
    var v = img.reduceRegion({reducer:ee.Reducer.mean(),geometry:study,scale:scale,maxPixels:1e9}).get(bandName);
    return ee.Feature(null, {v:v, t:img.get('system:time_start')});
  })).sort('t');
  var validFC = valsFC.filter(ee.Filter.notNull(['v']));
  var validVals = validFC.aggregate_array('v');
  var validTimes = validFC.aggregate_array('t');
  var nValid = validVals.size();
  var W = ee.Number(windowSize);
  return ee.Algorithms.If(nValid.gte(W).and(W.gte(4)),
    (function(){
      var arr = ee.Array(validVals);
      var idxArr = ee.Array(ee.List.sequence(0, nValid.subtract(1)));
      // Single global linear detrend over the WHOLE valid series (same
      // method as computeRealCSD, applied once here instead of per-chunk).
      var meanIdx = idxArr.reduce(ee.Reducer.mean(),[0]).get([0]);
      var meanVal = arr.reduce(ee.Reducer.mean(),[0]).get([0]);
      var idxDev = idxArr.subtract(meanIdx), valDev = arr.subtract(meanVal);
      var cov = idxDev.multiply(valDev).reduce(ee.Reducer.sum(),[0]).get([0]);
      var varIdx = idxDev.pow(2).reduce(ee.Reducer.sum(),[0]).get([0]);
      var slope = ee.Number(cov).divide(ee.Number(varIdx));
      var intercept = ee.Number(meanVal).subtract(slope.multiply(meanIdx));
      var trendArr = idxArr.multiply(slope).add(intercept);
      var residArr = arr.subtract(trendArr);

      var nWindows = nValid.subtract(W).add(1);
      var windowStarts = ee.List.sequence(0, nWindows.subtract(1));

      var windowResults = windowStarts.map(function(wi){
        wi = ee.Number(wi);
        var winResid = residArr.slice(0, wi, wi.add(W));
        var n = W;
        var resid0 = winResid.slice(0,0,n.subtract(1));
        var resid1 = winResid.slice(0,1,n);
        var mean0 = resid0.reduce(ee.Reducer.mean(),[0]).get([0]);
        var mean1 = resid1.reduce(ee.Reducer.mean(),[0]).get([0]);
        var dev0 = resid0.subtract(mean0), dev1 = resid1.subtract(mean1);
        var num = dev0.multiply(dev1).reduce(ee.Reducer.sum(),[0]).get([0]);
        var den0 = ee.Number(dev0.pow(2).reduce(ee.Reducer.sum(),[0]).get([0])).sqrt();
        var den1 = ee.Number(dev1.pow(2).reduce(ee.Reducer.sum(),[0]).get([0])).sqrt();
        var winAC1 = ee.Number(num).divide(den0.multiply(den1).max(1e-6));
        var winVar = winResid.reduce(ee.Reducer.sampleVariance(),[0]).get([0]);
        var endIdx = wi.add(W).subtract(1);
        var endTime = ee.Number(validTimes.get(endIdx));
        return ee.Feature(null, {windowIdx:wi, ac1:winAC1, variance:winVar, endTime:endTime});
      });
      return ee.FeatureCollection(windowResults).sort('windowIdx');
    })(),
    ee.FeatureCollection([]));
}

// Standard normal CDF approximation (Abramowitz & Stegun 26.2.17), used by
// the Mann-Kendall significance test below. Accurate to ~7.5e-8.
function normalCDF(z) {
  var t = 1 / (1 + 0.2316419 * Math.abs(z));
  var d = 0.3989423 * Math.exp(-z*z/2);
  var p = d*t*(0.3193815+t*(-0.3565638+t*(1.781478+t*(-1.821256+t*1.330274))));
  return z > 0 ? 1 - p : p;
}

// Kendall's tau + the Mann-Kendall trend significance test - the exact
// statistic Dakos et al. use to ask "is this metric moving in one direction
// consistently over time, or just bouncing randomly?" Runs client-side in
// plain JS on the (small, already-evaluated) sliding-window results, so it
// needs no extra Earth Engine calls.
//
// v10.156 BUG-02 FIX: this used to use ONLY the normal approximation for the
// S-statistic's variance, which reports arithmetically IMPOSSIBLE p-values at
// small n. At n=4 with tau=+1 it returned p=0.0416 - but with only 4!=24
// orderings the SMALLEST two-sided p that can exist at n=4 is 2/24=0.0833, so
// it was claiming significance where significance cannot be attained. (It also
// erred the other way in the far tail: n=7 tau=+1 returned 0.0016 when the
// exact answer is 0.0004.) Now computes the EXACT null distribution of S for
// small, untied samples, and adds the standard tie correction + continuity
// correction to the approximation branch it falls back to.
//
// mkExactTailP: exact P(S >= absS) under the null, via the standard Mahonian
// (inversion-count) recursion - the number of permutations of n items with
// exactly q inversions. S = nPairs - 2*inversions, so the S-tail is an
// inversion-count tail. Each step convolves the running count with a window of
// i ones, done here as a sliding sum, so the whole thing is O(n^3) on numbers
// no bigger than 45 - trivially cheap at the n<=10 it is used for. Validated
// against brute-force enumeration of all n! orderings for n=4..8: exact match
// (max abs error 0.0e+0).
var MK_EXACT_MAX_N = 10;
function mkExactTailP(n, absS) {
  var maxInv = n*(n-1)/2;
  var c = [1];
  for (var i = 2; i <= n; i++) {
    var next = [], run = 0;
    for (var q = 0; q <= maxInv; q++) {
      run += (q < c.length ? c[q] : 0);
      if (q-i >= 0) run -= (q-i < c.length ? c[q-i] : 0);
      next.push(run);
    }
    c = next;
  }
  var total = 1;
  for (var f = 2; f <= n; f++) total *= f;
  var cut = Math.floor((maxInv - absS)/2), cum = 0;
  for (var q3 = 0; q3 <= cut && q3 <= maxInv; q3++) cum += c[q3];
  return cum/total;
}
function mannKendallTest(values) {
  var clean = [];
  for (var i = 0; i < values.length; i++) {
    if (values[i] !== null && values[i] !== undefined && !isNaN(values[i])) clean.push(values[i]);
  }
  var n = clean.length;
  if (n < 4) return {tau:null, S:null, z:null, p:null, n:n, method:null, nTieGroups:0, error:'insufficient points (n='+n+')'};
  var S = 0, nTiedPairs = 0;
  for (var a = 0; a < n-1; a++) {
    for (var b = a+1; b < n; b++) {
      var diff = clean[b] - clean[a];
      if (diff > 0) S++;
      else if (diff < 0) S--;
      else nTiedPairs++;
    }
  }
  var nPairs = n*(n-1)/2;
  var tau = S / nPairs;
  var varS0 = n*(n-1)*(2*n+5)/18;
  // EXACT branch - only valid with no ties, and only worth it at small n
  if (nTiedPairs === 0 && n <= MK_EXACT_MAX_N) {
    var pEx = 2*mkExactTailP(n, Math.abs(S));
    if (pEx > 1) pEx = 1;
    return {tau:tau, S:S, z:(varS0>0?S/Math.sqrt(varS0):0), p:pEx, n:n,
      method:'exact', nTieGroups:0, error:null};
  }
  // NORMAL branch - now WITH the standard tie correction (previously missing):
  // varS = [n(n-1)(2n+5) - SUM_ties t(t-1)(2t+5)] / 18
  var sorted = clean.slice().sort(function(x,y){ return x-y; });
  var tieTerm = 0, nTieGroups = 0, runLen = 1;
  for (var s2 = 1; s2 <= n; s2++) {
    if (s2 < n && sorted[s2] === sorted[s2-1]) { runLen++; }
    else { if (runLen > 1) { tieTerm += runLen*(runLen-1)*(2*runLen+5); nTieGroups++; } runLen = 1; }
  }
  var varS = (n*(n-1)*(2*n+5) - tieTerm)/18;
  // standard Mann-Kendall continuity correction
  var z = 0;
  if (varS > 0) { if (S > 0) z = (S-1)/Math.sqrt(varS); else if (S < 0) z = (S+1)/Math.sqrt(varS); }
  var p = 2*(1-normalCDF(Math.abs(z)));
  if (p > 1) p = 1;
  return {tau:tau, S:S, z:z, p:p, n:n, method:'normal', nTieGroups:nTieGroups, error:null};
}
// v10.156 BUG-02: short, readable tag so every on-screen Mann-Kendall verdict
// says WHICH null distribution produced its p-value, and (for the exact branch)
// what the smallest attainable p at that n actually is - so a reader can tell
// "not significant" from "cannot possibly be significant at this sample size".
function mkMethodTxt(t){
  if(!t || t.method===null || t.method===undefined) return '';
  if(t.method==='exact'){
    var f=1; for(var i=2;i<=t.n;i++) f*=i;
    return ' [exact null, min attainable p='+(2/f).toFixed(4)+']';
  }
  return ' [normal approx'+(t.nTieGroups>0?', tie-corrected, '+t.nTieGroups+' tie group(s)':'')+']';
}
// v10.129 NEW: non-overlapping-window trajectory builder, for a
// METHODOLOGICALLY VALID Mann-Kendall test. mannKendallTest()'s p-value
// formula (varS = n*(n-1)*(2n+5)/18) assumes independent observations -
// but the sliding-window trajectory above steps ONE MONTH AT A TIME
// (windowSize-1 months shared between consecutive positions), which
// makes it artificially autocorrelated and violates that assumption.
// Confirmed as a real problem, not theoretical: tested directly on pure
// random noise with zero real trend - the overlapping version reported
// p<0.0001 ("significant"), while non-overlapping windows correctly
// reported p=0.109 ("not significant"). Same fix already built and
// validated in the companion Python deseasonalizing script this session.
// Uses entirely fresh, non-shared months per window - far fewer points,
// but each one is a genuinely independent sample, so its p-value can
// actually be trusted.
function computeNonOverlappingTrajectory(values, windowSize) {
  var out = [];
  // v10.158 W-20 FIX: windowSize 0 (or negative, or non-numeric) made this an
  // INFINITE loop - `i += 0` never advances and `i+0 <= length` never becomes
  // false. Confirmed by direct test: the call hangs and never returns. In the
  // GEE code editor that locks the browser tab with no error message at all,
  // which is the worst possible failure mode for a UI callback. Any window
  // size below 1 is meaningless, so it returns an empty trajectory instead.
  if (!values || !values.length) return out;
  windowSize = Math.floor(windowSize);
  if (!isFinite(windowSize) || isNaN(windowSize) || windowSize < 1) return out;
  for (var i = 0; i+windowSize <= values.length; i += windowSize) {
    var chunk = values.slice(i, i+windowSize);
    var s = jsNodeStats(chunk);
    if (s.realAC1 !== null) out.push({ac1:s.realAC1, variance:s.varTrendRatio});
  }
  return out;
}

// v10.107 NEW: client-side (plain JS) equivalents of the same statistics
// computeRealCSD/computeZonalSyncCSD compute server-side via ee.Array. Used
// to move S7D's math OFF the server: instead of firing ~43 separate
// .evaluate() calls (one full server-side graph evaluation per node per
// period), fetch ALL nodes' raw monthly values in just 2-3 batched calls
// (via reduceRegions()+flatten(), the same "fetch once, compute locally"
// pattern already proven safe for the STEP 5 sliding-window feature's
// Mann-Kendall test), then run this exact math on the small resulting
// array in JS. Formulas are identical to the EE versions - only WHERE the
// arithmetic runs has changed, not what it computes.
function jsLinearDetrendResiduals(values) {
  var n = values.length;
  if (n < 4) return null;
  var meanIdx = (n-1)/2, meanVal = 0;
  for (var i=0;i<n;i++) meanVal += values[i];
  meanVal = meanVal/n;
  var cov=0, varIdx=0;
  for (var i=0;i<n;i++){ cov += (i-meanIdx)*(values[i]-meanVal); varIdx += (i-meanIdx)*(i-meanIdx); }
  var slope = varIdx>0 ? cov/varIdx : 0;
  var intercept = meanVal - slope*meanIdx;
  var resid = [];
  for (var i=0;i<n;i++) resid.push(values[i] - (slope*i+intercept));
  return resid;
}
// v10.158 W-02 FIX: months-since-epoch index, so "is this pair really one
// month apart?" is a subtraction rather than a guess from array position.
function monthIndexFromT(t){
  var d = new Date(t);
  return d.getUTCFullYear()*12 + d.getUTCMonth();
}
// v10.158 W-02 FIX (BLOCKER) - LAG-1 AC1 WAS COMPUTED OVER NON-ADJACENT MONTHS
// deseasonalizeSeries() returns {t,v:null} for any month whose calendar month
// missed the >=3-samples climatology floor (v10.151 FIX 2), and every caller
// then FILTERED those out and handed the survivors here as a plain array. This
// function paired ARRAY-adjacent survivors and called the result a lag-1
// autocorrelation. Measured on a clean 28-month synthetic series: 12 of 28
// months survived and 2 of the 11 "lag-1" pairs were 9 REAL MONTHS apart; at
// n=26 it was 6 survivors, 2 of 5 pairs 11 months apart; at n=30, gaps of 7.
// The result was returned as deseasonalized:true with no warning - a p-value
// describing a statistic nobody defined.
// FIX: an OPTIONAL second argument carries the timestamps parallel to resid.
// When supplied, only pairs that are genuinely one calendar month apart are
// used; everything else is skipped. Callers that legitimately have no
// meaningful time order (the shuffled null distributions inside the
// permutation tests, where the whole point is that order is destroyed) pass
// nothing and get the original behaviour unchanged, so the null and the
// observed statistic are still computed the same way on the same pairs.
// Companion jsLag1PairAudit() below reports what a timestamped series would
// lose, so a caller can refuse rather than report a gap-contaminated number.
function jsLag1AC1(resid, times) {
  var n = resid.length;
  if (n<4) return null;
  var useT = !!(times && times.length===n);
  var r0 = [], r1 = [];
  for (var i=0;i<n-1;i++){
    if (useT && (monthIndexFromT(times[i+1]) - monthIndexFromT(times[i])) !== 1) continue;
    r0.push(resid[i]); r1.push(resid[i+1]);
  }
  // 3 pairs is what the original n>=4 check guaranteed on a gapless series;
  // keep that as the floor rather than reporting an AC1 off one or two pairs.
  if (r0.length < 3) return null;
  var m0=0, m1=0;
  for (var i=0;i<r0.length;i++){ m0+=r0[i]; m1+=r1[i]; }
  m0=m0/r0.length; m1=m1/r1.length;
  var num=0, den0=0, den1=0;
  for (var i=0;i<r0.length;i++){
    num += (r0[i]-m0)*(r1[i]-m1);
    den0 += (r0[i]-m0)*(r0[i]-m0);
    den1 += (r1[i]-m1)*(r1[i]-m1);
  }
  var denom = Math.sqrt(den0)*Math.sqrt(den1);
  return denom>1e-6 ? num/denom : 0;
}
// v10.158 W-02: how many array-adjacent pairs are NOT real lag-1 pairs, and
// how far apart the worst one is. Used to disclose (or refuse) rather than
// silently report a lag-1 statistic computed across holes.
function jsLag1PairAudit(times){
  var out = {nPairs:0, nAdjacent:0, nNonAdjacent:0, maxGapMonths:0};
  if(!times || times.length<2) return out;
  for(var i=1;i<times.length;i++){
    var gap = monthIndexFromT(times[i]) - monthIndexFromT(times[i-1]);
    out.nPairs++;
    if(gap===1) out.nAdjacent++; else { out.nNonAdjacent++; if(gap>out.maxGapMonths) out.maxGapMonths=gap; }
  }
  return out;
}
// v10.170 FAI-01: the variance-ratio denominator floor, named instead of being
// a bare 1e-6 repeated in the divisor and described in prose by the artifact
// rule. The artifact test needs to know EXACTLY what this number is - that is
// the whole thing it is detecting - so the two must not be able to drift apart.
var CSD_VAR_RATIO_FLOOR = 1e-6;
function jsVarianceHalves(resid) {
  var n = resid.length;
  var half = Math.floor(n/2);
  var first = resid.slice(0,half), second = resid.slice(half);
  function sampleVar(arr){
    if(arr.length<2) return 0;
    var m=0; for(var i=0;i<arr.length;i++) m+=arr[i]; m=m/arr.length;
    var s=0; for(var i=0;i<arr.length;i++) s+=(arr[i]-m)*(arr[i]-m);
    return s/(arr.length-1);
  }
  var v0=sampleVar(first), v1=sampleVar(second);
  return {varFirst:v0, varSecond:v1, ratio:v1/Math.max(v0,CSD_VAR_RATIO_FLOOR)};
}
function jsSkewness(resid) {
  var n = resid.length;
  if(n<4) return null;
  var m=0; for(var i=0;i<n;i++) m+=resid[i]; m=m/n;
  var variance=0; for(var i=0;i<n;i++) variance+=(resid[i]-m)*(resid[i]-m);
  variance = variance/Math.max(n-1,1);
  var std = Math.sqrt(Math.max(variance,1e-9));
  var m3=0; for(var i=0;i<n;i++) m3+=Math.pow(resid[i]-m,3);
  m3=m3/n;
  return m3/Math.pow(std,3);
}
function jsPearsonCorr(valuesA, valuesB) {
  var n = valuesA.length;
  if (n<4 || valuesB.length!==n) return null;
  var mA=0, mB=0;
  for (var i=0;i<n;i++){ mA+=valuesA[i]; mB+=valuesB[i]; }
  mA=mA/n; mB=mB/n;
  var num=0, denA=0, denB=0;
  for (var i=0;i<n;i++){
    num += (valuesA[i]-mA)*(valuesB[i]-mB);
    denA += (valuesA[i]-mA)*(valuesA[i]-mA);
    denB += (valuesB[i]-mB)*(valuesB[i]-mB);
  }
  var denom = Math.sqrt(denA)*Math.sqrt(denB);
  return denom>1e-6 ? num/denom : 0;
}
// Full node-level stats (AC1, variance halves, skewness) from a plain
// array of values - mirrors computeRealCSD's return shape so downstream
// code that reads .realAC1/.varTrendRatio/etc. works unchanged either way.
function jsNodeStats(values) {
  var clean = values.filter(function(v){ return v!==null&&v!==undefined&&!isNaN(v); });
  var n = clean.length;
  if (n<4) return {realAC1:null,varFirstHalf:null,varSecondHalf:null,varTrendRatio:null,skewness:null,nValidMonths:n};
  var resid = jsLinearDetrendResiduals(clean);
  var ac1 = jsLag1AC1(resid);
  var vh = jsVarianceHalves(resid);
  var skew = jsSkewness(resid);
  return {realAC1:ac1, varFirstHalf:vh.varFirst, varSecondHalf:vh.varSecond, varTrendRatio:vh.ratio, skewness:skew, nValidMonths:n};
}
// v10.150 FIX: jsNodeStats() above never deseasonalizes before computing
// AC1/variance - CONFIRMED via direct synthetic testing to produce a
// severe false-high-memory artifact: data with a real seasonal cycle and
// ZERO actual signal gave AC1=0.858 under the old approach (matching this
// tool's own long-documented finding that AC1 lands in a narrow ~0.78-0.89
// band across nearly every real test site, regardless of what's actually
// happening there). This fixed version deseasonalizes FIRST (reusing the
// SAME computeMonthlyClimatology()/deseasonalizeSeries() functions already
// proven and used elsewhere in this file for the STEP 3 comparison panel -
// no new, unverified logic), THEN detrends and computes AC1/variance.
// Re-validated on the same synthetic no-signal case: correctly gives AC1
// near 0. A positive control (real AR(1) signal, true phi=0.7, embedded
// under the same seasonal cycle) confirms this does not overcorrect - it
// still correctly detects the real signal (AC1=0.672).
// CRITICAL CAUGHT-BEFORE-SHIPPING BUG, found via direct testing during
// this same edit: a per-window climatology is only meaningful if calendar
// months genuinely REPEAT within the window (so climatology is a real
// average, not just a copy of a single value). Confirmed directly: for a
// 6-month window (every month appears exactly once), climatology[m] IS
// that exact value, so subtracting it zeroes out every point - destroying
// ALL information, not just seasonality. This would have broken FIND
// SWEET SPOT's short windows (tests down to 6 months) rather than fixing
// anything. Fixed: below 24 months (2 full years, guaranteeing every
// calendar month has at least 2 real samples to average), this function
// now explicitly FALLS BACK to the plain, non-deseasonalized computation
// (same real math as the original jsNodeStats(), still valid, still
// carrying the tool's existing, already-disclosed seasonal-cycle caveat)
// rather than either breaking short-window callers or silently producing
// degenerate all-zero output.
// Takes {t,v} pairs (needs real timestamps to determine each value's
// calendar month) instead of a plain value array - every call site already
// has this data available before it currently strips timestamps out.
// v10.151 FIX 3: two changes.
// (a) Deseasonalizing floor raised 24 -> 48 months. 48 months gives 4
//     samples per calendar month, clear of the degenerate region
//     documented in FIX 2 above.
// (b) NEW optional 2nd argument: a SHARED climatology. This is the fix
//     for the three-different-AC1-values problem. A real Looe Key run
//     (24.531,-81.41, 2021 vs 2023) reported the SAME window's AC1 as
//     -0.332 here (own 24mo climatology), +0.062 in the v10.127 panel
//     (pooled 48mo climatology) and +0.813 raw. Simulation puts the
//     own-vs-pooled spread at sd 0.14 across 2000 runs. Passing one
//     shared climatology collapses every code path to a single number.
// Callers passing nothing keep the old behaviour, with the safer floor.
// v10.158 W-03 FIX (BLOCKER, introduced by the v10.156 BUG-07 pooling fix):
// the `if (sharedClimatology)` branch had NO length or completeness check at
// all - the n>=48 floor sat only on the `else if`. Reproduced directly: with a
// 30-month pooled record (only 6 of 12 calendar months clearing the
// >=3-samples floor) the 6-, 9- and 12-month windows ALL collapsed onto the
// same 6 surviving points and returned the IDENTICAL AC1 (-0.790 in the
// harness; -0.646 in the audit's run), reported as
// climatologySource:'shared (pooled)' with no warning, against -0.211/-0.468/
// -0.500 unpooled. Three different windows, one number, no note.
// RULE PICKED, and it is the same rule in both branches: a climatology may be
// subtracted only when it is COMPLETE - all 12 calendar months cleared the
// >=CLIM_MIN_SAMPLES_PER_MONTH floor. 12 months x 3 samples = 36 months of
// record, which is exactly CSD_MIN_WINDOW_MONTHS, so the completeness rule and
// the window floor are the same number by construction and cannot drift. A
// complete climatology also drops NO points, which is what closes W-02 on this
// path: the deseasonalized series has no holes, so its lag-1 pairs are real.
// On failure this does NOT return a collapsed number: it falls back to the
// plain raw computation and records why in climatologySource/climatologyNote.
// v10.159 CORRECTION: the v10.158 wording here was "and says so, loudly". It
// did not. Those fields, and ac1PairsUsed/ac1PairsDropped/ac1MaxGapMonths, were
// written by this function and read by NO caller anywhere in the file. They are
// now rendered at every consumer via nodeStatsDisclosure(), and the failure
// itself is far rarer because computeUsableClimatology() imputes rather than
// refuses - see the v10.159 block inside the function body.
// v10.158 W-02: the timestamps are carried all the way to jsLag1AC1 now
// instead of being stripped, and any pair that is not one calendar month apart
// is excluded from the AC1 (belt and braces behind the completeness rule, for
// callers that reach this with a ragged series from some other route).
function jsNodeStatsFixed(seriesTV, sharedClimatology) {
  var clean = (seriesTV||[]).filter(function(s){ return s && s.v!==null && s.v!==undefined && !isNaN(s.v); });
  var n = clean.length;
  if (n < 4) return {realAC1:null,varFirstHalf:null,varSecondHalf:null,varTrendRatio:null,skewness:null,nValidMonths:n,deseasonalized:false,climatologySource:'none',climatologyNote:'fewer than 4 valid months',ac1PairsUsed:0,ac1PairsDropped:0};
  // v10.159 W-01/W-02 REGRESSION FIX + N4 RECONCILIATION.
  // v10.158 refused any climatology that was not 12/12 complete and fell back
  // to raw. On FAI (Sentinel-2, CLOUDY_PIXEL_PERCENTAGE<20) that is the normal
  // case at EVERY window length, so S7C/S7D/S7E/S7F were on the raw path
  // essentially always. Measured pass rate of the old 12/12 rule by record
  // length and per-month drop rate (10000 draws per cell):
  //        N   0%    5%     10%    15%   20%
  //        36  100   15.8   2.2    0.3   0.0
  //        48  100   84.8   51.4   24.9  9.1
  //        60  100   98.8   89.9   72.6  49.8
  //   and 2.8% at N=36 with seasonally-clustered gaps, which is how cloud and
  //   ice actually behave. The rule was, in practice, "never deseasonalize".
  // Now: computeUsableClimatology() imputes the calendar months it cannot
  // estimate from their own samples, so a gappy record is deseasonalized
  // instead of refused, and - because every calendar month has a mean - NO
  // reading is dropped, which is what W-02/W-03 actually required.
  // N4, the n>=48 gate on the self-computed branch: it is GONE, and with it the
  // contradiction the reviewer flagged between "n>=48" in the code and "implies
  // 36 by construction" in the v10.158 note. The branch is now gated on exactly
  // one thing - whether computeUsableClimatology() can produce a climatology at
  // all (CLIM_MIN_TOTAL_SAMPLES valid months covering CLIM_MIN_DISTINCT_MONTHS
  // calendar months) - so there is only one number to keep straight.
  // N4, the REST of the gap-awareness: still PARTIAL, and deliberately so.
  // Only realAC1 is gap-aware. jsVarianceHalves() and jsSkewness() still treat
  // the kept values as evenly spaced. That is stated rather than fixed because
  // the v10.153 variance-ratio cutoffs were calibrated against the current,
  // index-based split-half estimator, and changing the estimator without
  // re-running that 13.6-year Scripps calibration would silently invalidate
  // every varr threshold in CSD_NULL_CALIBRATION. ac1MaxGapMonths is returned
  // so a caller can see how far from evenly-spaced the series actually is;
  // v10.159 surfaces it on screen at every consumer (see nodeStatsDisclosure).
  var kept, wasDeseasonalized, climSource, climNote='';
  if (sharedClimatology) {
    if (climatologyIsComplete(sharedClimatology)) {
      kept = deseasonalizeSeries(clean, sharedClimatology)
        .filter(function(s){ return s.v!==null && s.v!==undefined && !isNaN(s.v); });
      wasDeseasonalized = true;
      climSource = 'shared (pooled) - '+climatologyCoverageNote(sharedClimatology);
    } else {
      kept = clean.slice();
      wasDeseasonalized = false;
      climSource = 'none - shared (pooled) climatology REFUSED';
      climNote = 'SHARED CLIMATOLOGY REJECTED: '+climatologyCoverageNote(sharedClimatology)+
        '. Subtracting it would silently delete every month whose calendar month is missing, '+
        'collapsing different window lengths onto the same few surviving points and returning '+
        'one identical AC1 for all of them. RAW (non-deseasonalized) values used instead - do '+
        'NOT compare this number against a deseasonalized one.';
    }
  } else {
    var ownRes = computeUsableClimatology(clean);
    if (ownRes.ok) {
      kept = deseasonalizeSeries(clean, ownRes.climatology)
        .filter(function(s){ return s.v!==null && s.v!==undefined && !isNaN(s.v); });
      wasDeseasonalized = true;
      climSource = 'own window (n='+n+'mo) - '+climatologyCoverageNote(ownRes.climatology);
    } else {
      kept = clean.slice();
      wasDeseasonalized = false;
      climSource = 'none - own-window climatology NOT POSSIBLE (n='+n+'mo)';
      climNote = 'NOT DESEASONALIZED: '+ownRes.reason+' The AC1/variance figures below are RAW '+
        'and carry the v10.101 seasonal-cycle caveat - a shared seasonal cycle alone can push '+
        'AC1 toward a high baseline. Do NOT compare them against a deseasonalized number, and '+
        'note that no p-value is reported for this series for the same reason.';
    }
  }
  if (kept.length < 4) return {realAC1:null,varFirstHalf:null,varSecondHalf:null,varTrendRatio:null,skewness:null,nValidMonths:kept.length,deseasonalized:wasDeseasonalized,climatologySource:climSource,climatologyNote:climNote,ac1PairsUsed:0,ac1PairsDropped:0};
  var valuesOnly = kept.map(function(s){ return s.v; });
  var timesOnly  = kept.map(function(s){ return s.t; });
  var audit = jsLag1PairAudit(timesOnly);
  var resid = jsLinearDetrendResiduals(valuesOnly);
  var ac1 = jsLag1AC1(resid, timesOnly);
  var vh = jsVarianceHalves(resid);
  var skew = jsSkewness(resid);
  if(audit.nNonAdjacent>0){
    climNote = (climNote?climNote+' | ':'')+
      'GAPPED SERIES: '+audit.nNonAdjacent+' of '+audit.nPairs+' consecutive array positions are NOT one '+
      'calendar month apart (largest gap '+audit.maxGapMonths+' months). Those pairs are EXCLUDED from the '+
      'lag-1 AC1'+(ac1===null?', leaving too few real lag-1 pairs to compute one at all.':'; the AC1 shown uses only the '+audit.nAdjacent+' genuine lag-1 pairs.');
  }
  return {realAC1:ac1, varFirstHalf:vh.varFirst, varSecondHalf:vh.varSecond, varTrendRatio:vh.ratio, skewness:skew, nValidMonths:kept.length, deseasonalized:wasDeseasonalized, climatologySource:climSource, climatologyNote:climNote,
    ac1PairsUsed:audit.nAdjacent, ac1PairsDropped:audit.nNonAdjacent, ac1MaxGapMonths:audit.maxGapMonths};
}

// Defensive extraction from a reduceRegions() output feature's properties -
// the exact output property name for a single-band mean reducer should be
// the band name itself, but this falls back gracefully rather than assuming.
function extractReduceRegionsValue(props, bandName) {
  if(!props) return null;
  if(props[bandName]!==undefined && props[bandName]!==null && typeof props[bandName]==='number') return props[bandName];
  if(props.mean!==undefined && props.mean!==null && typeof props.mean==='number') return props.mean;
  for(var k in props){
    if(k==='label'||k==='idx'||k==='t'||k==='system:index') continue;
    if(typeof props[k]==='number'&&!isNaN(props[k])) return props[k];
  }
  return null;
}
// v10.161 FIX 19 / S6b + S7 - NO MORE "x / 0" FRACTIONS ON SCREEN.
// OBSERVED IN A LIVE BROWSER RUN at Bocas del Toro: S7F printed
//   "S7D: NO SYNCHRONIZATION SIGNAL (0/7 on-reef rising) | AC1 rising at 0/0 nodes"
// "0/0 nodes" is not a result. It is the rendering of an empty denominator: at
// a cloud-limited site NO node had two windows with a computable AC1, so the
// tally divided by nothing. A reader cannot tell "tested 0 nodes" from "tested
// some nodes and none rose" - and those are opposite findings, exactly the
// distinction v10.114 and v10.156 BUG-05 already had to restore elsewhere in
// this file. countOfTotal() renders a real fraction when the denominator is
// positive and an explicit sentence when it is zero, so an untested tally can
// never again look like a measured null.
// v10.161 FIX 19 / S6a - A PROGRESS COUNTER THAT NEVER LOOKS FROZEN, AND
// WHICH SAYS WHAT A FROZEN ONE MEANS.
// OBSERVED IN A LIVE BROWSER RUN: long after S7F had completed with full
// results, S7D still read "Running: 2 / 3 batched calls done..." and S7E
// "Step 2/3: 1 / 2 batched calls done..." - permanently. TRACED (not run - the
// UI paths cannot be executed in the Node harness): every one of these panels
// updates its status label inside a per-call bump() and only replaces it when
// the pending counter reaches ZERO. Both finish() functions do set a final
// label on every path they reach, including the insufficient-data ones - so a
// frozen counter means one .evaluate() callback NEVER ARRIVED (an Earth Engine
// quota refusal or a hung request; this file has hit the account concurrency
// quota before, and there is no setTimeout in the GEE sandbox to time it out).
// There is therefore no code path that can clear the label, and the panel's own
// promise - "a live counter below shows progress so it never looks frozen" -
// is broken in exactly the case it was built for.
// WHAT IS FIXED, given a timeout is not available:
//   1. The counter now NAMES the calls it is still waiting on, so a stuck panel
//      says WHICH call is missing instead of only how many are done.
//   2. It carries, in the label itself, what a stalled counter means and what
//      to do about it - so "frozen" is a diagnosis on screen, not a mystery.
//   3. A per-panel run sequence number means a late callback from an abandoned
//      run can no longer overwrite the label of a newer one. Pressing RUN again
//      is now a clean reset, which is the recovery the text points the user at.
// WHAT IS NOT FIXED, stated plainly: a callback that never fires still never
// fires. Without a timer this cannot be turned into an automatic failure.
var S7_STALL_HINT = 'If this line stops changing for several minutes, that call has not returned (Earth Engine\n'+
  'quota or a hung request). Nothing is lost - press RUN again for a clean retry. The Console\n'+
  'records each call\'s real outcome as it lands.';
// Removes a finished call from the outstanding list and renders it.
function s7Outstanding(list, key){
  var i=list.indexOf(key);
  if(i>=0) list.splice(i,1);
  return list.length>0?('Still waiting on: '+list.join(', ')):'All calls returned - computing results...';
}
function countOfTotal(hits, total, unitPlural, emptyTxt){
  if(total===null||total===undefined||isNaN(total)||total<=0){
    return emptyTxt||('no '+unitPlural+' had enough valid data to test');
  }
  return hits+'/'+total+' '+unitPlural;
}
// Groups a raw reduceRegions()+flatten() evaluate() result into per-node
// time series: {label: [{t, v}, ...]}, sorted by time.
function groupSeriesByLabel(fcResult, bandName) {
  var byLabel = {};
  if(!fcResult || !fcResult.features) return byLabel;
  fcResult.features.forEach(function(f){
    var p = f.properties||{};
    var label = p.label;
    if(label===undefined||label===null) return;
    var v = extractReduceRegionsValue(p, bandName);
    if(!byLabel[label]) byLabel[label] = [];
    byLabel[label].push({t:p.t, v:v});
  });
  Object.keys(byLabel).forEach(function(label){
    byLabel[label].sort(function(a,b){ return a.t - b.t; });
  });
  return byLabel;
}
// v10.160 S6 FIX - THE POOLED-CLIMATOLOGY FIX NEVER REACHED THE SHIPPED PANELS.
// v10.159 S1 made the DISPLAYED AC1 and the TESTED AC1 the same estimator, but
// only when both are handed the same climatology. Every shipped call site -
// S7D, S7E and S7F (both paths) - called jsNodeStatsFixed(series) with NO
// sharedClimatology, so the display deseasonalized each window against its OWN
// climatology while permutationTestDeltaFixed deseasonalized both windows
// against the POOLED one. MEASURED at the S7D/S7E default (18 BEFORE + 12 AFTER,
// seasonal amplitude 3 smooth sine, noise SD 1, gap 0, 1500 draws): the displayed
// and tested deltas disagreed in SIGN on 38.3% of unmasked draws and 40.4% at 10%
// per-month masking, worst case displayed -0.5729 against tested +0.7090 - a
// bigger discrepancy than the 0.5447 that S1 set out to remove, and opposite in
// sign. With this helper in place the same harness reports 0.0% sign disagreement
// and a worst |displayed - tested| of 0.0000 in every cell measured (18+12,
// 24+24 and 36+12, unmasked and at 10% masking).
// This helper builds the pooled climatology once for a
// BEFORE/AFTER pair and hands the SAME one to both windows, which is what
// STEP 3 COMPARE and STEP 4 have done since v10.151 FIX 4b / v10.156 BUG-07.
// Returns null when no usable pooled climatology exists, and jsNodeStatsFixed
