// Two ready-made statFn wrappers, reusing the exact same detrend/AC1/
// variance building blocks already proven this session (jsNodeStats,
// STEP 5, S7C/D/E/F all already rely on these same three functions).
// v10.159 S1 FIX: both wrappers now take an OPTIONAL parallel time vector, and
// permutationTestDeltaFixed() passes the SAME one to the observed statistic and
// to every shuffle. Before this, jsNodeStatsFixed() computed the DISPLAYED AC1
// with timestamps (so non-adjacent pairs were skipped) while statAC1ForPerm()
// computed the TESTED AC1 without them - two different estimators on the same
// screen, measured 0.8101 displayed vs 0.6777 tested at n=25 and 0.5799 vs
// 0.4742 at n=24 on a gapped series. Passing times to the observed side ALONE
// would import S2 (the null would then use more pairs than the observed
// statistic, biasing p downward - measured 7.5-8.8% against a nominal 5%), so
// the times go to both sides or to neither.
// statVarRatioForPerm accepts the argument for a uniform call signature but
// deliberately ignores it - see the N4 note on jsVarianceHalves().
function statAC1ForPerm(vals, times){
  if(vals.length<4) return null;
  var resid = jsLinearDetrendResiduals(vals);
  return jsLag1AC1(resid, times);
}
function statVarRatioForPerm(vals, times){
  if(vals.length<4) return null;
  var resid = jsLinearDetrendResiduals(vals);
  var vh = jsVarianceHalves(resid);
  return vh.ratio;
}
// v10.127 NEW: deseasonalizing - direct fix for the caveat disclosed since
// v10.101 (never actually built until now): AC1/variance computed on RAW
// monthly values can be inflated purely by the shared seasonal cycle
// (every site is warmer in summer, colder in winter, regardless of any
// real dynamical change) - evidence for this being a real problem, not
// theoretical, is that AC1 landed in a narrow ~0.78-0.89 band across
// nearly every GBR site tested this session, more consistent with
// seasonal autocorrelation dominating than genuine site-specific signal.
// Standard climate-science fix: compute each calendar month's average
// value (the "climatology") from the site's own data, then subtract that
// expected seasonal value from each real reading, leaving only the
// "anomaly" - how unusual THIS particular month was, with the seasonal
// cycle already removed. AC1/variance computed on anomalies instead of
// raw values are not inflated by the seasonal cycle.
// DISCLOSED LIMIT: with typical S13 windows (10-24 months), there are
// only 1-2 samples per calendar month to estimate the climatology from -
// a genuinely noisy estimate, not a robust multi-decade seasonal average.
// Treat this as an exploratory comparison against the raw AC1/variance
// already shown, not a fully validated replacement for it.
var CLIM_MIN_SAMPLES_PER_MONTH = 3;
function computeMonthlyClimatology(seriesTV){
  var byMonth={};
  (seriesTV||[]).forEach(function(s){
    if(s.v===null||s.v===undefined||isNaN(s.v)) return;
    var m=new Date(s.t).getUTCMonth();
    if(!byMonth[m]) byMonth[m]=[];
    byMonth[m].push(s.v);
  });
  // v10.151 FIX 2: require >=3 samples per calendar month.
  // With exactly 2 samples, subtracting their mean forces the pair to
  // become (+d,-d) - mirror images BY CONSTRUCTION, not by measurement.
  // Simulated on pure seasonal + white noise (true AC1 = 0), the old
  // 2-sample path returned AC1 = -0.051 at 24 months, decaying to -0.007
  // at 240 months. The v10.150 comment claimed 2 samples/month was
  // sufficient; it is not. Months below the floor now return no
  // climatology, so deseasonalizeSeries drops those points instead of
  // injecting a deterministic artifact.
  var climatology={};
  var nUsable=0, nRejected=0, nTotalSamples=0;
  for(var m=0;m<12;m++){
    if(byMonth[m]) nTotalSamples+=byMonth[m].length;
    if(byMonth[m]&&byMonth[m].length>=CLIM_MIN_SAMPLES_PER_MONTH){
      var sum=0; byMonth[m].forEach(function(v){sum+=v;});
      climatology[m]={mean:sum/byMonth[m].length, n:byMonth[m].length};
      nUsable++;
    } else if(byMonth[m]){ nRejected++; }
  }
  climatology._meta={nUsableMonths:nUsable,nRejectedMonths:nRejected,
                     minSamples:CLIM_MIN_SAMPLES_PER_MONTH,
                     nTotalSamples:nTotalSamples,
                     complete:(nUsable===12)};
  return climatology;
}
// ============================================================================
// v10.159 W-01/W-02 REGRESSION FIX (BLOCKER) - THE 12/12 COMPLETENESS RULE
// TURNED A CALIBRATED TEST INTO AN UNCALIBRATED ONE.
// v10.158 required all 12 calendar months to clear the >=3-samples floor
// before anything could be deseasonalized, and on failure it ran the
// permutation test on RAW values instead. MEASURED CONSEQUENCE, phase-averaged
// Monte Carlo on pure seasonality + white noise with NO real change (3000 reps
// per cell, variance-ratio statistic, nominal 5%, SE about 0.4pp):
//     config           shape     v10.156   v10.158   v10.159
//     18+12 (S7D/E)    smooth      4.8%     13.5%      4.8%
//     18+12 (S7D/E)    sawtooth    4.7%     25.4%      5.6%
//     18+12 (S7D/E)    spike       5.1%     14.4%      4.5%
//     12+12            smooth    no p-val   24.0%      6.2%
//     12+12            sawtooth  no p-val   39.8%      6.0%
//     12+12            spike     no p-val   10.4%      5.6%
//     36+12            smooth      4.8%      5.4%      5.0%
// i.e. at the shipped S7D/S7E month boxes v10.158 ran a nominal-5% test at
// 10.4-39.8% and printed "likely real (p<0.05)" with no warning. That is worse
// than v10.156, which this rule was supposed to improve on.
// ---------------------------------------------------------------------------
// v10.160 AUDIT OF THE TABLE DIRECTLY ABOVE. Its v10.156 and v10.158 columns are
// the historical record of why the v10.159 change was made and were NOT
// re-derived this session; they are not quoted anywhere in v10.160 as a current
// property of anything. Its v10.159 COLUMN describes code that is still here, so
// it was re-measured, and TWO of its cells DID NOT REPRODUCE:
//     config   claimed v10.159    re-measured v10.160
//     18+12        4.8%           5.5 - 7.0%   (amp 3 and 10, three shapes,
//                                               gap 0 and gap 0-3, 2000 reps)
//     12+12        6.2%           1.1 - 4.1% at gap 0, 3.9 - 4.7% at gap 0-3
//                                 (conservative and gap-dependent, not high)
// The 18+12 figure is the one that mattered: it is the number the S7D/S7E
// default was justified by. Both are WITHDRAWN. The single set of numbers this
// file now states is the four tables in the v10.160 header entry; this comment
// does not restate them, so they cannot drift apart again.
// ---------------------------------------------------------------------------
// THE ROUTE TAKEN is the reviewer's option (a): IMPUTE the calendar months
// that cannot be estimated from their own samples, so deseasonalizing still
// happens and the series handed on still has no holes. A monthly climatology
// is a 12-parameter description of one smooth annual cycle, and estimating it
// as 12 INDEPENDENT means is the wasteful way to do it - months next to each
// other carry information about each other. So:
//   1. a seasonal harmonic model (mean + CLIM_HARMONIC_ORDER sin/cos pairs,
//      7 free parameters at order 3) is least-squares fitted to EVERY valid
//      reading in the record at once;
//   2. each calendar month's climatology is then its own samples blended with
//      that fitted cycle, weighting the fit as CLIM_HARMONIC_PRIOR_WEIGHT
//      pseudo-observations: mean = (sum(own samples) + w*fitted) / (n + w).
//      A month with many samples is therefore essentially its own mean; a
//      month with none is exactly the fitted value - i.e. imputed from its
//      neighbours, which is what the fit is built from.
// Every calendar month now has a mean, so deseasonalizeSeries() drops NOTHING
// and the resulting series has no holes - which is what W-02 (lag-1 pairs
// spanning gaps) and W-03 (different windows collapsing onto the same few
// surviving points) actually needed. The 12/12 rule closed those two by
// refusing to deseasonalize at all; this closes them while still removing the
// seasonal cycle.
// WHAT IT IS NOT: this is not a free lunch at any record length. It refuses
// outright below CLIM_MIN_DISTINCT_MONTHS distinct calendar months or
// CLIM_MIN_TOTAL_SAMPLES total valid months, and the permutation tests then
// return NO p-value (reviewer's option (b)) rather than a raw-series one -
// see permutationTestDeltaFixed().
// WHY 24, STATED ACCURATELY. An earlier draft of this note said the floor was
// buying CALIBRATION below 24 months. Re-measured against the function as it
// actually ships, that was wrong and is corrected here: with the floor lowered
// to 8, the variance-ratio false-positive rate at pooled totals of 12 to 22
// months comes out at 3.1-6.8% across {smooth, sawtooth, summer-spike} - about
// the same as above the floor. What collapses below 24 is POWER, and that was
// measured too (a REAL x5 change in the AFTER window's variance, 2000 reps,
// fraction detected at p<0.05):
//     pooled  12    16     18     22     24     30     48
//     power  7.3%  19.8%  22.9%  34.3%  45.7%  62.5%  71.3%
// plus the arithmetic: the order-3 fit spends 7 parameters, so a 12-month
// pooled record leaves it 5 residual degrees of freedom. So the floor is a
// POWER floor and an over-fitting guard, in line with CSD_MIN_WINDOW_MONTHS
// (36) which this module enforces far above it anyway - NOT a calibration
// floor. A p-value that would be "not significant" 90% of the time on a real
// change is not information, and is not reported.
// THE PRIOR WEIGHT: v10.159 claimed this was scanned, and quoted worst-cell
// figures of 6.1 / 6.2 / 7.2 / 9.4 / 11.4 / 13.6% at w = 0.3 / 0.5 / 0.75 / 1.0
// / 1.5 / 2.0. v10.160 AUDIT: that scan NEVER STATED ITS DESIGN - no seasonal
// amplitude, no gap policy, no shuffle count, no replicate count - and it does
// not reproduce as written. RE-DERIVED against this function, worst cell over
// {18+12, 24+12, 36+12} x {smooth, sawtooth, summer-spike}, 1500 reps/cell,
// gap uniform 0-3, 300 shuffles, nominal 5% (12+12 is below the v10.160 floor
// and no longer runs, so it is not in the worst-cell set):
//   seasonal amplitude 2:  w=0  6.7   0.3  7.1   0.5  7.0   0.75 7.2
//                          1.0  7.3   1.5  7.3   2.0  7.1   4.0  6.3    FLAT
//   seasonal amplitude 10: w=0  6.7   0.3  6.9   0.5  6.9   0.75 6.7
//                          1.0  7.0   1.5  8.7   2.0 10.2   4.0 13.3
// WHAT THAT ACTUALLY SUPPORTS, stated instead of the old claim: at ordinary
// seasonal amplitude the scan does not discriminate between w = 0 and w = 4 at
// all. At LARGE amplitude the rate is flat up to w = 1 and rises sharply above
// it. So w = 0.5 is a safe choice and is kept - it is inside the flat region at
// both amplitudes - but NOTHING in this measurement shows it is better than 0 or
// 0.3, and the claim that it was picked off a monotone curve is withdrawn.
// The mechanism the old comment gave for the rise is still the right one: a
// large w pushes the climatology toward a cycle the harmonics can represent and
// leaves whatever they cannot in the residual, which is why the amplitude-10
// column moves and the amplitude-2 column does not.
var CLIM_HARMONIC_ORDER = 3;            // mean + 3 sin/cos pairs = 7 parameters
var CLIM_HARMONIC_PRIOR_WEIGHT = 0.5;   // pseudo-observations of the fitted cycle
var CLIM_MIN_DISTINCT_MONTHS = 9;       // of 12; below this the fit extrapolates too far
// v10.160 S9 FIX: this was 24, and 24 violated the criterion its own refusal
// string states ("a p-value that would miss a real change two times in three is
// not reported"). MEASURED, variance-ratio statistic, floors lowered to 8 so
// every pooled total runs, seasonal amplitude 3 on a smooth sine AND on an
// adversarial sawtooth, noise SD 1, real change = AFTER window's second half at
// 5x noise SD, nPerm=300, 3000 reps/cell, nominal 5%, reported as
// {fixed gap 0 months, gap uniform 0-3 months}:
//   pooled  FPR              power against the 5x change
//     24    1.1-4.1%         21.7-40.3%   <- fails the stated criterion at gap 0
//     25    3.0-4.6%         34.2-48.8%
//     26    3.4-5.4%         47.1-58.5%   <- CHOSEN
//     28    5.2-6.2%         61.3-68.8%
//     30    6.1-6.9%         70.7-75.3%
//     36    4.9-5.4%         68.3-69.8%
// 26 is the shortest pooled total at which the stated criterion is true under
// EVERY gap policy measured, and it has the closest-to-nominal false-positive
// rate of any candidate. 28 and 30 buy more power but run 5.2-6.9%, i.e. up to
// 40% above nominal. The whole 24-30 band is Monte Carlo noise of about +-0.4
// points near 5%; the power column is what separates the rows, not the FPR one.
var CLIM_MIN_TOTAL_SAMPLES = 26;        // valid months in the record feeding the climatology
// v10.160 BLOCKER 3 FIX - THE AC1 STATISTIC NEEDS ITS OWN, MUCH HIGHER FLOOR.
// CLIM_MIN_TOTAL_SAMPLES is a VARIANCE-statistic floor. It is far too low for
// the AC1 statistic, for the reason v10.151 FIX 2 already documented and
// v10.159 then re-introduced everywhere: when a calendar month has only 1-2 own
// samples, subtracting a mean dominated by those samples forces the residual
// pair toward mirror images. MEASURED against the shipped
// computeUsableClimatology()/deseasonalizeSeries() pair, 12 calendar months each
// observed exactly k times, seasonal amplitude 10 smooth sine, noise SD 1, 4000
// draws: the correlation between the two residuals of the same calendar month is
//   k=2  -0.969     k=3  -0.513     k=4  -0.326     k=5  -0.243
// (v10.151 FIX 2 quoted -0.92 for the unblended 2-sample mean; the prior-weight
// blend does not rescue it, because the fitted cycle it blends in is itself
// estimated from the same 24 readings). This destroys the lag-1
// autocorrelation the statistic is trying to measure. At
// pooled totals near 24-30 the pooled record supplies about 2 samples per
// calendar month and the AC1 delta goes DEAD - not anti-conservative, dead.
// MEASURED, statAC1ForPerm through permutationTestDeltaFixed, seasonal
// amplitude 3 smooth sine, noise SD 1, BEFORE AR(1) phi=0 throughout,
// AFTER phi=0 (FPR) or phi=0.8 (power), gap uniform 0-3 months, random start
// calendar month, nPerm=300, 2000 reps/cell, nominal 5%:
//   pooled  cfg      FPR    power(phi 0 -> 0.8)
//     24    12+12    0.2%      0.7%
//     28    16+12    0.6%      2.6%
//     30    18+12    2.0%      3.5%
//     32    16+16    1.1%      7.6%
//     36    18+18    2.1%     13.1%
//     40    20+20    2.5%     20.0%
//     44    22+22    3.6%     27.8%
//     48    24+24    4.3%     39.2%   <- CHOSEN floor
//     72    36+36    4.8%     69.4%
//     96    48+48    4.9%     89.3%
// Below 36 pooled the false-positive rate is 0.2-2.0% against a nominal 5% and
// the power against a phi 0 -> 0.8 change is 0.7-3.8%: the test cannot produce
// a significant result whether or not one is there. 48 = 12 calendar months x 4
// samples (one more than v10.151's 3-per-month rule) is the shortest pooled
// total at which the null is calibrated (4.0-4.3%) AND a balanced pair of
// windows clears the same "not missed two times in three" criterion the
// variance floor is held to (39.2% at 24+24).
// WHAT THIS FLOOR DOES NOT BUY, stated because it would otherwise be read in:
// power is governed by the SHORTER window, not by the pooled total. At pooled
// 48 the measured power is 4.4% at 36+12, 17.3% at 30+18 and 39.2% at 24+24.
// A non-significant AC1 result from an unbalanced pair is close to no
// information at all; the panels print the two window lengths next to it.
var CSD_AC1_MIN_POOLED_MONTHS = 48;
// Ordinary least squares via the normal equations with partial pivoting.
// p is at most 7 here, so the conditioning concern that normally argues for
// QR does not bite; a tiny ridge term keeps a rank-deficient design (e.g. a
// record that happens to contain only 9 distinct calendar months) solvable
// instead of dividing by zero.
function solveLeastSquares(X, y){
  var n=X.length; if(n===0) return null;
  var p=X[0].length, i, j, k;
  var A=[], b=[];
  for(i=0;i<p;i++){ var rowA=[]; for(j=0;j<p;j++) rowA.push(0); A.push(rowA); b.push(0); }
  for(k=0;k<n;k++){ for(i=0;i<p;i++){ for(j=0;j<p;j++) A[i][j]+=X[k][i]*X[k][j]; b[i]+=X[k][i]*y[k]; } }
  for(i=0;i<p;i++) A[i][i]+=1e-9;
  for(i=0;i<p;i++){
    var piv=i;
    for(k=i+1;k<p;k++) if(Math.abs(A[k][i])>Math.abs(A[piv][i])) piv=k;
    if(Math.abs(A[piv][i])<1e-12) return null;
    var tr=A[i]; A[i]=A[piv]; A[piv]=tr;
    var tb=b[i]; b[i]=b[piv]; b[piv]=tb;
    for(k=i+1;k<p;k++){
      var f=A[k][i]/A[i][i];
      for(j=i;j<p;j++) A[k][j]-=f*A[i][j];
      b[k]-=f*b[i];
    }
  }
  var x=[]; for(i=0;i<p;i++) x.push(0);
  for(i=p-1;i>=0;i--){ var s=b[i]; for(j=i+1;j<p;j++) s-=A[i][j]*x[j]; x[i]=s/A[i][i]; }
  for(i=0;i<p;i++) if(isNaN(x[i])||!isFinite(x[i])) return null;
  return x;
}
function seasonalHarmonicBasis(m, order){
  var row=[1];
  for(var h=1;h<=order;h++){
    row.push(Math.sin(2*Math.PI*h*m/12));
    row.push(Math.cos(2*Math.PI*h*m/12));
  }
  return row;
}
// Least-squares fit of the annual cycle to the whole record at once. Returns
// function(calendarMonth) -> fitted value, or null if the record cannot
// support the fit. NOTE: no trend term. v10.159 reported that a linear index term
// was tried and measured at a worst cell of 6.5% against 6.2% without it. v10.160
// did NOT re-derive that comparison, and the 6.2% baseline it is quoted against
// is one of the figures the v10.160 audit withdrew, so the two numbers are not
// repeated here as fact. The trend term stays out on the argument that does not
// depend on them: it is the wrong thing to fit here, because the pooled
// BEFORE+AFTER record's apparent "trend" is partly the before/after difference
// the test exists to measure, so fitting it would absorb the signal.
function fitSeasonalHarmonics(seriesTV, order){
  var X=[], y=[];
  (seriesTV||[]).forEach(function(s){
    if(!s || s.v===null || s.v===undefined || isNaN(s.v)) return;
    X.push(seasonalHarmonicBasis(new Date(s.t).getUTCMonth(), order));
    y.push(s.v);
  });
  var nParams=1+2*order;
  if(X.length < nParams) return null;
  var beta=solveLeastSquares(X,y);
  if(!beta) return null;
  return function(m){
    var row=seasonalHarmonicBasis(m, order), v=0;
    for(var j=0;j<beta.length;j++) v+=beta[j]*row[j];
    return v;
  };
}
// The climatology every deseasonalizing caller should use from v10.159 on.
// Returns {ok:true, climatology:<complete 12-month climatology>, note:'...'}
// or {ok:false, climatology:null, reason:'...'} - and when it says false the
// caller must NOT quietly fall back to raw values and keep emitting a p-value.
function computeUsableClimatology(seriesTV){
  var byMonth={}, nTotal=0, nDistinct=0, m;
  (seriesTV||[]).forEach(function(s){
    if(!s || s.v===null || s.v===undefined || isNaN(s.v)) return;
    var mm=new Date(s.t).getUTCMonth();
    if(!byMonth[mm]) byMonth[mm]=[];
    byMonth[mm].push(s.v);
    nTotal++;
  });
  for(m=0;m<12;m++) if(byMonth[m]) nDistinct++;
  if(nTotal<CLIM_MIN_TOTAL_SAMPLES || nDistinct<CLIM_MIN_DISTINCT_MONTHS){
    return {ok:false, climatology:null, nTotalSamples:nTotal, nDistinctMonths:nDistinct,
      reason:'cannot be computed at this window length / with this much seasonal coverage: '+
             nTotal+' valid months covering '+nDistinct+' of 12 calendar months, against a floor '+
             'of '+CLIM_MIN_TOTAL_SAMPLES+' months covering '+CLIM_MIN_DISTINCT_MONTHS+'. '+
             (nDistinct<CLIM_MIN_DISTINCT_MONTHS
               ? 'SEASONAL COVERAGE is what fails here: with only '+nDistinct+' of 12 calendar '+
                 'months represented anywhere in the record, more than '+(12-CLIM_MIN_DISTINCT_MONTHS)+
                 ' of the 12 monthly means would have to be invented by the harmonic fit rather '+
                 'than informed by a neighbouring month that was actually observed.'
               : 'RECORD LENGTH is what fails here, and that floor is a POWER floor, measured: '+
                 'below it a REAL five-fold rise in the AFTER window noise is detected only '+
                 '7-34% of the time (against 46% at 24 months and 71% at 48), and the '+
                 '7-parameter seasonal fit is left too few degrees of freedom. A p-value that '+
                 'would miss a real change two times in three is not reported.')};
  }
  var order=CLIM_HARMONIC_ORDER;
  var fit=fitSeasonalHarmonics(seriesTV, order);
  while(!fit && order>1){ order--; fit=fitSeasonalHarmonics(seriesTV, order); }
  if(!fit){
    return {ok:false, climatology:null, nTotalSamples:nTotal, nDistinctMonths:nDistinct,
      reason:'the seasonal harmonic fit did not converge on this record ('+nTotal+
             ' valid months, '+nDistinct+'/12 calendar months) - no p-value is reported.'};
  }
  var clim={}, nObserved=0, nImputed=0, w=CLIM_HARMONIC_PRIOR_WEIGHT;
  for(m=0;m<12;m++){
    var arr=byMonth[m]||[], sum=0;
    for(var i=0;i<arr.length;i++) sum+=arr[i];
    var fitted=fit(m);
    clim[m]={mean:(sum + w*fitted)/(arr.length + w), n:arr.length, fitted:fitted};
    if(arr.length>=CLIM_MIN_SAMPLES_PER_MONTH) nObserved++;
    if(arr.length===0) nImputed++;
  }
  clim._meta={nUsableMonths:12, nRejectedMonths:0, minSamples:CLIM_MIN_SAMPLES_PER_MONTH,
              nTotalSamples:nTotal, complete:true, imputed:true,
              nDistinctMonths:nDistinct, nWellSampledMonths:nObserved,
              nFullyImputedMonths:nImputed, harmonicOrder:order, priorWeight:w};
  return {ok:true, climatology:clim, nTotalSamples:nTotal, nDistinctMonths:nDistinct,
    note:'DESEASONALIZED against a complete 12/12 climatology: '+nObserved+' of 12 calendar '+
         'months had '+CLIM_MIN_SAMPLES_PER_MONTH+'+ own samples, '+nImputed+
         ' had none and were imputed from the fitted annual cycle, the rest are their own '+
         'samples blended with it (order-'+order+' harmonics, prior weight '+w+', from '+
         nTotal+' valid months covering '+nDistinct+'/12 calendar months). No reading is '+
         'dropped, so the series has no holes.'};
}
// v10.158 W-02/W-03: a climatology is safe to subtract ONLY when all 12
// calendar months cleared the >=CLIM_MIN_SAMPLES_PER_MONTH floor. If any
// month is missing, deseasonalizeSeries() returns v:null for every reading in
// that month, callers filter those out, and what is left is a series with
// HOLES - which then silently became "lag-1" AC1 pairs spanning up to 11 real
// months (W-02), or collapsed three different window lengths onto the same
// handful of surviving points and returned one identical AC1 for all of them
// (W-03).
// v10.160 NIT - THE ARITHMETIC CLAIM THAT USED TO CLOSE THIS COMMENT IS STALE.
// It said "12 usable months x 3 samples each = 36, the SAME 36-month floor
// CSD_MIN_WINDOW_MONTHS enforces everywhere else, so this rule and that floor
// cannot drift apart". They have already drifted: since v10.159 the climatology
// this function is asked about is normally an IMPUTED one from
// computeUsableClimatology(), which sets _meta.complete = true unconditionally
// and is reachable at CLIM_MIN_TOTAL_SAMPLES (26) valid months spread over
// CLIM_MIN_DISTINCT_MONTHS (9) calendar months. So "complete" here now means
// "every calendar month has a mean", NOT "every calendar month had 3 own
// samples", and it says nothing about record length. What it still guarantees -
// and this is the only thing any caller uses it for - is that
// deseasonalizeSeries() will drop NO reading, so the surviving series has no
// holes and its lag-1 pairs are real. The sample-count question is answered by
// climatologyCoverageNote()'s nWellSampledMonths, which is what the panels
// print, and the length question by the floors, which are separate numbers set
// by separate measurements.
function climatologyIsComplete(climatology){
  if(!climatology) return false;
  if(climatology._meta && climatology._meta.complete!==undefined) return !!climatology._meta.complete;
  for(var m=0;m<12;m++){ if(!climatology[m]||climatology[m].mean===undefined) return false; }
  return true;
}
function climatologyCoverageNote(climatology){
  var mt=(climatology&&climatology._meta)?climatology._meta:null;
  if(!mt) return 'climatology coverage unknown';
  // v10.159: an imputed climatology is complete by construction, so the honest
  // coverage figure is how much of it came from real samples, not 12/12.
  if(mt.imputed) return mt.nWellSampledMonths+'/12 calendar months had '+mt.minSamples+
         '+ own samples, '+mt.nFullyImputedMonths+'/12 had none and were imputed from the '+
         'order-'+mt.harmonicOrder+' fitted annual cycle (from '+mt.nTotalSamples+
         ' valid months covering '+mt.nDistinctMonths+'/12 calendar months)';
  return mt.nUsableMonths+'/12 calendar months cleared the >='+mt.minSamples+
         '-samples floor (from '+mt.nTotalSamples+' valid months of data)';
}
// v10.160 S8 - DISCLOSED LATENT HAZARD: DESEASONALIZING MAKES THE RESIDUALS
// HETEROSCEDASTIC, AND THE PERMUTATION NULL DOES NOT MODEL THAT.
// Subtracting a climatology whose mean for calendar month m was estimated from
// that month's own few samples removes part of the noise along with the cycle,
// and it removes MORE of it the fewer samples that month has. MEASURED against
// this exact pair of functions - 12 calendar months each observed exactly k
// times, seasonal amplitude 10 smooth sine, TRUE per-reading noise SD 1.0,
// 20000 readings:
//     own samples in that calendar month   1     2     3     4     5     6
//     residual SD                         0.26  0.73  0.82  0.86  0.90  0.90
//     residual variance                   0.08  0.54  0.68  0.76  0.82  0.84
// A calendar month seen once has its residual variance deflated about 13-fold.
// permutationTestDeltaFixed() then pools ALL the residuals and shuffles them
// FREELY between the two windows, which assumes they are exchangeable - and the
// deseasonalizing is what destroyed that. If the BEFORE and AFTER windows have
// systematically different per-calendar-month sample counts (they do whenever
// they are different lengths, and whenever masking is seasonal), the pooled null
// mixes residuals of different scales.
// This is disclosed rather than fixed. It is NOT demonstrated to inflate the
// false-positive rate at the configurations this file now allows: measured 4.3%
// at 36+36, 4.5-5.9% at 24+12 and 5.5-7.0% at 18+12 against a nominal 5% (see
// the v10.160 table in the header). It is one of the reasons the floors are
// where they are - more samples per calendar month means less deflation and less
// variation in it - and it is a reason to prefer the LONGEST windows the record
// supports. A correct fix is a stratified or restricted permutation that shuffles
// within calendar month, which is a different design and is not attempted here.
function deseasonalizeSeries(seriesTV, climatology){
  return (seriesTV||[]).map(function(s){
    if(s.v===null||s.v===undefined||isNaN(s.v)) return {t:s.t, v:null};
    var m=new Date(s.t).getUTCMonth();
    var clim=climatology[m];
    if(!clim||clim.mean===undefined) return {t:s.t, v:null};
    return {t:s.t, v:s.v-clim.mean};
  });
}
// Batches monthly extraction across ALL points in ptsFC into ONE
// FeatureCollection (one evaluate() call covers every node's whole time
// series), instead of one .evaluate() per node. For each image in
// monthlyColl, reduceRegions() samples every point in ptsFC at once; the
// per-image results (tagged with that image's time) are flattened into a
// single flat table.
function extractMultiNodeSeries(monthlyColl, ptsFC, bandName, scale) {
  var n = monthlyColl.size();
  var imgList = monthlyColl.toList(n);
  var perImageList = ee.List.sequence(0, n.subtract(1)).map(function(i){
    var img = ee.Image(imgList.get(i));
    var t = img.get('system:time_start');
    // v10.167 FIX 20 / S1: tileScale:4 added. The standard Earth Engine remedy
    // for the per-graph memory pressure inferred from the empty returns above;
    // it costs nothing when it is not needed. UNTESTED against live EE.
    var reduced = img.select([bandName]).reduceRegions({collection:ptsFC, reducer:ee.Reducer.mean(), scale:scale, tileScale:4});
    return reduced.map(function(f){ return f.set('t', t); });
  });
  return ee.FeatureCollection(perImageList).flatten();
}

// ============================================================
// v10.167 FIX 20 / S1 - THE FAI MULTI-NODE FETCH, DIAGNOSED AND CHUNKED.
//
// WHAT WAS OBSERVED (live browser runs at Bocas del Toro, 9.175 -81.986 -
// these are real observations, not simulations):
//   S7C  3 nodes, 24 months (2023-01 +24)                  WORKS, 8 valid months/node
//   S7D  9 nodes, 25-month union (2022-01+24 / 2023-01+12) returns, 0 raw features
//   S7D  9 nodes, 32-month union (2021-06+24 / 2023-01+12) returns, 0 raw features
//   S7E/S7F 2 sites, 36-month union (2021-01+24 / 2023-01+12) NEVER RETURNS
//   (earlier, v10.162-era) 9 nodes x 12-month AFTER window   returned all 108 features
// In every S7D case the FAI pre-check reported scenes DO exist at this exact
// point (BEFORE 9 of 24 months | AFTER 4 of 12 months), and S7C proves FAI
// genuinely resolves here.
//
// WHAT THE EVIDENCE ACTUALLY SAYS - three hypotheses ruled OUT first:
//  1. NOT span length. S7C works at 24 months and S7D fails at 25, but those
//     two numbers are not comparable: S7C and S7D do not share a fetch path.
//     Comparing them is comparing two different functions, not two spans.
//  2. NOT node count. S7E fails with TWO sites. A 9-vs-3 explanation cannot
//     cover a 2-site failure.
//  3. NOT a labelling/grouping bug. groupSeriesByLabel() does silently drop a
//     feature with no `label` - but S7D's own diagnostic counts RAW features
//     BEFORE grouping (combinedFeatCount), and the live run reported 0 there.
//     The features never arrived; there was nothing for the grouper to drop.
//     TRACED, not run: ptsFC sets `label` on every feature, reduceRegions
//     carries non-reducer properties through untouched, f.set('t',t) preserves
//     them, flatten() preserves them, and groupSeriesByLabel() buckets on
//     exactly that key. There is no path here that produces an unlabelled
//     feature.
//
// WHAT DOES SEPARATE EVERY FAILURE FROM EVERY SUCCESS: the code path.
// EVERY failing FAI fetch goes through extractMultiNodeSeries(); EVERY
// succeeding one goes through computeRealCSDDeseasonalized()/
// computeZonalSyncCSD(). Line by line, that is the only structural
// difference - the two paths agree on the collection builder (mkMoFAIRange),
// the band ('fai'), the scale (20 m), the buffer (150 m) and the site:
//
//   WORKING (S7C)                        FAILING (S7D/S7E/S7F)
//   monthlyColl.map(img => ...)          toList() + ee.List.sequence().map()
//   img.reduceRegion(ONE geometry)       img.select([b]).reduceRegions(ptsFC)
//   maxPixels: 1e9 set                   no maxPixels, no tileScale
//   output = nMonths features            output = nMonths x nRegions features
//   one region per graph                 2 or 9 regions per graph
//   no label (positional {t,v})          label carried through flatten()
//
// So the failing path asks ONE .evaluate() to build nMonths Sentinel-2 monthly
// median composites AND materialize nMonths x nRegions features out of them,
// unchunked and unbounded. Ordering the observations by that per-call work:
//   12 mo x 9 = 108 elements   -> returned, fully populated
//   24 mo x 9 = 216            -> returned EMPTY
//   25 mo x 9 = 225            -> returned EMPTY
//   32 mo x 9 = 288            -> returned EMPTY
//   36 mo x 9 = 324 (+36 x 2)  -> never returned
// The two failure MODES are ordered by that number; the failure itself is not.
// HONEST LIMIT ON THIS CLAIM: what happens server-side between "216 elements"
// and "empty result with no error" cannot be observed from here - there is no
// Earth Engine access from this session. The mechanism is INFERRED (a memory /
// element / payload ceiling on one graph, which EE has been seen to surface as
// an empty table rather than an error). What is NOT inferred is which code
// path fails and which does not: that is 5 for 5 in the observations above.
//
// THE FIX: stop sending one unbounded graph. The span is cut into chunks whose
// per-call work never exceeds the LARGEST CONFIGURATION EVER OBSERVED TO
// RETURN DATA ON THIS PATH - 12 months x 9 nodes = 108 features. Both bounds
// are taken from that same observation and nothing else; neither is a guess at
// where the real ceiling sits, because the real ceiling has not been measured.
// The chunks are fetched SEQUENTIALLY (bounded concurrency - this file has hit
// the account concurrency quota before) and merged client-side by label and
// timestamp, which is the same fetch-once-and-slice arithmetic v10.162 already
// established. tileScale:4 is added to the reduceRegions call as well: it is
// the standard EE remedy for exactly the memory pressure inferred above, it
// costs nothing when it is not needed, and it is UNTESTED here.
//
// WHICH FAILURE EACH CHANGE ADDRESSES:
//   - chunking + tileScale  -> the "returns 0 raw features" failure (S7D)
//   - chunking + the per-call deadline below -> the "never returns" failure
//     (S7E/S7F). Chunking alone cannot fix a hang; it only makes each call
//     small enough that hanging is less likely and names WHICH chunk stalled.
//     The deadline is what turns a stall into a visible refusal.
//   - S7C is NOT changed. It is the one configuration observed to work, and
//     nothing here is worth risking it on.
var S7_FAI_MAX_ELEMENTS_PER_CALL = 108;  // 12 months x 9 nodes - the largest OBSERVED to return
var S7_FAI_MAX_MONTHS_PER_CALL   = 12;   // the month count of that same observation

// How many months one chunked call may cover, given how many regions ride
// along in it. Pure - unit tested in Node.
function s7FaiChunkMonths(nRegions){
  var r = Math.max(1, nRegions||1);
  var byElements = Math.floor(S7_FAI_MAX_ELEMENTS_PER_CALL / r);
  return Math.max(1, Math.min(S7_FAI_MAX_MONTHS_PER_CALL, byElements));
}
// The calendar-month grid ONE fetch must cover to serve both windows. Anchored
// on the first of the month (not the user's day-of-month) so every chunk after
// the first sits on the SAME grid - a grid that shifted between chunks would
// duplicate or skip months when the halves were merged. Window slicing is
// unaffected: sliceSeriesByWindow() takes the half-open interval
// [start, start+n months), which contains exactly one point of a monthly grid
// per month wherever the grid is anchored.
function s7FaiGridSpan(beforeStart, beforeMonths, afterStart, afterMonths){
  var bS=ymdToUTCms(beforeStart), aS=ymdToUTCms(afterStart);
  if(bS===null||aS===null) return null;
  var bE=addMonthsUTCms(bS,beforeMonths), aE=addMonthsUTCms(aS,afterMonths);
  var sD=new Date(Math.min(bS,aS)), eD=new Date(Math.max(bE,aE));
  var sY=sD.getUTCFullYear(), sM=sD.getUTCMonth();
  // The window end is EXCLUSIVE, so the last month the grid must carry is the
  // month of (end - 1 ms). A window ending exactly on the 1st does not need
  // that month's composite.
  var eD2=new Date(Math.max(bE,aE)-1);
  var nMonths=(eD2.getUTCFullYear()-sY)*12 + (eD2.getUTCMonth()-sM) + 1;
  return {startDateStr: sY+'-'+((sM+1<10?'0':'')+(sM+1))+'-01',
          nMonths: Math.max(1, nMonths), endExclusiveMs: eD.getTime()};
}
// Cut a grid into chunks. Returns [{start,months,index,expected}, ...]. Pure.
function s7FaiChunkPlan(gridStartStr, nMonths, nRegions){
  var per=s7FaiChunkMonths(nRegions), out=[], done=0;
  if(!gridStartStr || !(nMonths>0)) return out;
  while(done<nMonths){
    var take=Math.min(per, nMonths-done);
    var st=faiAddMonthsStr(gridStartStr, done);
    if(st===null) return [];
    out.push({start:st, months:take, index:out.length, expected:take*Math.max(1,nRegions||1)});
    done+=take;
  }
  return out;
}
// Merge the chunk payloads into one reduceRegions-shaped result, de-duplicated
// on (label, t) so an overlapping grid could never double-count a month. Pure.
function mergeFaiChunkResults(parts){
  var feats=[], seen={};
  (parts||[]).forEach(function(fc){
    if(!fc||!fc.features) return;
    fc.features.forEach(function(f){
      var p=(f&&f.properties)||{};
      var k=String(p.label)+'|'+String(p.t);
      if(seen[k]) return;
      seen[k]=1; feats.push(f);
    });
  });
  return {type:'FeatureCollection', features:feats};
}
// How many EE calls a module's series fetch will cost, so every on-screen
// string can be DERIVED from the plan instead of quoting a stale literal.
function s7FaiCallCount(gridStartStr, nMonths, nRegions){
  return s7FaiChunkPlan(gridStartStr, nMonths, nRegions).length;
}

// ---- the per-call deadline -------------------------------------------------
// v10.161 S6a said plainly: "a callback that never fires still never fires.
// Without a timer this cannot be turned into an automatic failure." That was
// true of the GLOBAL setTimeout, which the GEE sandbox does not expose. The
// Code Editor's own ui.util namespace does expose setTimeout/clearTimeout, and
// that is what this uses - FEATURE-DETECTED, never assumed. If it is absent the
// modules behave exactly as they did before and SAY SO on screen, rather than
// silently promising a deadline they cannot enforce.
var S7_CALL_DEADLINE_MS = 240000;   // 4 minutes per chunked call
function s7DeadlineAvailable(){
  try { return (typeof ui!=='undefined') && !!ui.util && typeof ui.util.setTimeout==='function'; }
  catch(eDA){ return false; }
}
function s7SetDeadline(ms, fn){
  if(!s7DeadlineAvailable()) return null;
  try { return ui.util.setTimeout(fn, ms); } catch(eSD){ return null; }
}
function s7ClearDeadline(h){
  if(h===null||h===undefined) return;
  try { if(s7DeadlineAvailable() && typeof ui.util.clearTimeout==='function') ui.util.clearTimeout(h); }
  catch(eCD){}
}
var S7_DEADLINE_NOTE = s7DeadlineAvailable() ?
  ('A call that does not return within '+Math.round(S7_CALL_DEADLINE_MS/60000)+
   ' minutes is REFUSED on screen rather than left waiting.') :
  ('NO TIMER AVAILABLE in this sandbox build - a call that never returns will leave this\n'+
   'panel waiting. The line below names which call, and pressing RUN again is a clean retry.');

// ---- the chunked, sequential, deadline-guarded series fetch ----------------
// cfg: {gridStartStr, nMonths, ptsFC, nRegions, band, scale, tag, isCurrent, onProgress}
// onDone({ok:true,  fc, plan, nCalls, shortChunks})
// onDone({ok:false, reason, detail, plan, nCalls, chunkIndex, fc})
function fetchFaiSeriesChunked(cfg, onDone){
  var plan=s7FaiChunkPlan(cfg.gridStartStr, cfg.nMonths, cfg.nRegions);
  var tag=cfg.tag||'S7';
  if(plan.length===0){ onDone({ok:false, reason:'plan', detail:'Could not build a month grid from the dates given.',
                               plan:plan, nCalls:0, chunkIndex:-1}); return; }
  var parts=[], shortChunks=[], i=0;
  function current(){ return cfg.isCurrent ? cfg.isCurrent() : true; }
  function step(){
    if(!current()) return;                      // v10.161 S6a stale-run guard
    if(i>=plan.length){
      onDone({ok:true, fc:mergeFaiChunkResults(parts), plan:plan, nCalls:plan.length, shortChunks:shortChunks});
      return;
    }
    var ch=plan[i], settled=false, dl=null;
    if(cfg.onProgress) cfg.onProgress(i, plan.length, ch);
    var coll=mkMoFAIRange(ch.start, ch.months);
    var req=extractMultiNodeSeries(coll, cfg.ptsFC, cfg.band, cfg.scale);
    dl=s7SetDeadline(S7_CALL_DEADLINE_MS, function(){
      if(settled||!current()) return;
      settled=true;
      print('=== '+tag+' [series chunk '+(ch.index+1)+'/'+plan.length+'] DEADLINE - no response in '+
            S7_CALL_DEADLINE_MS+' ms ===');
      onDone({ok:false, reason:'deadline', chunkIndex:ch.index, plan:plan, nCalls:plan.length,
              detail:'Call '+(ch.index+1)+' of '+plan.length+' ('+ch.start.substring(0,7)+' + '+ch.months+
                     ' months, '+cfg.nRegions+' regions, '+ch.expected+' expected features) did not return within '+
                     Math.round(S7_CALL_DEADLINE_MS/60000)+' minutes.'});
    });
    req.evaluate(function(v,e){
      if(settled||!current()) return;
      settled=true; s7ClearDeadline(dl);
      var n=(v&&v.features)?v.features.length:0;
      if(e){
        print('=== '+tag+' [series chunk '+(ch.index+1)+'/'+plan.length+'] ERROR === '+e);
        onDone({ok:false, reason:'error', chunkIndex:ch.index, plan:plan, nCalls:plan.length, detail:String(e)});
        return;
      }
      print('=== '+tag+' [series chunk '+(ch.index+1)+'/'+plan.length+'] OK - '+n+' of '+ch.expected+' feature(s) ===');
      if(n===0){
        onDone({ok:false, reason:'empty', chunkIndex:ch.index, plan:plan, nCalls:plan.length,
                detail:'Call '+(ch.index+1)+' of '+plan.length+' ('+ch.start.substring(0,7)+' + '+ch.months+
                       ' months x '+cfg.nRegions+' regions) returned 0 features where '+ch.expected+
                       ' were expected. reduceRegions() emits one feature per region per image whether or not '+
                       'the pixels are masked, so 0 is a failed call, NOT a data gap.'});
        return;
      }
      if(n<ch.expected) shortChunks.push({index:ch.index, got:n, expected:ch.expected});
      parts.push(v); i++; step();
    });
  }
  step();
}
// The on-screen refusal for a chunked fetch that did not complete. One
// vocabulary for all three modules, so S7E/S7F refuse the way S7D already does.
function s7ChunkRefusalText(tag, res, nRegions){
  var head;
  if(res.reason==='deadline') head='NO RESPONSE - '+tag+' stopped waiting rather than leaving you on a frozen counter.';
  else if(res.reason==='empty') head='EMPTY RESULT - '+tag+' refused rather than rendering a table on missing data.';
  else if(res.reason==='error') head='EARTH ENGINE ERROR - '+tag+' refused.';
  else head='CANNOT RUN - '+tag+' refused.';
  return head+'\n'+(res.detail||'')+'\n'+
    'The '+(res.nMonths||(res.plan?res.plan.length:0))+'-call chunked fetch (v10.167: at most '+
    S7_FAI_MAX_MONTHS_PER_CALL+' months x '+nRegions+' regions = '+
    (S7_FAI_MAX_MONTHS_PER_CALL*nRegions)+' features per call, against the 108-feature configuration that '+
    'was OBSERVED to return) did not complete, so nothing is shown. Press RUN again for a clean retry, '+
    'or shorten the windows.';
}


// spatial autocorrelation across a landscape can be a STRONGER warning
// signal than temporal indicators, especially with short time series -
// so this is a genuinely different, complementary indicator family, not
// just another view of the same temporal data.
// spatialVar: pixel-to-pixel SST variance across the region for that period.
// spatialAC1: correlation between each pixel and its immediate 3x3
//   neighbourhood mean (a simple, defensible proxy for Moran's I / spatial
//   autocorrelation - rising values mean neighbouring pixels are becoming
//   more alike, i.e. spatial patches are forming, a classic pre-transition
//   pattern-formation signature).
// Best-effort by design: if the region is too small/data-sparse for a
// meaningful pixel sample, returns nulls rather than failing the caller.
function computeSpatialEWS(monthlyColl, region, scale) {
  var composite = monthlyColl.select('sst').mean();
  var pixCountDict = composite.reduceRegion({reducer:ee.Reducer.count(),geometry:region,scale:scale,maxPixels:1e9,bestEffort:true});
  var spatialVarDict = composite.reduceRegion({reducer:ee.Reducer.variance(),geometry:region,scale:scale,maxPixels:1e9,bestEffort:true});
  var kernel = ee.Kernel.square({radius:1,units:'pixels'});
  var neighborMean = composite.reduceNeighborhood({reducer:ee.Reducer.mean(),kernel:kernel,skipMasked:true}).rename('neighbor');
  var combined = composite.rename('orig').addBands(neighborMean);
  // v10.88: pass the WHOLE correlation dictionary through rather than
  // doing .get('correlation') server-side - the exact output key name
  // for a combined-input reducer like pearsonsCorrelation isn't something
  // that can be verified without live access, and .get() on a missing key
  // throws a hard server-side error. Extracting the right key client-side
  // (see extractSpatialAC1 below) degrades to "unavailable" instead of crashing.
  var corrDict = combined.reduceRegion({reducer:ee.Reducer.pearsonsCorrelation(),geometry:region,scale:scale,maxPixels:1e9,bestEffort:true});
  return ee.Dictionary({
    pixelCount: pixCountDict.get('sst'),
    spatialVar: spatialVarDict.get('sst'),
    corr: corrDict
  });
}

// Client-side, defensive: pull a correlation value out of whatever key
// name the pearsonsCorrelation reducer actually used, without assuming.
function extractSpatialAC1(corrObj) {
  var r = extractSpatialAC1Detail(corrObj);
  return r.value;
}
// v10.152 FIX 9: the value alone could not be trusted. Two real runs at
// two different sites, on different dates, both returned a spatial AC1
// delta of EXACTLY +0.000 - a bit-identical value from two independently
// computed pixel fields, which is a fallback signature, not a
// measurement. This version reports WHICH key it read, so the toolkit
// line can say plainly whether the pearsonsCorrelation reducer named its
// output the way this code assumes, or whether the last-resort loop
// grabbed some other numeric property.
function extractSpatialAC1Detail(corrObj) {
  if(!corrObj || typeof corrObj!=='object') return {value:null, key:null, how:'no dictionary returned'};
  var candidates=['correlation','orig_neighbor_correlation','neighbor_orig_correlation','pearsonsCorrelation'];
  for(var i=0;i<candidates.length;i++){
    var v=corrObj[candidates[i]];
    if(v!==undefined&&v!==null&&typeof v==='number'&&!isNaN(v))
      return {value:v, key:candidates[i], how:'named key'};
  }
  for(var k in corrObj){
    if(k==='_meta') continue;
    if(k.toLowerCase().indexOf('p-value')>=0||k.toLowerCase().indexOf('pvalue')>=0) continue;
    if(typeof corrObj[k]==='number'&&!isNaN(corrObj[k]))
      return {value:corrObj[k], key:k, how:'FALLBACK - no expected key found, took first numeric property'};
  }
  var keysSeen=[]; for(var k2 in corrObj){ keysSeen.push(k2); }
  return {value:null, key:null, how:'no numeric property at all (keys seen: '+
    (keysSeen.length?keysSeen.join(', '):'none')+')'};
}

// v10.100 NEW: empirical two-zone temporal synchronization (study reef vs
// the already-selected deep-water control site). This is the "empirical
// interaction/covariance network" idea applied minimally and safely: rather
// than inventing new zone geometries (reef flat / mangrove / channel, which
// would need habitat datasets not verified reliable in this environment),
// it reuses the control site STEP 3 already auto-selects. Tracks whether
// the study reef's month-to-month SST fluctuations become MORE correlated
// with the open-ocean control (rising synchronization - the site losing its
// local buffering/independence, the leading-indicator direction reported by
// Dakos et al. 2011, Am Nat 177:E153-E166) or LESS correlated (decoupling)
// between the BEFORE and AFTER periods.
// Honest limits, same as the rest of the toolkit: this is a correlation,
// not a mechanistic interaction coefficient (no J_ij), and shared external
// forcing (a marine heatwave hitting both sites) will raise this number
// with or without any real internal "frustration" - it is one more piece
// of evidence, not proof of anything on its own.
// v10.101 CAVEAT (found by re-checking this after it shipped, not caught
// beforehand): this correlates RAW monthly SST, not deseasonalized
// anomalies. Two ocean points within a few hundred km share a strong
// seasonal cycle (both warm in summer, cool in winter) that has nothing to
// do with critical slowing down, which likely pushes the baseline
// correlation toward a high ceiling regardless of any real coupling
// change. Supporting evidence: across every real test run in this tool's
// history, the core AC1 statistic (which has the same raw/linear-detrend-
// only issue) consistently landed in a narrow ~0.78-0.89 band across very
// different sites and periods - more consistent with a metric dominated by
// shared seasonal month-to-month autocorrelation than by genuine site-
// specific dynamics. A proper fix requires per-zone monthly climatology
// subtraction before correlating; not implemented here because it needs
// live testing to verify before trusting it. Until then: read the DELTA
// (change vs BEFORE), not the absolute correlation value, and weight this
// indicator as lower-confidence.
function computeZonalSyncCSD(monthlyColl, zoneA, zoneB, bandName, scale) {
  var pairedFC = ee.FeatureCollection(monthlyColl.map(function(img){
    var vA = img.reduceRegion({reducer:ee.Reducer.mean(),geometry:zoneA,scale:scale,maxPixels:1e9}).get(bandName);
    var vB = img.reduceRegion({reducer:ee.Reducer.mean(),geometry:zoneB,scale:scale,maxPixels:1e9}).get(bandName);
    return ee.Feature(null, {vA:vA, vB:vB, t:img.get('system:time_start')});
  })).sort('t');
  var validFC = pairedFC.filter(ee.Filter.notNull(['vA','vB']));
  var n = validFC.size();
  return ee.Algorithms.If(n.gte(4),
    (function(){
      var arrA = ee.Array(validFC.aggregate_array('vA'));
      var arrB = ee.Array(validFC.aggregate_array('vB'));
      var meanA = arrA.reduce(ee.Reducer.mean(),[0]).get([0]);
      var meanB = arrB.reduce(ee.Reducer.mean(),[0]).get([0]);
      var devA = arrA.subtract(meanA), devB = arrB.subtract(meanB);
      var num = devA.multiply(devB).reduce(ee.Reducer.sum(),[0]).get([0]);
      var denA = ee.Number(devA.pow(2).reduce(ee.Reducer.sum(),[0]).get([0])).sqrt();
      var denB = ee.Number(devB.pow(2).reduce(ee.Reducer.sum(),[0]).get([0])).sqrt();
      var corr = ee.Number(num).divide(denA.multiply(denB).max(1e-6));
      return ee.Dictionary({corr:corr, n:n});
    })(),
    ee.Dictionary({corr:null, n:n}));
}

function analyzeThermalRecovery(monthlyFeatures, mmmValue) {
  if (mmmValue === null || mmmValue === undefined)
    return {error: 'No real MMM baseline available at this location - cannot compute recovery time.'};
  var threshold=mmmValue+1, episodes=[], currentEpisode=null, nValid=0, nGap=0;
  for (var i=0; i<monthlyFeatures.length; i++) {
    var props=monthlyFeatures[i].properties, v=props.v, dateStr=new Date(props.t).toISOString().slice(0,7);
    if (v===null||v===undefined) { nGap++; continue; }
    nValid++;
    if (v > threshold) {
      if (currentEpisode===null) currentEpisode={startDate:dateStr,months:1,peakSST:v};
      else { currentEpisode.months++; if(v>currentEpisode.peakSST) currentEpisode.peakSST=v; }
    } else {
      if (currentEpisode!==null) {
        currentEpisode.endDate=dateStr; currentEpisode.recovered=true;
        episodes.push(currentEpisode); currentEpisode=null;
      }
    }
  }
  var ongoing=null;
  if (currentEpisode!==null) { currentEpisode.recovered=false; ongoing=currentEpisode; }
  var completedDurations=episodes.map(function(e){ return e.months; });
  var meanRecovery=completedDurations.length>0?(completedDurations.reduce(function(a,b){return a+b;},0)/completedDurations.length):null;
  var maxRecovery=completedDurations.length>0?Math.max.apply(null,completedDurations):null;
  return {threshold:threshold,mmmValue:mmmValue,episodes:episodes,ongoingEpisode:ongoing,
    nCompletedEpisodes:episodes.length,meanRecoveryMonths:meanRecovery,maxRecoveryMonths:maxRecovery,
    nValidMonths:nValid,nGapMonths:nGap};
}

