// GO TO COORDINATES - v10.67 FIX: hemisphere-aware parseCoordPart()
panel.add(lbl('GO TO COORDINATES (use this, not the search bar above)',9,'#ffffff','#334466',true));
panel.add(lbl('Format: lat, lon  e.g. 13.5S, 112.3E  or  -13.5, 112.3  or  63.84, -22.43',7,'#555555'));
var coordInput = ui.Textbox({
  placeholder: 'lat, lon  e.g. 13.5S, 112.3E  or  64.13, -51.38 (Nuuk GEM)',
  style: {stretch:'horizontal', margin:'2px 4px', fontSize:'11px'}
});
panel.add(coordInput);
var coordStatusV = dynLbl('','#880000');
var goToCoordsBtn = ui.Button({
  label: 'GO (pans map + draws white ring + analyzes)',
  style: {fontSize:'11px',fontWeight:'bold',margin:'2px 4px',
    backgroundColor:'#cce0ff',color:'#003388',stretch:'horizontal',padding:'6px 4px',border:'2px solid #0055cc'},
  onClick: function(){
    var txt = (coordInput.getValue()||'').trim();
    if(!txt){ coordStatusV.setValue('Enter coordinates first, e.g. 13.5S, 112.3E'); return; }
    // v10.67 FIX (v10.19): use hemisphere-aware parser instead of raw parseFloat
    var rawParts = txt.split(',');
    if(rawParts.length!==2){ coordStatusV.setValue('Invalid format - use: lat, lon  (e.g. 13.5S, 112.3E  or  -13.5, 112.3)'); return; }
    var latIn=parseCoordPart(rawParts[0]), lonIn=parseCoordPart(rawParts[1]);
    if(isNaN(latIn)||isNaN(lonIn)){ coordStatusV.setValue('Invalid format - use: lat, lon  (e.g. 13.5S, 112.3E  or  -13.5, 112.3)'); return; }
    if(latIn<-90||latIn>90){ coordStatusV.setValue('Latitude must be -90..90'); return; }
    if(lonIn<-180||lonIn>180){ coordStatusV.setValue('Longitude must be -180..180'); return; }
    coordStatusV.setValue('Going to '+latIn+', '+lonIn+'...');
    coordStatusV.style().set('color','#115511');
    Map.setCenter(lonIn,latIn,11);
    // Draw white ring immediately before compute pipeline starts
    var immediateRing=ee.Geometry.Point([lonIn,latIn]).buffer(1000);
    while(Map.layers().length()>0){ Map.remove(Map.layers().get(0)); }
    Map.addLayer(ee.Image().byte().paint(immediateRing,0,3),
      {palette:['#ffffff'],opacity:1.0},'Study zone (white border)');
    analyzeLocation(latIn,lonIn);
  }
});
panel.add(goToCoordsBtn);
panel.add(coordStatusV);

// v10.83 FIX: GEE's server-side script sandbox does NOT support the ES6
// String.prototype.repeat() method. Calling it throws "TypeError:
// (intermediate value)... is not a function" - which is exactly what was
// silently killing FIND SWEET SPOT (and would have killed COMPARE's
// separator lines too). Use this loop-based helper everywhere instead.
function repeatChar(ch, n) {
  var s = '';
  for (var i = 0; i < n; i++) s += ch;
  return s;
}

// v10.88 NEW: "toolkit" tally helper - counts how many independent EWS
// indicators are available and how many agree in the CSD-consistent
// direction, rather than letting one indicator (historically: temporal
// variance) decide the verdict alone. Mirrors the "don't rely on a single
// indicator" guidance from the early-warning-signals literature.
// v10.90 FIX: previously every scored indicator (AC1, variance, spatial
// variance, spatial autocorrelation) counted as ONE EQUAL VOTE. Dakos et al.
// 2012 (Ecology 93:264-271) found this is not justified: autocorrelation
// "appears a relatively robust indicator... regardless of the source of
// noise" across every scenario they tested, while variance "may sometimes
// decrease close to a transition" for well-documented reasons (parameter-
// noise sensitivity changes, and a "freezing" effect in slow-responding
// systems - their Fig. 4). So AC1 not rising is more informative than
// variance not rising, and a variance-only rise deserves LESS confidence
// than an AC1-only rise - the opposite of a flat 1-vote-each tally. This
// rebuild treats AC1 as the PRIMARY indicator and everything else
// (temporal variance, spatial variance, spatial autocorrelation) as
// SUPPORTING evidence that raises or lowers confidence around it.
// v10.156 BUG-03 FIX: near-zero-denominator guard for S13.
// varTrendRatio = secondHalfVar / max(firstHalfVar, 1e-6), so a near-zero
// FIRST half inflates the ratio without any genuine surge. S7C already fixed
// this in v10.105 and S7D in v10.109, but S13 - COMPARE (STEP 3), FIND SWEET
// SPOT (STEP 4) and the STEP 2 readout - never got the guard. Real S13 runs
// produced +1276%, +2876% and +34.22x at a 6-month window, and a ratio like
// that fed a false "LOCAL CSD SIGNAL DETECTED" banner. This is the SAME rule,
// same numbers and same wording as S7C/S7D: first-half variance < 0.001 AND
// |ratio or delta| > 5 -> ARTIFACT, warned on screen and EXCLUDED from the
// CSD tally, the best-window selection and the headline verdict.
// ============================================================
// v10.162 S3 - THE BONFERRONI CLAIM RESTED ON PERMUTATION NOISE.
// OBSERVED, from a live FIND SWEET SPOT run: the 48-month row reported
// "Study AC1 p=0.023" against a corrected bar of 0.0250, and the panel
// concluded "At least one window survives the STRICTER Bonferroni-corrected
// bar - this is real evidence". At 300 shuffles p=0.023 IS 7/300: the p-value
// grid step is 1/300 = 0.0033, so a single shuffle landing the other way moves
// that row to 0.0200 or 0.0267 - across the bar, in either direction.
// INDEPENDENT EVIDENCE that 300 is too few, from an earlier live run: three
// rows flagged DUPLICATE - identical data, identical statistics (-0.70x,
// +0.214, -1.03x, +0.34x on all three) - returned control-variance p-values of
// 0.003 / 0.010 / 0.030. A tenfold spread with nothing varying but the shuffle
// draw.
// HOW THE NEW COUNT WAS CHOSEN (not picked round). The quantity that has to be
// resolved is the DISTANCE from an estimated p to the corrected bar, so the
// requirement is on the Monte Carlo standard error SE = sqrt(p(1-p)/B) AT the
// bar. The bar is 0.05/k for k powered windows, i.e. 0.0500 (k=1) down to
// 0.00833 (k=6). MEASURED in Node against the shipped permutationTestDeltaFixed
// (BEFORE 36 valid months, AFTER 48 - the heaviest row this panel builds):
//     B      SE at p=0.025    SE at p=0.00833    wall clock per test
//    300       0.00901          0.00525             20 ms
//   2000       0.00349          0.00203             49 ms
//  10000       0.00156          0.00091            187 ms
//  20000       0.00110          0.00064            337 ms
// 10000 puts the SE at the k=2 bar (0.0250, the live case) at 0.0016 - about
// 1/16 of the bar, and 5.8x tighter than 300 - while costing 187 ms per test.
// FIND SWEET SPOT fires at most 6 windows x 4 tests, and only the rows that can
// actually be COUNTED get the high count, so the realistic added cost is
// 8-16 tests x 187 ms = 1.5-3.0 s, with a 4.5 s worst case if every row is
// powered and distinct. That is small next to this panel's 8 Earth Engine calls
// (20-60 s), and it adds no EE work at all - the shuffles are client-side JS on
// series already fetched. 20000 would buy another 1.4x of precision for double
// the time, which is not the binding constraint.
// SEED-TO-SEED SPREAD, measured on ONE fixed dataset, 12 independent repeats of
// the same test: at B=300 the p-values spanned 0.6033-0.7000 (spread 0.0967);
// at B=10000, 0.6493-0.6653 (spread 0.0160).
// SUB-FLOOR and DUPLICATE rows keep 300: they are excluded from every tally,
// from the best-window pick and from the Bonferroni divisor, so no claim rests
// on them and there is nothing for extra precision to protect.
// WHAT 10000 STILL CANNOT DO: it does not make a claim irreversible, it makes
// the reversal MEASURABLE. Any p within 2 Monte Carlo SEs of the bar can still
// flip on a different seed, so the panel now computes that margin per row and
// SAYS SO on screen instead of asserting "this is real evidence". At the live
// 48-month numbers (p=0.023, bar 0.0250, B=10000) SE=0.0015 and p+2SE=0.0260,
// which is ABOVE the bar - so that exact row would now be reported as too close
// to call rather than as a survivor.
// v10.163 REGRESSION FIX: v10.162 ran EVERY countable row at 10000 shuffles.
// The permutation loop is CLIENT-SIDE JS on the browser's single main thread,
// and the GEE sandbox has no Web Worker and no setTimeout, so there is no way
// to yield mid-loop. OBSERVED in a real browser run at Bocas del Toro: STEP 4
// with two countable rows fired 2 rows x 4 tests x 10000 = 80000 statistic
// evaluations on top of 4 excluded rows x 4 x 300, and Chrome showed
// "Page Unresponsive". v10.161 did 6 x 4 x 300 = 7200, about 12x less.
// FIX: spend shuffles only where they can change a decision. Every row runs
// first at the diagnostic count; a row is RE-RUN at the high count only if its
// p-value lands near a decision boundary, where the extra precision is the
// difference between a claim and a coin flip. Typically that is zero or one
// row per scan, so the cost returns to roughly the v10.161 level while the
// precision lands exactly where the Bonferroni claim needed it.
// 3000, not 10000. RE-DERIVED this session against the shipped function: at the
// live 48-month figures (p=0.023, bar 0.0250) the SE is 0.0027 at B=3000 and
// 0.0015 at B=10000, and p+2SE is ABOVE the bar either way - so both report TOO
// CLOSE TO CALL and 10000 buys no different VERDICT, only a tighter number on a
// question it still cannot settle (that would take about B=100000). 3000 is the
// point where escalation still changes verdicts that are genuinely settleable
// without paying for ones that are not.
var CSD_PERM_N_COUNTED = 3000;       // escalation count - only for tests near a decision boundary
var CSD_PERM_N_DIAGNOSTIC = 300;     // first pass for every row, and final for excluded rows
// A row is escalated when its first-pass p-value sits within this many
// first-pass standard errors of either decision boundary (the uncorrected 0.05
// or the Bonferroni-corrected bar). At B=300 the SE near p=0.05 is about 0.013,
// so 4 SE is a window of roughly +/-0.05 around each boundary - wide enough that
// a row which would have crossed after escalation is not missed, narrow enough
// that a p of 0.3 or 0.9 never pays for precision it cannot use.
var CSD_PERM_ESCALATE_SE = 4;
// v10.163: with adaptive escalation the four tests in one row can each carry a
// different shuffle count, so the row cannot print a single `nShuffles` any more
// - that variable is gone, and reading it is what threw
// "ReferenceError: nShuffles is not defined" in a live run. Report the counts
// actually used, from the test objects themselves.
function rowShuffleTxt(tests){
  var seen=[], i, n;
  for(i=0;i<tests.length;i++){
    n = (tests[i] && tests[i].nPerm) ? tests[i].nPerm : null;
    if(n===null) continue;
    if(seen.indexOf(n)===-1) seen.push(n);
  }
  if(seen.length===0) return 'n/a';
  seen.sort(function(a,b){return a-b;});
  if(seen.length===1) return String(seen[0]);
  return seen[0]+'-'+seen[seen.length-1]+' (escalated)';
}
// True when p is close enough to a boundary that 300 shuffles cannot settle it.
function permNeedsPrecision(t, bar){
  if(!t || t.pValue===null || t.pValue===undefined) return false;
  if(!t.nPerm || t.nPerm<=0) return false;
  var p=t.pValue, se=Math.sqrt(Math.max(p*(1-p),1e-9)/t.nPerm), w=CSD_PERM_ESCALATE_SE*se;
  if(Math.abs(p-0.05)<=w) return true;
  if(bar!==null && bar!==undefined && isFinite(bar) && Math.abs(p-bar)<=w) return true;
  return false;
}
// Monte Carlo standard error of an estimated permutation p-value, and whether a
// claim that it clears `bar` could be reversed by re-running with another seed.
function permMonteCarloSE(t){
  if(!t || t.pValue===null || t.pValue===undefined || !t.nPerm || t.nPerm<=0) return null;
  return Math.sqrt(Math.max(t.pValue,1/t.nPerm)*(1-t.pValue)/t.nPerm);
}
// true when p is below the bar but within 2 SE of it - i.e. "survives" is not
// safe to assert.
function permClaimIsSeedFragile(t, bar){
  var se=permMonteCarloSE(t);
  if(se===null || bar===null || bar===undefined) return false;
  return (t.pValue < bar) && ((t.pValue + 2*se) >= bar);
}

var CSD_VAR_ARTIFACT_VARFIRST = 0.001, CSD_VAR_ARTIFACT_MAG = 5;
// v10.162 S6 FIX - THE RULE LEAKED, AND THE `AND` WAS DOING THE LEAKING.
// OBSERVED IN A LIVE S7C RUN at Bocas del Toro (9.175, -81.981), verbatim:
//   Center: AC1=-0.146 Var=4.14x  (1st-half=0.0000, 2nd-half=0.0000)   [NOT flagged]
//   North:  AC1=0.009  Var=12.08x (1st-half=0.0000, 2nd-half=0.0000)  LIKELY ARTIFACT
// Both rows have a first-half variance that prints as 0.0000. North was flagged
// only because its ratio happened to land above 5 and Center was not flagged
// only because its ratio happened to land below it. The defect is structural,
// not a threshold that needs tuning: varTrendRatio = secondHalfVar /
// max(firstHalfVar, 1e-6), so once firstHalfVar is at or under the 1e-6 floor
// the denominator is a CONSTANT, the ratio is an arbitrary rescaling of the
// second half alone, and its MAGNITUDE carries no information about whether the
// ratio is trustworthy. Requiring |ratio| > 5 on top of a near-zero denominator
// therefore makes the magnitude threshold decide something it cannot know, and
// silently passes every artifact whose ratio happens to be small - 4.14x here.
// FIXED: a near-zero denominator is now disqualifying ON ITS OWN. The magnitude
// argument is still accepted (every call site passes it) but no longer gates the
// flag; it is used only for wording.
// WHAT THIS DOES NOT DO - MEASURED, not assumed. The worry is that dropping the
// magnitude condition starts flagging genuine variance surges. It cannot, and the
// reason is arithmetic rather than empirical: a genuine surge has a REAL first
// half, and a real first half is not < 0.001. Re-ran the earlier sweep to confirm
// on the shipped code path (see the v10.162 changelog for the measured rate).
// v10.170 FAI-01 - THE THRESHOLD HAD UNITS, AND FAI IS NOT IN THOSE UNITS.
// REPORTED from live runs of v10.168/v10.169: EVERY S7D node was flagged
// ⚠ARTIFACT at Hawaii (all 9) and again at Bocas del Toro. A flag that fires
// on 100% of rows is not detecting anything - it had become a rename of "this
// row is FAI" - and it cost the entire ΔVar column at both sites.
// TRACED: CSD_VAR_ARTIFACT_VARFIRST is an ABSOLUTE variance threshold, 0.001,
// and a variance carries the SQUARE of its variable's units. It was set on SST,
// whose deseasonalized residual variance runs roughly 0.05-1.0 degC^2, so 0.001
// sits far below any real SST first half and the rule discriminated properly
// there. FAI is a dimensionless index: at Bocas the observed FAI spread across
// all nine nodes is about +/-0.001 TOTAL, so its residual variance is ~1e-7, and
// even at Hawaii (FAI 0.136) the first-half variance lands under 1e-3. Against a
// 0.001 cut, "varFirst < 0.001" is simply ALWAYS TRUE for FAI. Nothing was
// measured; the predicate was a constant.
// FIXED, and deliberately NOT by retuning 0.001 to some smaller FAI-shaped
// number - that would just move the same units bug to the next variable. The
// test is now UNIT-FREE, and asks the two questions that actually make a ratio
// untrustworthy:
//   (a) DOES THE FLOOR BIND? ratio = v1 / max(v0, CSD_VAR_RATIO_FLOOR). Once v0
//       reaches that floor the denominator is a CONSTANT and the ratio is an
//       arbitrary rescaling of the second half alone. Testing v0 against a small
//       multiple of the floor is unit-free because the floor is the thing being
//       compared against, not a guess about the variable's scale.
//   (b) IS THE DENOMINATOR DEGENERATE RELATIVE TO THIS SERIES' OWN SPREAD? Flag
//       when the first half carries under CSD_VAR_ARTIFACT_REL_FRAC of the
//       window's mean half-variance. Note what this reduces to algebraically:
//       v0 < f*(v0+v1)/2  is EXACTLY  v1/v0 > 2/f - 1, so at f=0.02 it is the
//       ratio exceeding 99x. That is stated plainly rather than dressed up - a
//       99x variance ratio is a degenerate denominator, not a physical surge.
// varScaleRef is OPTIONAL and every existing SST call site omits it, so those
// keep the legacy absolute rule byte-for-byte and none of the v10.153 SST
// calibration is touched by this commit. The FAI call sites (S7C, S7D) pass it.
var CSD_VAR_ARTIFACT_FLOOR_MULT = 10;   // (a): v0 <= 10 * CSD_VAR_RATIO_FLOOR
var CSD_VAR_ARTIFACT_REL_FRAC   = 0.02; // (b): v0 < 2% of mean half-variance (ratio > 99x)
function isVarRatioArtifact(varFirst, magnitude, varScaleRef) {
  if(varFirst===null || varFirst===undefined || isNaN(varFirst)) return false;
  // unit-free branch - used wherever the caller can supply this series' own scale
  if(typeof varScaleRef==='number' && isFinite(varScaleRef) && varScaleRef>0){
    if(varFirst <= CSD_VAR_RATIO_FLOOR*CSD_VAR_ARTIFACT_FLOOR_MULT) return true;
    return varFirst < CSD_VAR_ARTIFACT_REL_FRAC*varScaleRef;
  }
  // legacy absolute branch - unchanged, still what every SST call site gets
  return varFirst < CSD_VAR_ARTIFACT_VARFIRST;
}
// Scale reference for the unit-free branch: the mean of this window's two half
// variances. Returns null when either half is missing, which sends the caller
// back to the legacy rule rather than silently passing a bogus scale.
function varScaleRefOf(varFirst, varSecond){
  if(varFirst===null||varFirst===undefined||isNaN(varFirst)) return null;
  if(varSecond===null||varSecond===undefined||isNaN(varSecond)) return null;
  var m=(varFirst+varSecond)/2;
  return (isFinite(m)&&m>0)?m:null;
}
var CSD_VAR_ARTIFACT_MSG_RELATIVE =
  '\u26A0 ARTIFACT RULE (v10.170, unit-free): a \u0394Var is flagged when the first-half variance either sits at the '+
  'ratio floor ('+CSD_VAR_RATIO_FLOOR+', so the denominator is a constant and the ratio is an arbitrary rescaling of the '+
  'second half) or falls under '+(CSD_VAR_ARTIFACT_REL_FRAC*100)+'% of this window\'s own mean half-variance - which is '+
  'algebraically the same as a variance ratio above '+Math.round(2/CSD_VAR_ARTIFACT_REL_FRAC-1)+'x. Through v10.169 the '+
  'test was an ABSOLUTE variance cut of '+CSD_VAR_ARTIFACT_VARFIRST+', set on SST (residual variance ~0.05-1.0 degC^2). '+
  'FAI is dimensionless and its residual variance is orders of magnitude smaller, so that cut was TRUE FOR EVERY FAI ROW '+
  'EVER TESTED - it flagged all 9 nodes at Hawaii and all 9 at Bocas, which is a constant, not a measurement. The rule '+
  'above has no units and so cannot fail that way on the next variable either.';
var CSD_VAR_ARTIFACT_MSG =
  '⚠ LIKELY ARTIFACT: first-half variance is near-zero (<'+CSD_VAR_ARTIFACT_VARFIRST+'), so the variance '+
  'ratio is divided by the 1e-6 floor rather than by a real number - treat this Var value with real caution, '+
  'not as a genuine surge, AT ANY RATIO. v10.162: the flag no longer also requires |ratio|>'+CSD_VAR_ARTIFACT_MAG+
  ' - a live run showed a 4.14x and a 12.08x row with the SAME 0.0000 first half, one flagged and one not. It is '+
  'EXCLUDED from the CSD tally and from the headline verdict (same rule as S7C v10.105 / S7D v10.109).';

// v10.156 BUG-08 FIX: measured power of permutationTestDeltaFixed (Monte
// Carlo, BEFORE phi=0.2 vs AFTER phi). At 24 months the test has essentially
// NO power, yet STEP 2 accepted windows down to 4 months, the worked example
// suggested 24, and FIND SWEET SPOT tested 6/9/12-month windows and could name
// one of them a "sweet spot". These numbers are now shown on screen and used
// as real guard rails: below the floor the test is refused outright; floor-to-47
// months is warned prominently; FIND SWEET SPOT's sub-floor rows are
// labelled UNDERPOWERED and excluded from the best-window pick and the tally.
//
// v10.158 W-01 FIX (BLOCKER): that floor was 24 - which was the ONE window
// length at which the permutation test could not run at all. The climatology
// needs CLIM_MIN_SAMPLES_PER_MONTH=3 samples in each of 12 calendar months;
// 24 months gives exactly 2, so 0 of 12 months survive, every point is
// dropped, and the test returned pValue:null. Measured across totals 20->60
// it worked at 20, 22 and 28+ and returned NULL at 24 and 26; the AC1 variant
// died outright at n=24 with 'insufficient data after processing (n=0)'.
// v10.156 BUG-08 had pointed users at precisely that dead spot.
// The floor is now 36 = 12 calendar months x 3 samples, the shortest window
// that CAN produce a complete climatology. CSD_DESEASON_MIN_MONTHS below is
// the same number by construction and is what the three permutation tests
// gate on, so the gate and the climatology floor cannot disagree again.
var CSD_MIN_WINDOW_MONTHS = 36;      // hard block below this
var CSD_RECOMMENDED_WINDOW_MONTHS = 48; // prominent warning below this
var CSD_MAX_WINDOW_MONTHS = 60;      // longest window STEP 2 / STEP 4 accept
// v10.159 N2 FIX: v10.158's changelog claimed the on-screen "6" / "13" / "24
// tests" strings were "now derived too". They were not - they were still three
// hardcoded literals in panel labels and one in the startup block, which is
// exactly the desync the claim said had been removed. The window list now lives
// here, at module scope, so the labels and the onClick handler read the SAME
// array and the counts below are computed from it.
//   windows           = CSD_SWEET_SPOT_WINDOWS.length              (6)
//   permutation fetches= 4 raw {t,v} series (study/ctrl x BEFORE/AFTER-max)
//   parallel EE calls  = windows*2 + 1 control-BEFORE + 4           (17)
//   permutation tests  = windows * 4 (study/ctrl x AC1/var)         (24)
// v10.160 NIT: CSD_SWEET_SPOT_NCALLS was windows*2+1 = 13, which CONTRADICTED the
// real budget the onClick handler counts (multiTotal = windowLengths.length*2+1+4
// = 17) and the panel label that printed 17. The 4 permutation-test raw-series
// fetches were missing from it. It is now the same expression as multiTotal, and
// multiTotal is now written in terms of it so there is one definition.
// CSD_SWEET_SPOT_NPERMTESTS was defined and referenced by nothing; it is kept
// because the panel text quotes the count, and it is now actually used below.
var CSD_SWEET_SPOT_WINDOWS = [12,24,36,48,54,60];
var CSD_SWEET_SPOT_NWINDOWS = CSD_SWEET_SPOT_WINDOWS.length;
var CSD_SWEET_SPOT_NPERMFETCHES = 4;   // study/ctrl x BEFORE/AFTER-max raw series
var CSD_SWEET_SPOT_NCALLS = CSD_SWEET_SPOT_NWINDOWS*2 + 1 + CSD_SWEET_SPOT_NPERMFETCHES;
var CSD_SWEET_SPOT_NPERMTESTS = CSD_SWEET_SPOT_NWINDOWS*4;
function csdSweetSpotPoweredList(){
  var out=[];
  for(var i=0;i<CSD_SWEET_SPOT_WINDOWS.length;i++)
    if(CSD_SWEET_SPOT_WINDOWS[i]>=CSD_MIN_WINDOW_MONTHS) out.push(CSD_SWEET_SPOT_WINDOWS[i]);
  return out;
}
// The deseasonalizing gate used by permutationTestDeltaFixed,
// permutationTestAC1Fixed and permutationTestCorrDelta. Derived, not typed:
// 12 calendar months x CLIM_MIN_SAMPLES_PER_MONTH samples each. Below it the
// tests still RUN, on RAW values, and say so - they no longer return null.
// v10.159 W-01: this is no longer the gate for anything. It was the "pooled
// months needed for a 12/12 climatology" threshold, and the 12/12 rule it served
// is gone - computeUsableClimatology()'s own CLIM_MIN_TOTAL_SAMPLES /
// CLIM_MIN_DISTINCT_MONTHS floors decide now, and they were set by measurement
// rather than by this arithmetic. v10.160: the power-table text below no longer
// quotes it either - it quotes CLIM_MIN_TOTAL_SAMPLES and
// CSD_AC1_MIN_POOLED_MONTHS, the two constants that are actually branched on. It
// is kept solely because several historical changelog entries above name it.
// NOTHING IN THE FILE BRANCHES ON IT. If you are looking for the number a test
// gates on, it is one of those two, not this.
var CSD_DESEASON_MIN_MONTHS = 12 * CLIM_MIN_SAMPLES_PER_MONTH;   // = 36 (documentation only)
// v10.160: RE-DERIVED. The v10.158/v10.159 text that stood here quoted a power
// table whose design was never recorded, and its closing sentence ("the
// permutation test returned NO p-value at all at 24 and 26 months") contradicted
// the STEP 4 label printed in the same panel, which said that claim was no longer
// true. Both are replaced by one table, measured this session against the shipped
// functions, with its design stated.
var CSD_POWER_TABLE_TXT =
  'MEASURED POWER AND FALSE-POSITIVE RATE OF THIS TEST (v10.160, Monte Carlo).\n'+
  'DESIGN, so these numbers are reproducible: monthly series, seasonal cycle +\n'+
  'noise, per-reading noise SD 1.0, random start calendar month, BEFORE->AFTER gap\n'+
  'uniform 0-3 months, 300 shuffles per test, 2000 replicates per cell, nominal 5%.\n'+
  'Monte Carlo standard error is about 0.5 percentage points near 5%, so single cells\n'+
  'move by ~1 point between runs; the differences below are much larger than that.\n'+
  'v10.162 NOTE ON THE SHUFFLE COUNT: this table was measured at 300 shuffles per\n'+
  'test, which is no longer what STEP 4 runs. STEP 4 now uses '+CSD_PERM_N_COUNTED+' shuffles on any\n'+
  'row that can be counted and '+CSD_PERM_N_DIAGNOSTIC+' only on the transparency-only rows. The shuffle\n'+
  'count sets the PRECISION of an individual p-value (its Monte Carlo SE), not the\n'+
  'test\'s power or its false-positive RATE, which are properties of the statistic and\n'+
  'the window length - so the rates below still describe the shipped test. They are\n'+
  'NOT re-measured at '+CSD_PERM_N_COUNTED+', and are not claimed to be.\n'+
  '\n'+
  'AC1 STATISTIC - balanced windows, AR(1) noise, BEFORE phi=0.2 vs AFTER phi,\n'+
  'seasonal amplitude 3 on a smooth sine:\n'+
  '  windows  | phi=0.2 (FPR) | phi=0.5 | phi=0.7 | phi=0.9\n'+
  '  12+12    |   NO p-VALUE  |    -    |    -    |    -\n'+
  '  18+18    |   NO p-VALUE  |    -    |    -    |    -\n'+
  '  24+24    |      4%       |    9%   |   17%   |   25%\n'+
  '  36+36    |      5%       |   15%   |   34%   |   52%\n'+
  '  48+48    |      5%       |   22%   |   53%   |   75%\n'+
  '12+12 and 18+18 return NO p-value because they pool 24 and 36 months, under the\n'+
  'AC1-specific floor of '+CSD_AC1_MIN_POOLED_MONTHS+' pooled valid months (v10.160 BLOCKER 3). Below that floor\n'+
  'the AC1 statistic is not merely weak, it is DEAD: measured false-positive rate\n'+
  '0.2% at 24 pooled months and 2.0% at 30, against a nominal 5%, with 0.7-3.5%\n'+
  'power against an AR(1) phi 0 -> 0.8 change. v10.159 reported p-values there.\n'+
  'READ THE TABLE HONESTLY: even ABOVE the floor this test is not powerful. A real\n'+
  'loss of resilience from phi=0.2 to phi=0.7 is missed 5 times in 6 at 24+24 and\n'+
  '2 times in 3 at 36+36. A non-significant AC1 result is mostly evidence that the\n'+
  'window is short, not that nothing happened. Use the longest windows the record\n'+
  'supports.\n'+
  '\n'+
  'VARIANCE-RATIO STATISTIC - the same engine, different statistic. Real change =\n'+
  "AFTER window's second half at 5x the noise SD. Ranges span seasonal amplitude 3\n"+
  'and 10, smooth / sawtooth / summer-spike cycles, and gap 0 as well as gap 0-3:\n'+
  '  windows  |   FPR       | power against the 5x change\n'+
  '  18+12    | 5.5 - 7.0%  |  63.7 - 74.8%\n'+
  '  24+12    | 4.5 - 5.9%  |  66.0 - 70.2%\n'+
  '  48+24    | 4.8 - 5.4%  |  86.3 - 87.1%\n'+
  '  36+36    | 4.3 - 4.5%  |  96.4 - 96.8%\n'+
  'The variance statistic is the one carrying this tool at short windows. Its floor\n'+
  'is CLIM_MIN_TOTAL_SAMPLES = '+CLIM_MIN_TOTAL_SAMPLES+' pooled valid months, which is much lower than\n'+
  "the AC1 floor and is set by its own measurement - see that constant's comment.\n"+
  'NOTE the 18+12 row: it runs up to 7.0%, about 40% above nominal. That is the\n'+
  'v10.159 S7D/S7E default; v10.160 moves those defaults to 24+12.\n'+
  '\n'+
  'WHAT THIS TABLE DOES NOT COVER, stated rather than implied: the null is built by\n'+
  'shuffling deseasonalized residuals freely between the two windows, and\n'+
  'deseasonalizing makes those residuals heteroscedastic (see the S8 note above\n'+
  'deseasonalizeSeries). Nothing above shows that inflating the rate at these\n'+
  'configurations, but the assumption is not exactly true and it is one reason to\n'+
  'prefer long windows.';

function buildToolkitTally(indicators) {
  var lines=[], nAvail=0, nAgree=0;
  var primaryAvailable=false, primaryAgrees=false, primaryName=null;
  var supportAvail=0, supportAgree=0;
  indicators.forEach(function(ind){
    if(ind.scored){
      if(ind.available){
        nAvail++;
        if(ind.agrees) nAgree++;
        if(ind.primary){ primaryAvailable=true; primaryAgrees=!!ind.agrees; primaryName=ind.name; }
        else { supportAvail++; if(ind.agrees) supportAgree++; }
      }
      lines.push('  '+(ind.primary?'[PRIMARY - Dakos et al. 2012] ':'[supporting] ')+ind.name+': '+ind.display+
        (ind.available?(ind.agrees?'  [CSD-consistent]':'  [not rising]'):'  [unavailable]'));
    } else {
      lines.push('  '+ind.name+': '+ind.display+'  [reported, not scored]');
    }
  });
  return {lines:lines, nAvail:nAvail, nAgree:nAgree,
    primaryAvailable:primaryAvailable, primaryAgrees:primaryAgrees, primaryName:primaryName,
    supportAvail:supportAvail, supportAgree:supportAgree};
}

// AC1-weighted confidence classification, shared by STEP 3's live render
// and its final combined verdict. Returns {label, level} where level is
// one of 'high'/'moderate'/'low-moderate'/'low'/'none' for colour-coding.
// ============================================================
// ============================================================
// v10.154 FIX 11 - PERMUTATION TEST FOR A CORRELATION DELTA
//
// permutationTestDeltaFixed handles single-series statistics (AC1,
// variance ratio). S7D's headline statistic is different: the change in
// CORRELATION between a ring node and Center. That needed its own engine,
// because the null must preserve the within-month pairing - both nodes'
// values for a given month have to move together when labels are
// reshuffled, or the test destroys the very coupling it is measuring.
//
// Null hypothesis: BEFORE and AFTER months are exchangeable, i.e. the
// observed change in coupling is what random relabelling would produce.
//
// Deseasonalizes on a pooled climatology first, at the same >=24-month
// threshold used everywhere else in this file, so a shared seasonal cycle
// cannot inflate the correlation independent of real dynamics (the
// v10.101 caveat, which applies with extra force to a correlation between
// two nearby points).
function permutationTestCorrDelta(beforeA, beforeB, afterA, afterB, nPerm){
  nPerm = nPerm || 500;
  function align(sa, sb){
    var mb = {};
    (sb||[]).forEach(function(s){ if(s&&s.v!==null&&s.v!==undefined&&!isNaN(s.v)) mb[s.t]=s.v; });
    var out=[];
    (sa||[]).forEach(function(s){
      if(s&&s.v!==null&&s.v!==undefined&&!isNaN(s.v)&&mb[s.t]!==undefined)
        out.push({t:s.t, a:s.v, b:mb[s.t]});
    });
    return out;
  }
  var B=align(beforeA,beforeB), A=align(afterA,afterB);
  if(B.length<4 || A.length<4)
    return {observedDelta:null, corrBefore:null, corrAfter:null, pValue:null, nPerm:0,
            deseasonalized:false, permStatus:'unavailable',
            permReason:'insufficient paired months ('+B.length+'/'+A.length+', need 4+ in each window)',
            deseasonNote:'NOT TESTABLE - insufficient paired months ('+B.length+'/'+A.length+', need 4+ in each window)',
            note:'insufficient paired months ('+B.length+'/'+A.length+', need 4+ each)'};

  // shared climatology across both windows, both nodes.
  // v10.159 W-01 REGRESSION FIX: v10.158 gated this at CSD_DESEASON_MIN_MONTHS
  // and on a 12/12-complete climatology ON BOTH NODES, and ran on RAW paired
  // values otherwise - the same uncalibrated path measured at 10.4-39.8% false-
  // positive rate on the single-series version. S7D's default month boxes pool
  // 30 months, so this ALWAYS took the raw path. Now: computeUsableClimatology()
  // on each node (which imputes the calendar months it cannot estimate from
  // their own samples), and if EITHER node cannot produce one, the test returns
  // NO p-value rather than a raw one.
  var pooled=B.concat(A);
  var caRes=computeUsableClimatology(pooled.map(function(r){return {t:r.t,v:r.a};}));
  var cbRes=computeUsableClimatology(pooled.map(function(r){return {t:r.t,v:r.b};}));
  if(!caRes.ok || !cbRes.ok){
    var whyCorr=(!caRes.ok?caRes.reason:cbRes.reason);
    return {observedDelta:null, corrBefore:null, corrAfter:null, pValue:null, nPerm:0,
            deseasonalized:false, permStatus:'unavailable', permReason:whyCorr,
            deseasonNote:'NOT TESTABLE - '+whyCorr, note:'NOT TESTABLE - '+whyCorr};
  }
  var ca=caRes.climatology, cb=cbRes.climatology;
  var deseason=false, deseasonNote='';
  var dsB=[], dsA=[];
  function dsPair(arr){
    return arr.map(function(r){
      var m=new Date(r.t).getUTCMonth();
      return {t:r.t, a:r.a-ca[m].mean, b:r.b-cb[m].mean};
    });
  }
  dsB=dsPair(B); dsA=dsPair(A);
  if(dsB.length<4||dsA.length<4){
    return {observedDelta:null, corrBefore:null, corrAfter:null, pValue:null, nPerm:0,
            deseasonalized:false, permStatus:'unavailable',
            permReason:'too few paired months survived deseasonalizing',
            deseasonNote:'NOT TESTABLE - too few paired months survived deseasonalizing',
            note:'NOT TESTABLE - too few paired months survived deseasonalizing'};
  }
  B=dsB; A=dsA; deseason=true;
  deseasonNote='DESEASONALIZED against complete pooled climatologies on both nodes ('+
    climatologyCoverageNote(ca)+' / '+climatologyCoverageNote(cb)+').';
  function corr(arr){
    return jsPearsonCorr(arr.map(function(r){return r.a;}), arr.map(function(r){return r.b;}));
  }
  var cB=corr(B), cA=corr(A);
  if(cB===null||cA===null)
    return {observedDelta:null, corrBefore:null, corrAfter:null, pValue:null, nPerm:0,
            deseasonalized:deseason, permStatus:'unavailable',
            permReason:'the paired correlation itself is not computable on these two windows',
            deseasonNote:deseasonNote, note:'correlation unavailable'};
  var obs=cA-cB, all=B.concat(A), nB=B.length, cnt=0, valid=0;
  for(var i=0;i<nPerm;i++){
    var sh=all.slice();
    for(var j=sh.length-1;j>0;j--){
      var k=Math.floor(Math.random()*(j+1)), tmp=sh[j]; sh[j]=sh[k]; sh[k]=tmp;
    }
    var pB=corr(sh.slice(0,nB)), pA=corr(sh.slice(nB));
    if(pB===null||pA===null) continue;
    valid++;
    if(Math.abs(pA-pB)>=Math.abs(obs)) cnt++;
  }
  return {observedDelta:obs, corrBefore:cB, corrAfter:cA,
          pValue: valid>0 ? cnt/valid : null, nPerm:valid, deseasonalized:deseason,
          permStatus: valid>0 ? 'ok' : 'unavailable',
          permReason: valid>0 ? null : 'no shuffle produced a usable paired correlation',
          deseasonNote:deseasonNote};
}

// v10.153 FIX 10 - EMPIRICALLY CALIBRATED THRESHOLDS
//
// The >0.01 AC1 and >0.15x variance cutoffs were never calibrated
// against anything. They have now been MEASURED, using 13.6 years of
// 4-minute Scripps Pier CTD data (Jan 2013 - Aug 2026, 1.95M readings,
// QC-flagged: temperature, salinity, chlorophyll). La Jolla is a
// temperate kelp coast with no documented regime shift, so every
// threshold crossing there is a false positive by construction.
//
// Across 104-176 non-overlapping BEFORE/AFTER splits, deseasonalized
// exactly the way this tool does it:
//
//   window   AC1 delta sd   Var delta sd   FALSE-POSITIVE RATE, old cutoffs
//   24mo        0.247          3.003        AC1 51%,  Var 48%
//   36mo        0.205          2.826        AC1 46%,  Var 49%
//   48mo        0.166          1.853        AC1 34%,  Var 57%
//
// The AC1-OR-variance rule that S7E uses to declare a site signal fired
// on 80% of no-event temperature windows. The permutation test on those
// SAME windows rejected at 0-9% - correctly calibrated.
//
// Values below are the 95th percentile of |delta| under that null, i.e.
// the cutoff that actually delivers a 5% false-positive rate.
//
// READ THIS BEFORE TRUSTING THEM: calibrated cutoffs this large will
// almost never fire. That IS the honest conclusion - a fixed threshold
// cannot adapt to how noisy a particular site is, while the permutation
// test adapts per-site automatically. These values exist so the
// threshold branch stops manufacturing confident false positives, not
// because a fixed threshold is a good idea. The p-value is still the
// only verdict here with a known error rate.
var CSD_NULL_CALIBRATION = {
  24: {ac1:0.491, varr:7.311, n:176},
  36: {ac1:0.395, varr:7.020, n:140},
  48: {ac1:0.347, varr:4.797, n:104}
};
var CSD_USE_CALIBRATED_THRESHOLDS = true;   // false restores the old 0.01/0.15 behaviour

function getCalibratedThresholds(nMonths){
  if(!CSD_USE_CALIBRATED_THRESHOLDS)
    return {ac1:0.01, varr:0.15, n:0,
      basis:'UNCALIBRATED legacy cutoffs - measured false-positive rate 34-57%'};
  var keys=[24,36,48], best=keys[0], i;
  for(i=0;i<keys.length;i++){
    if(Math.abs(keys[i]-(nMonths||24))<Math.abs(best-(nMonths||24))) best=keys[i];
  }
  var c=CSD_NULL_CALIBRATION[best];
  // v10.159 N3: 54 and 60 are NOT calibration keys - the measured Scripps null
  // was cut at 24, 36 and 48 months only, so both land on 48 by nearest-match.
  // That is the conservative direction (the null spread shrinks as the window
  // grows, so a 48-month cutoff applied at 54 or 60 months is wider than the
  // right one and fires LESS often), but the basis string said "nearest
  // calibrated window 48mo" without saying the request was outside the
  // calibrated range at all. It now says so plainly.
  var req=(nMonths||24);
  var extrapolated=(req>keys[keys.length-1]);
  return {ac1:c.ac1, varr:c.varr, n:c.n, calibratedWindow:best, extrapolated:extrapolated,
    basis:'95th pct of |delta| under a measured no-event null (Scripps Pier CTD, '+
      c.n+' splits, nearest calibrated window '+best+'mo)'+
      (extrapolated?' - NOTE: '+req+' months is BEYOND the calibrated range (24/36/48mo were the '+
        'only lengths measured), so the '+best+'mo cutoff is reused. The null spread narrows as '+
        'the window lengthens, so this cutoff is WIDER than a '+req+'mo one would be and fires '+
        'less often - conservative, but not calibrated at this length.':'')};
}

// Attach to ANY verdict derived from a threshold rather than a p-value.
function thresholdOnlyWarning(){
  return 'THRESHOLD-ONLY VERDICT - no significance test was run in this module. '+
    'Fixed cutoffs were measured firing on up to 80% of windows at a site where '+
    'nothing happened. Read as a direction indicator, not as evidence.';
}
// ============================================================================
// v10.159 W-01 item 2 + W-02 DISCLOSURE HELPERS.
// Two separate defects made the same class of mistake: a machine-readable flag
// was returned and then never read.
//  (a) permutationTestDeltaFixed() has returned `deseasonalized` since v10.158
//      and `deseasonNote` on every return path, but exactly ONE of six render
//      sites printed it (STEP 3 COMPARE). STEP 4's sweet-spot table, S7D's
//      per-node AC1 column, S7D's pair-coupling column, S7E and S7F all printed
//      "p=..." bare.
//  (b) jsNodeStatsFixed() has returned climatologySource, climatologyNote,
//      ac1PairsUsed, ac1PairsDropped and ac1MaxGapMonths since v10.158 and NO
//      caller read any of them, while the file claimed the reason was "on
//      screen" and said so "loudly".
// Rather than repeat the same five lines at every site, every p-value in this
// file now goes through permP()/permVerdictTag() and every jsNodeStatsFixed
// result through nodeStatsDisclosure(). Adding a render site later gets the
// disclosure for free; forgetting to call them is visible as a bare p-value.
// permUsable() is the GATE: significance wording is allowed only when the test
// produced a p-value AND it was computed on a properly deseasonalized series.
function permUsable(t){
  return !!(t && t.pValue!==null && t.pValue!==undefined && t.deseasonalized===true);
}
// Why there is no p-value, in one line, for a table cell.
function permWhyNot(t){
  if(!t) return 'NOT TESTABLE (test did not run)';
  if(t.permStatus==='pending'||t.permStatus===undefined&&t.pValue===undefined) return 'pending';
  if(t.pValue===null||t.pValue===undefined) return 'NOT TESTABLE';
  if(t.deseasonalized!==true) return 'NOT CALIBRATED (raw series)';
  return '';
}
// The ONLY approved way to render a permutation p-value in this file.
function permP(t, decimals){
  if(permUsable(t)) return 'p='+t.pValue.toFixed(decimals===undefined?3:decimals);
  return permWhyNot(t);
}
// Significance wording, gated on permUsable() so a p-value computed on a raw,
// non-deseasonalized series can never be dressed up as "likely real".
function permVerdictTag(t){
  if(!permUsable(t)) return '';
  if(t.pValue<0.01) return ' *** likely real (p<0.01)';
  if(t.pValue<0.05) return ' * likely real (p<0.05)';
  return ' (not significant)';
}
// The long-form reason, for the explanatory block under a table.
function permSeriesNote(t, label){
  if(!t) return '';
  if(permUsable(t)) return (label?label+': ':'')+(t.deseasonNote||'');
  var why=t.permReason||t.note||t.error||'no reason recorded';
  return (label?label+': ':'')+'NO p-VALUE REPORTED. '+why;
}
// v10.159 W-02: the five jsNodeStatsFixed fields, rendered. Returns '' when
// there is genuinely nothing to disclose (a fully deseasonalized, gapless
// series), so a clean run does not gain noise.
function nodeStatsDisclosure(st, label){
  if(!st) return '';
  var bits=[];
  var noteSaysRaw = !!(st.climatologyNote && st.climatologyNote.indexOf('NOT DESEASONALIZED')>=0);
  if(st.deseasonalized!==true && !noteSaysRaw) bits.push('NOT DESEASONALIZED - these AC1/variance figures are RAW and carry the '+
    'v10.101 seasonal-cycle caveat; do not compare them against a deseasonalized number');
  // v10.160 NIT: this pushed unconditionally, so bits was never empty and the
  // function never returned '' - contradicting its own header and making the
  // "every node deseasonalized against a complete climatology" else-branch at
  // every consumer unreachable, while adding a ~180-character noise line to
  // every clean run. The climatology source is worth printing exactly when
  // something about it needs saying.
  if(st.climatologySource && (st.deseasonalized!==true || st.ac1PairsDropped))
    bits.push('climatology: '+st.climatologySource);
  // climatologyNote already carries the GAPPED SERIES sentence when there is one,
  // so the pair audit is only spelled out separately if the note does not.
  var noteHasGap = !!(st.climatologyNote && st.climatologyNote.indexOf('GAPPED SERIES')>=0);
  if(st.ac1PairsDropped && !noteHasGap) bits.push(st.ac1PairsDropped+' of '+(st.ac1PairsUsed+st.ac1PairsDropped)+
    ' array-adjacent pairs are NOT one calendar month apart (largest gap '+
    (st.ac1MaxGapMonths||0)+' months) and are excluded from the AC1');
  if(st.climatologyNote) bits.push(st.climatologyNote);
  if(bits.length===0) return '';
  return (label?label+' - ':'')+bits.join(' | ');
}
// Collapses the disclosures for a set of nodes into the lines a panel appends,
// de-duplicating identical messages so a 9-node network does not print the
// same sentence nine times.
function nodeStatsDisclosureLines(entries){
  var seen={}, out=[];
  entries.forEach(function(e){
    var d=nodeStatsDisclosure(e.st, e.label);
    if(!d) return;
    var body=d.indexOf(' - ')>=0?d.substring(d.indexOf(' - ')+3):d;
    if(seen[body]){ seen[body].labels.push(e.label); return; }
    seen[body]={labels:[e.label], body:body};
    out.push(seen[body]);
  });
  return out.map(function(o){
    return '  ['+o.labels.join(', ')+'] '+o.body;
  });
}


// v10.151 FIX 5: the confidence label now CANNOT exceed the p-value.
// WHY: a real Looe Key run printed "NO STATISTICALLY SIGNIFICANT SIGNAL,
// AC1 p=0.980" on one line and "Confidence: HIGH" four lines below. The
// old function took only the tally and never saw a p-value, so with
// primaryAgrees=true it returned HIGH by construction. The permutation
// result resolved in a separate callback and wrote only to the banner -
// two verdicts, disjoint inputs, structurally unable to agree.
// Directional agreement among indicators is not evidence when the
// significance test cannot separate the deltas from ordinary noise.
// Pass null/null before the permutation test resolves; that correctly
// yields PRELIMINARY rather than a confident-sounding label.
// v10.158: permStatus distinguishes "the permutation test has not come back
// yet" from "it ran and structurally cannot produce a p-value here". Those are
// completely different statements to a user - the first says wait, the second
// says this window length cannot answer the question - and the panel used to
// print the first in both cases. Accepted values: undefined/'pending' (not
// back yet), 'ok' (ran, p-values below), 'unavailable' (ran, no p-value
// possible). Callers that pass nothing keep the old, wait-flavoured wording.
function classifyToolkitConfidence(tally, pAC1, pVar, permStatus){
  var base;
  if(!tally.primaryAvailable){
    if(tally.supportAvail===0) base={label:'NO INDICATORS AVAILABLE', level:'none'};
    else if(tally.supportAgree>0) base={label:'LOW (AC1 unavailable - only weaker supporting indicators to go on: '+
      tally.supportAgree+'/'+tally.supportAvail+' agree)', level:'low'};
    else base={label:'LOW (AC1 unavailable, no supporting indicators agree either)', level:'low'};
  } else if(tally.primaryAgrees){
    if(tally.supportAvail>0 && tally.supportAgree===tally.supportAvail)
      base={label:'primary indicator (AC1) rising, corroborated by ALL '+tally.supportAvail+' supporting indicator(s)', level:'high'};
    else if(tally.supportAgree>0)
      base={label:'primary indicator (AC1) rising, corroborated by '+tally.supportAgree+' of '+tally.supportAvail+' supporting indicator(s)', level:'high'};
    else if(tally.supportAvail>0)
      base={label:'primary indicator (AC1) rising; supporting indicator(s) flat/falling. Per Dakos et al. 2012 this does NOT by itself weaken the AC1 signal - variance is documented to sometimes fall even near a genuine transition (their Fig. 2c, Fig. 4).', level:'moderate'};
    else
      base={label:'primary indicator (AC1) rising alone, no supporting data available (Dakos et al. 2012: AC1 alone is a relatively robust signal)', level:'moderate'};
  } else if(tally.supportAgree>0){
    base={label:'primary indicator (AC1) did NOT rise, even though '+tally.supportAgree+
      ' supporting indicator(s) did. Dakos et al. 2012: variance-type indicators can rise OR fall near a real transition, so this is weaker evidence than an AC1 rise would be.', level:'low-moderate'};
  } else {
    base={label:'primary indicator (AC1) did not rise, and no supporting indicators rose either', level:'low'};
  }

  // ---- significance gate (v10.151) ----
  var havePvals=(pAC1!==null&&pAC1!==undefined)||(pVar!==null&&pVar!==undefined);
  if(!havePvals){
    if(permStatus==='unavailable'){
      return {label:'NOT TESTABLE AT THIS WINDOW LENGTH - the permutation test RAN and cannot be '+
        'computed here (it returned no p-value for either statistic; see the permutation panel for '+
        'the reason). This is not a pending result and waiting will not change it: choose a longer '+
        'window. Direction only: '+base.label,
        level:'preliminary'};
    }
    return {label:'PRELIMINARY (permutation test has not returned a p-value yet) - direction only: '+base.label,
      level:'preliminary'};
  }
  var sig=(pAC1!==null&&pAC1!==undefined&&pAC1<0.05)||(pVar!==null&&pVar!==undefined&&pVar<0.05);
  var pTxt='AC1 p='+((pAC1!==null&&pAC1!==undefined)?pAC1.toFixed(3):'n/a')+
           ', Var p='+((pVar!==null&&pVar!==undefined)?pVar.toFixed(3):'n/a');
  if(!sig&&(base.level==='high'||base.level==='moderate')){
    return {label:'LOW - the indicator DIRECTIONS look CSD-consistent ('+base.label+
      '), but the permutation test cannot distinguish these deltas from ordinary noise ('+pTxt+
      '). Directional agreement among indicators is not evidence when the significance test is null.',
      level:'low'};
  }
  if(sig&&base.level==='high') return {label:'HIGH - '+base.label+'; permutation test agrees ('+pTxt+')', level:'high'};
  if(sig&&base.level==='moderate') return {label:'MODERATE - '+base.label+'; permutation test agrees ('+pTxt+')', level:'moderate'};
  return {label:base.label+' ('+pTxt+')', level:base.level};
}

// v10.151 FIX 6: general verdict-conflict test, replacing the two
// string-match checks (v10.119 headline, v10.120 detail) that only ever
// looked for 'MORE STABLE THAN CONTROL'. At Looe Key vTitle was
// 'NO SIGNAL AT EITHER SITE', so neither fired and the panel printed
// verbatim: "STRONG SIGNAL, LIKELY REGIONAL ... Regional context: NO
// SIGNAL AT EITHER SITE". That was the fifth appearance of this bug
// class; each previous fix patched one string. This tests the actual
// disagreement instead, so future cases are caught automatically.
// Returns null when there is no conflict (or when either side is
// genuinely unknown), otherwise an explanatory string.
function verdictsConflict(combinedTitle, vTitle){
  function saysSignal(str){
    str=String(str||'').toUpperCase();
    if(str.indexOf('CANNOT ASSESS')>=0) return null;
    if(str.indexOf('CANNOT CLASSIFY')>=0) return null;
    if(str.indexOf('NO SIGNAL')>=0) return false;
    if(str.indexOf('NO RELIABLE')>=0) return false;
    if(str.indexOf('MORE STABLE')>=0) return false;
    if(str.indexOf('STRONG')>=0||str.indexOf('SIGNAL PRESENT')>=0||
       str.indexOf('LOCAL CSD')>=0||str.indexOf('MARGINAL LOCAL')>=0||
       str.indexOf('GLOBAL SIGNAL')>=0||str.indexOf('WEAK SIGNAL')>=0) return true;
    return null;
  }
  var x=saysSignal(combinedTitle), y=saysSignal(vTitle);
  if(x===null||y===null) return null;
  if(x===y) return null;
  return 'VERDICTS DISAGREE - the AC1-weighted toolkit headline says "'+combinedTitle+
    '" while the variance-based regional read says "'+vTitle+'". These come from two separate '+
    'classifiers with different inputs and have not been reconciled. Treat NEITHER as confirmed - '+
    'read the permutation p-value above, which is the only real significance test in this panel.';
}

// v10.84 FIX: translate cryptic Earth Engine errors into something actionable.
// Errors like "Unknown reference to value named ''..." or "Failed to contact
// Earth Engine servers" are almost always a TEMPORARY server/connectivity
// hiccup (often from firing many parallel calls at once, e.g. right after a
// map click), not a real bug in the inputs. Recognize the common patterns
// and tell the user to just retry, while still showing the raw error text
// underneath for debugging.
function friendlyEEError(errText) {
  var raw = String(errText);
  var lower = raw.toLowerCase();
  var isTransient = lower.indexOf('unknown reference to value named')>=0 ||
    lower.indexOf('failed to contact earth engine')>=0 ||
    lower.indexOf('econnreset')>=0 || lower.indexOf('timeout')>=0 ||
    lower.indexOf('too many')>=0 || lower.indexOf('rate limit')>=0 ||
    lower.indexOf('internal error')>=0 || lower.indexOf('computation timed out')>=0;
  if(isTransient){
    return 'TEMPORARY EARTH ENGINE HICCUP - not a data problem.\n'+
      'This usually happens when several requests fire at once (e.g. right after\n'+
      'a map click or another S13 test). Your inputs are still in the boxes -\n'+
      'just wait a few seconds and press the button again.\n'+
      '\nRaw error: '+raw;
  }
  return 'Raw error: '+raw;
}

