        csdStoredAfterV.style().set('color','#aa3300');
        csdTestStatusV.setValue('Done [AFTER]. STEP 2 complete -> scroll down and press COMPARE (STEP 3), or use FIND SWEET SPOT (STEP 4) to test several AFTER lengths at once.');
