var s7dBeforeMonthsInput = ui.Textbox({placeholder:'months, e.g. 24',value:'24',style:{stretch:'horizontal',margin:'2px 4px',fontSize:'11px'}});
panel.add(s7dBeforeMonthsInput);
panel.add(lbl('AFTER start date + months:',7,'#aa3300'));
var s7dAfterStartInput = ui.Textbox({placeholder:'e.g. 2023-11-01',style:{stretch:'horizontal',margin:'2px 4px',fontSize:'11px'}});
panel.add(s7dAfterStartInput);
var s7dAfterMonthsInput = ui.Textbox({placeholder:'months, e.g. 12',value:'12',style:{stretch:'horizontal',margin:'2px 4px',fontSize:'11px'}});
panel.add(s7dAfterMonthsInput);
var s7dStatusV = ui.Label('Fill in the fields above, then press RUN. v10.167: 1 pre-check + ceil(span/12) chunked series calls + 1 NDVI check, where span is the calendar months the two windows jointly cover (4 calls at a 24-month span, 5 at 31, 10 at the 95-month maximum). The chunks run in sequence, so expect roughly 1-3 minutes.',
  {fontSize:'11px',fontWeight:'bold',color:'#555555',backgroundColor:'#eeeeee',padding:'6px 8px',margin:'2px 0',whiteSpace:'pre',border:'2px solid #aaaaaa'});
var s7dResultV = ui.Label('',{fontSize:'8px',color:'#2a1040',backgroundColor:'#f2ecfa',padding:'4px 6px',margin:'2px 0',whiteSpace:'pre'});
var s7dRunSeq = 0;   // v10.161 S6a: a late callback from an abandoned run must not overwrite a newer run's label
var s7dRunBtn = ui.Button({
  label:'RUN FULL 9-NODE NETWORK (chunked: 2 + 1 EE call per 12 months of span)',
  style:{fontSize:'11px',fontWeight:'bold',margin:'2px 4px',backgroundColor:'#ded0f0',color:'#3a1560',stretch:'horizontal',padding:'6px 4px',border:'2px solid #5a2a80'},
  onClick:function(){
    var coordTxt=(s7dCoordInput.getValue()||'').trim();
    var radiusTxt=(s7dRadiusInput.getValue()||'').trim();
    var beforeStartTxt=(s7dBeforeStartInput.getValue()||'').trim();
    var beforeMonthsTxt=(s7dBeforeMonthsInput.getValue()||'').trim();
    var afterStartTxt=(s7dAfterStartInput.getValue()||'').trim();
    var afterMonthsTxt=(s7dAfterMonthsInput.getValue()||'').trim();
    if(!coordTxt||!beforeStartTxt||!beforeMonthsTxt||!afterStartTxt||!afterMonthsTxt){
      s7dStatusV.setValue('MISSING - fill in Lat/Lon and both BEFORE/AFTER date+months fields.');
      s7dStatusV.style().set('color','#cc0000'); s7dStatusV.style().set('backgroundColor','#ffd0d0'); return;
    }
    var rawParts=coordTxt.split(',');
    if(rawParts.length!==2){s7dStatusV.setValue('Invalid format - use: lat, lon'); s7dStatusV.style().set('color','#cc0000'); return;}
    var latIn=parseCoordPart(rawParts[0]), lonIn=parseCoordPart(rawParts[1]);
    if(isNaN(latIn)||isNaN(lonIn)){s7dStatusV.setValue('Invalid format - use: lat, lon'); s7dStatusV.style().set('color','#cc0000'); return;}
    var radiusKm=parseFloat(radiusTxt);
    if(isNaN(radiusKm)||radiusKm<0.3||radiusKm>3){s7dStatusV.setValue('Ring radius must be 0.3-3 km.'); s7dStatusV.style().set('color','#cc0000'); return;}
    var beforeMonths=parseInt(beforeMonthsTxt,10), afterMonths=parseInt(afterMonthsTxt,10);
    // v10.159 W-01 item 4 set a floor of 12 months per box and claimed "the
    // pooled record is always >= CLIM_MIN_TOTAL_SAMPLES and the shipped defaults
    // always produce a properly deseasonalized, calibrated p-value". v10.160 S5:
    // that sentence was false on BOTH halves and is replaced rather than edited.
    //  - "always >= CLIM_MIN_TOTAL_SAMPLES": that floor counts VALID months, and
    //    12+12 sat exactly on it, so one masked month refused the whole test.
    //    Sentinel-2 FAI is cloud-masked. Measured p-value emission at 12+12 under
    //    the v10.159 floor of 24: 100% unmasked, 8.7% at 10% per-month masking,
    //    0.3% at 20%, 0.1% at 25%, and 0.0% at 25% seasonally-clustered
    //    (3000 draws/cell).
    //  - "calibrated": at 12+12 the measured variance-ratio false-positive rate
    //    was 1.1-4.1% at a fixed 0-month gap and 3.9-4.7% at a random 0-3 month
    //    gap, i.e. gap-dependent and conservative, with 21.7-24.8% power at gap 0.
    // FIXED by raising the DEFAULTS (see the month boxes above) and by checking
    // the POOLED total here, not just the per-box minimum. The per-box floor of
    // 12 stays - below one full annual cycle per window there is nothing to
    // estimate a seasonal cycle from - and the pooled total must now clear
    // CLIM_MIN_TOTAL_SAMPLES before the run starts, instead of the test
    // discovering it later and reporting NOT TESTABLE. Note what this check
    // CANNOT do: it counts NOMINAL months, and the floor counts VALID ones, so a
    // heavily masked record can still fall under it. That is why the defaults now
    // sit 10 months clear of the floor rather than on it.
    if(isNaN(beforeMonths)||beforeMonths<12||beforeMonths>36||isNaN(afterMonths)||afterMonths<12||afterMonths>36){
      s7dStatusV.setValue('BEFORE/AFTER months must each be 12-36 (v10.159: raised from 4 - below one full annual cycle per window there is nothing to estimate the seasonal cycle from).');
      s7dStatusV.style().set('color','#cc0000'); return;
    }
    // v10.160 S5: the POOLED total is what the climatology floor is applied to.
    if((beforeMonths+afterMonths) < CLIM_MIN_TOTAL_SAMPLES){
      s7dStatusV.setValue('BEFORE + AFTER must total at least '+CLIM_MIN_TOTAL_SAMPLES+' months (you asked for '+(beforeMonths+afterMonths)+'). '+
        'Below that the seasonal cycle cannot be estimated well enough to remove, and no p-value is reported. MEASURED at a 24-month pooled record '+
        '(seasonal amplitude 3, noise SD 1, 3000 draws): a real five-fold rise in the AFTER window noise is detected only 21.7-24.8% of the time at a '+
        '0-month BEFORE/AFTER gap. Note this check counts NOMINAL months; the floor counts VALID ones, so on a cloud-masked record leave real slack - '+
        'the shipped default of 24+12 sits 10 months clear of the floor.');
      s7dStatusV.style().set('color','#cc0000'); return;
    }
    // v10.162 S1: the combined-span cap, checked before any EE call is spent.
    var _s7dSpanPre = combinedWindowSpan(beforeStartTxt, beforeMonths, afterStartTxt, afterMonths);
    var _s7dSpanRefusal = combinedSpanRefusal(_s7dSpanPre, beforeMonths, afterMonths);
    if(_s7dSpanRefusal){ s7dStatusV.setValue(_s7dSpanRefusal); s7dStatusV.style().set('color','#cc0000');
      s7dStatusV.style().set('backgroundColor','#ffd0d0'); s7dStatusV.style().set('whiteSpace','pre'); return; }
    s7dRunSeq++; var s7dMyRun=s7dRunSeq;   // v10.161 S6a
    recordStudySite(latIn, lonIn, 'S7D');

    // v10.161 S4: cheap FAI data-density gate BEFORE the heavy batched calls
    // (v10.162 S1: 2 of them, not 3; v10.167 FIX 20: 1 NDVI check plus one
    // chunked series call per 12 months of BEFORE..AFTER span).
    faiPrecheckThenRun({lat:latIn, lon:lonIn, moduleName:'S7D', statusLbl:s7dStatusV, resultLbl:s7dResultV,
      windows:[{name:'BEFORE',start:beforeStartTxt,months:beforeMonths},
               {name:'AFTER', start:afterStartTxt, months:afterMonths}],
      cannotRunTxt:'S7C-S7F cannot run here.'}, function(_pre){

    function destinationPoint(lat, lon, bearingDeg, distKm){
      var R=6371, brng=bearingDeg*Math.PI/180, lat1=lat*Math.PI/180, lon1=lon*Math.PI/180;
      var lat2=Math.asin(Math.sin(lat1)*Math.cos(distKm/R)+Math.cos(lat1)*Math.sin(distKm/R)*Math.cos(brng));
      var lon2=lon1+Math.atan2(Math.sin(brng)*Math.sin(distKm/R)*Math.cos(lat1),Math.cos(distKm/R)-Math.sin(lat1)*Math.sin(lat2));
      return {lat:lat2*180/Math.PI, lon:lon2*180/Math.PI};
    }
    var bearings8=[{b:0,label:'N'},{b:45,label:'NE'},{b:90,label:'E'},{b:135,label:'SE'},
      {b:180,label:'S'},{b:225,label:'SW'},{b:270,label:'W'},{b:315,label:'NW'}];
    var nodes=[{label:'Center',lat:latIn,lon:lonIn}];
    bearings8.forEach(function(br){
      var d=destinationPoint(latIn,lonIn,br.b,radiusKm);
      nodes.push({label:br.label,lat:d.lat,lon:d.lon});
    });
    nodes.forEach(function(nd){ nd.buf=ee.Geometry.Point([nd.lon,nd.lat]).buffer(150); });

    // v10.107 FIX: previously fired ~43 separate .evaluate() calls (one full
    // server-side graph evaluation per node per period). Now batches ALL 9
    // nodes' monthly values into ONE FeatureCollection per period via
    // reduceRegions()+flatten() (extractMultiNodeSeries), plus one batched
    // NDVI check - 3 total .evaluate() calls instead of ~43. All AC1/
    // variance/skewness/correlation math now runs client-side in JS
    // (jsNodeStats/jsPairCorrelation) on the small resulting tables, using
    // formulas identical to the EE versions - only where the arithmetic
    // runs has changed, not what it computes.
    var ptsFC = ee.FeatureCollection(nodes.map(function(nd,idx){
      return ee.Feature(nd.buf, {label:nd.label, idx:idx});
    }));
    // v10.162 S1: ONE combined series spanning BEFORE-start .. AFTER-end
    // (including the gap), sliced into the two windows client-side by real
    // timestamp. Replaces the separate BEFORE fetch that returned 0 features
    // in the live Bocas del Toro run while AFTER returned all 108.
    var _s7dSpan = combinedWindowSpan(beforeStartTxt, beforeMonths, afterStartTxt, afterMonths);
    // v10.167 FIX 20 / S1: the ONE unbounded combined fetch is replaced by a
    // CHUNKED one. See the long note above s7FaiChunkMonths(): every observed
    // failure of this module used extractMultiNodeSeries() on a single graph of
    // nMonths x 9 nodes; the only configuration of that path ever observed to
    // return data was 12 months x 9 nodes = 108 features, and that is the bound
    // each chunk now respects.
    var _s7dGrid = s7FaiGridSpan(beforeStartTxt, beforeMonths, afterStartTxt, afterMonths);
    var _s7dPlan = s7FaiChunkPlan(_s7dGrid.startDateStr, _s7dGrid.nMonths, nodes.length);
    var _s7dSeriesCalls = _s7dPlan.length;
    var _s7dTotalCalls = _s7dSeriesCalls + 1;          // + the NDVI check
    var ndviWaterMasked=ndviWater.updateMask(oceanMask).rename('ndviW');
    // v10.109 FIX: switched from mean() over 150m to max() over a FIXED
    // 500m buffer to fix Center falsely reading "LIKELY NOT on-reef".
    // v10.110 FIX: that fixed value size (500m) was itself a bug - at the
    // default 0.5km ring radius, a 500m buffer overlaps substantially with
    // EVERY adjacent node's buffer (Center-to-ring spacing = radiusKm*1000;
    // ring-to-ring spacing is even smaller, ~0.77x that). A real run showed
    // Center/N/NE/E all reading the IDENTICAL value 0.84 - strong evidence
    // their overlapping buffers were all picking up the same peak pixel,
    // silently defeating the purpose of having 9 distinct nodes. Buffer
    // size now SCALES with the user's ring radius (30% of node spacing,
    // capped 80-250m) so it can never exceed roughly a third of the gap to
    // the nearest neighbouring node, while still being larger than the
    // 150m FAI buffer that caused the original false-negative.
    var ndviBufM = Math.max(80, Math.min(250, radiusKm*1000*0.3));
    var ptsFCForNdvi = ee.FeatureCollection(nodes.map(function(nd,idx){
      return ee.Feature(ee.Geometry.Point([nd.lon,nd.lat]).buffer(ndviBufM), {label:nd.label, idx:idx});
    }));
    var rNdviAll = ndviWaterMasked.reduceRegions({collection:ptsFCForNdvi, reducer:ee.Reducer.max(), scale:20});

    s7dStatusV.setValue('Running: '+_s7dTotalCalls+' batched Earth Engine calls - '+_s7dSeriesCalls+
      ' chunked series call(s) covering '+_s7dGrid.nMonths+' months x '+nodes.length+' nodes, plus 1 NDVI check.\n'+
      'v10.167: the series is fetched in chunks of at most '+S7_FAI_MAX_MONTHS_PER_CALL+' months x '+nodes.length+
      ' nodes and merged client-side,\n'+
      'because the single unchunked fetch returned 0 features in live runs at 24-32 months x 9 nodes.\n'+
      'The chunks run one after another, so expect roughly '+(_s7dSeriesCalls*30)+'-'+(_s7dSeriesCalls*60)+' seconds.\n'+
      S7_DEADLINE_NOTE);
    s7dStatusV.style().set('color','#334466'); s7dStatusV.style().set('backgroundColor','#eeeeee');
    s7dStatusV.style().set('border','2px solid #aaaaaa'); s7dStatusV.style().set('whiteSpace','pre');
    s7dResultV.setValue('');

    var s7dData={}, s7dPending=2, s7dErrors=0;
    // v10.167 FIX 20 / S1: still TWO outstanding units (the series, the NDVI
    // check), but the series unit is now _s7dSeriesCalls chunked EE calls run
    // in sequence. The v10.161 S6a run-sequence guard and stall-explaining
    // progress text are unchanged. s7dDead is the new one: once a chunked fetch
    // has REFUSED on screen, a later NDVI callback must not overwrite the
    // refusal with a progress line or a half-populated table.
    var s7dDead=false;
    var s7dWaiting=['combined BEFORE..AFTER series ('+_s7dSeriesCalls+' chunked call(s))','NDVI check'];
    var s7dCallName={combined:'combined BEFORE..AFTER series ('+_s7dSeriesCalls+' chunked call(s))', ndvi:'NDVI check'};
    function s7dBump(key,val,err){
      if(s7dMyRun!==s7dRunSeq || s7dDead) return;   // v10.161 S6a: stale run, do not touch the label
      s7dData[key]=err?null:val;
      if(err) s7dErrors++;
      s7dPending--;
      // v10.161 S6a: name the outstanding call(s) and say what a frozen counter means.
      var _wait=s7Outstanding(s7dWaiting, s7dCallName[key]||key);
      s7dStatusV.setValue('Running: '+(2-s7dPending)+' / 2 batched call groups done ('+_s7dSeriesCalls+
        ' chunked series call(s) + 1 NDVI check)'+
        (s7dErrors>0?' ('+s7dErrors+' errored)':'')+'...\n'+_wait+
        (s7dPending>0?('\n'+S7_STALL_HINT+' (search "S7D [" in the Console.)'):''));
      if(s7dPending===0) s7dFinish();
    }
    // v10.167 FIX 20 / S2: a chunked fetch that errors, comes back empty or
    // never answers now REFUSES on screen. S7D already refused correctly when
    // the fetch RETURNED short; this covers the two cases it did not - and it
    // is the same refusal S7E and S7F now use, so all three behave alike.
    function s7dRefuseChunks(res){
      if(s7dMyRun!==s7dRunSeq || s7dDead) return;
      s7dDead=true;
      var txt=s7ChunkRefusalText('S7D', res, nodes.length);
      s7dStatusV.setValue(txt+'\nS7C-S7F cannot run here with these windows.');
      s7dStatusV.style().set('color','#cc0000'); s7dStatusV.style().set('backgroundColor','#ffd0d0');
      s7dStatusV.style().set('border','2px solid #cc0000'); s7dStatusV.style().set('whiteSpace','pre');
      s7dStatusV.style().set('fontWeight','bold');
      s7dResultV.setValue('Chunk plan was '+_s7dSeriesCalls+' call(s) over '+_s7dGrid.nMonths+' month(s) x '+
        nodes.length+' nodes, starting '+_s7dGrid.startDateStr+'.'+(_pre&&_pre.note?'\n'+_pre.note:''));
      print('=== S7D REFUSED (v10.167 chunked fetch: '+res.reason+') === '+(res.detail||''));
    }
    function s7dFinish(){
      if(s7dMyRun!==s7dRunSeq) return;   // v10.161 S6a
      try {
        function fmtN(v,d){ return (v!==null&&v!==undefined&&!isNaN(v))?v.toFixed(d):'n/a'; }

        // v10.162 S1: slice the ONE combined series into the two windows by
        // real timestamp (sliceSeriesMapByWindow), not by array position.
        var combinedByNode = groupSeriesByLabel(s7dData.combined, 'fai');
        var beforeByNode = sliceSeriesMapByWindow(combinedByNode, beforeStartTxt, beforeMonths);
        var afterByNode  = sliceSeriesMapByWindow(combinedByNode, afterStartTxt,  afterMonths);
        // If the combined fetch came back but does not actually cover both
        // windows, REFUSE with the existing insufficient-data wording rather
        // than rendering half a table (the v10.161 behaviour) or hanging.
        var _s7dShort = combinedSliceShortfall(beforeByNode['Center']||[], afterByNode['Center']||[], 4);
        if(_s7dShort){
          s7dStatusV.setValue(_s7dShort+'\nS7C-S7F cannot run here.');
          s7dStatusV.style().set('color','#cc0000'); s7dStatusV.style().set('backgroundColor','#ffd0d0');
          s7dStatusV.style().set('border','2px solid #cc0000'); s7dStatusV.style().set('whiteSpace','pre');
          s7dResultV.setValue('Chunked fetch returned '+((s7dData.combined&&s7dData.combined.features)?s7dData.combined.features.length:0)+
            ' raw feature(s) across '+_s7dGrid.nMonths+' month(s) x '+nodes.length+' nodes in '+_s7dSeriesCalls+' call(s).'+
            (_pre&&_pre.note?'\n'+_pre.note:''));
          print('=== S7D REFUSED (v10.162 S1 combined-slice shortfall) === '+_s7dShort);
          return;
        }
        var ndviByLabel = {};
        if(s7dData.ndvi && s7dData.ndvi.features){
          s7dData.ndvi.features.forEach(function(f){
            var p=f.properties||{};
            ndviByLabel[p.label] = extractReduceRegionsValue(p,'ndviW');
          });
        }

        var perNodeStats = {};
        nodes.forEach(function(nd){
          // v10.160 S6: ONE pooled climatology per node, shared by the BEFORE
          // and AFTER display figures, so the dAC1 in the table is the same
          // quantity as the observedDelta the p-value beside it was computed on.
          var _ndClim = pooledClimFor(beforeByNode[nd.label]||[], afterByNode[nd.label]||[]);
          perNodeStats[nd.label] = {before:jsNodeStatsFixed(beforeByNode[nd.label]||[], _ndClim), after:jsNodeStatsFixed(afterByNode[nd.label]||[], _ndClim)};
        });
        var perPairCorr = {};
        for(var pi=1;pi<nodes.length;pi++){
          var label=nodes[pi].label;
          perPairCorr[label] = {
            before: jsPairCorrelation(beforeByNode['Center'], beforeByNode[label]),
            after: jsPairCorrelation(afterByNode['Center'], afterByNode[label])
          };
        }

        var rows=['Node | On-reef? | \u0394AC1 (p) | \u0394Var | \u0394Corr-vs-Center (p)'];
        rows.push(repeatChar('\u2500',56));
        // v10.154 FIX 11: S7D previously had NO significance test at all -
        // its verdict came from fixed cutoffs (dAC1>0.01, dCorr>0.10) that
        // were measured firing on up to 80% of windows at a site where
        // nothing happened. Now every node and every pair gets a real
        // permutation p-value, with a Bonferroni bar for the fact that 8
        // pairs plus 9 nodes are tested at once. Zero new EE calls - this
        // reuses beforeByNode/afterByNode, already fetched above.
        var nOnReefRisingCorr=0, nOnReefTotal=0, nOffReef=0, nAc1Rising=0, nAc1Avail=0;
        var nCorrSig=0, nCorrTested=0, nAc1Sig=0, nAc1Tested=0;
        var s7dPerm={};
        // v10.161 S6c: _nTests is how many tests were FIRED (8 pairs + 9 nodes).
        // At a cloud-limited site most of them come back NOT TESTABLE, and a
        // Bonferroni bar built from the fired count then corrects for a family
        // that does not exist. _nPUsable below counts the tests that actually
        // produced a p-value; the bar is derived from that, after the loop.
        var _nTests = Math.max(1, (nodes.length-1) + nodes.length);
        var _nPUsable = 0;
        var BONF;
        for(var idx=0;idx<nodes.length;idx++){
          var nd=nodes[idx];
          var stB=perNodeStats[nd.label].before, stA=perNodeStats[nd.label].after;
          var ndviV=(ndviByLabel[nd.label]!==undefined)?ndviByLabel[nd.label]:null;
          var onReef = ndviV!==null ? (ndviV>-0.10) : null;
          var onReefLabel = onReef===null?'n/a':(onReef?'yes ('+fmtN(ndviV,2)+')':'LIKELY NOT ('+fmtN(ndviV,2)+')');
          if(onReef===false) nOffReef++;
          var dAC1=(stB.realAC1!==null&&stA.realAC1!==null)?(stA.realAC1-stB.realAC1):null;
          var dVar=(stB.varTrendRatio!==null&&stA.varTrendRatio!==null)?(stA.varTrendRatio-stB.varTrendRatio):null;
          var _thrD = getCalibratedThresholds(Math.min(beforeMonths, afterMonths));
          if(dAC1!==null){ nAc1Avail++; if(dAC1>_thrD.ac1) nAc1Rising++; }

          // v10.154: real p-value for this node's AC1 change
          var ac1T = permutationTestDeltaFixed(beforeByNode[nd.label]||[],
                                               afterByNode[nd.label]||[],
                                               statAC1ForPerm, 500);
          s7dPerm[nd.label] = {ac1:ac1T};
          // v10.159 W-01 item 2: was a bare p-value. permP() prints NOT TESTABLE
          // (or NOT CALIBRATED) instead whenever permUsable() is false.
          var ac1PTxt = permP(ac1T);
          if(permUsable(ac1T)){ nAc1Tested++; _nPUsable++; if(ac1T.pValue<0.05) nAc1Sig++; }

          var dCorrTxt='-', corrPTxt='-';
          if(idx>0){
            var pc=perPairCorr[nd.label];
            var dCorr=(pc.before.corr!==null&&pc.after.corr!==null)?(pc.after.corr-pc.before.corr):null;
            dCorrTxt=dCorr!==null?((dCorr>0?'+':'')+dCorr.toFixed(3)):'n/a';
            // v10.154: real p-value for the coupling change, pairing preserved
            var corrT = permutationTestCorrDelta(beforeByNode['Center'], beforeByNode[nd.label],
                                                 afterByNode['Center'], afterByNode[nd.label], 500);
            s7dPerm[nd.label].corr = corrT;
            corrPTxt = permP(corrT);
            if(permUsable(corrT)) _nPUsable++;
            if(onReef===true){
              nOnReefTotal++;
              if(permUsable(corrT)){
                nCorrTested++;
                // SIGNIFICANT AND RISING - direction alone is no longer enough.
                // v10.160 BLOCKER 4: dCorr comes from jsPairCorrelation on the RAW
                // paired series while corrT.pValue comes from
                // permutationTestCorrDelta, which deseasonalizes BOTH nodes against
                // a pooled climatology. Same mismatch as S7F's _sig(): a two-sided
                // p earned by a significant FALL in deseasonalized coupling could be
                // reported as HYPER-SYNCHRONIZATION off a raw rise. corrBefore /
                // corrAfter on the test result are the deseasonalized correlations
                // the null was actually built around, so the direction is taken from
                // them.
                if(permUsable(corrT) && corrT.pValue<0.05 &&
                   corrT.corrAfter!==null && corrT.corrAfter!==undefined &&
                   corrT.corrBefore!==null && corrT.corrBefore!==undefined &&
                   (corrT.corrAfter-corrT.corrBefore)>0){ nCorrSig++; nOnReefRisingCorr++; }
              }
            }
          }
          // v10.109 FIX: same near-zero-denominator artifact risk already
          // fixed for S7C in v10.105 (varTrendRatio = 2ndHalfVar/max(1st
          // HalfVar,1e-6) - a tiny first-half variance inflates the ratio
          // without any real surge). Ported here after a real S7D run
          // showed SW=+52.31x and SE=+11.99x, even more extreme than the
          // case that prompted the original fix.
          // v10.162 S6: second private copy of the same rule, with the same
          // leak. Routed through the shared isVarRatioArtifact().
          // v10.170 FAI-01: same fix as S7C - hand the rule this node's own
          // scale instead of letting it fall back to the SST-shaped absolute cut
          // that is true of every FAI row. The BEFORE window is the denominator
          // of dVar, so the BEFORE window's own halves are the right scale.
          var artifactFlag='';
          if(isVarRatioArtifact(stB.varFirstHalf, dVar, varScaleRefOf(stB.varFirstHalf, stB.varSecondHalf))){
            artifactFlag=' \u26A0ARTIFACT';
          }
          rows.push(nd.label+repeatChar(' ',Math.max(1,7-nd.label.length))+'| '+
            onReefLabel+repeatChar(' ',Math.max(1,12-onReefLabel.length))+'| '+
            (dAC1!==null?(dAC1>0?'+':'')+dAC1.toFixed(3):'n/a')+' ('+ac1PTxt+') | '+
            (dVar!==null?(dVar>0?'+':'')+dVar.toFixed(2)+'x':'n/a')+artifactFlag+' | '+
            dCorrTxt+' ('+corrPTxt+')');
        }
        rows.push(repeatChar('\u2500',56));
        rows.push(CSD_VAR_ARTIFACT_MSG_RELATIVE);
        rows.push('BEFORE: '+beforeStartTxt+' + '+beforeMonths+'mo | AFTER: '+afterStartTxt+' + '+afterMonths+'mo | radius='+radiusKm+'km | NDVI check buffer='+ndviBufM.toFixed(0)+'m (scaled to avoid overlapping adjacent nodes)');
        rows.push('Method (v10.167): '+_s7dTotalCalls+' EE fetches for this run - '+_s7dSeriesCalls+
          ' CHUNKED series call(s) (reduceRegions+flatten, at most '+S7_FAI_MAX_MONTHS_PER_CALL+' months x '+
          nodes.length+' nodes = '+(S7_FAI_MAX_MONTHS_PER_CALL*nodes.length)+' features each) covering '+
          _s7dGrid.nMonths+' months from '+_s7dGrid.startDateStr+', merged client-side, plus the NDVI check. '+
          'v10.162 made this ONE fetch; that single unchunked fetch is what returned 0 features in live runs at '+
          '24, 25 and 32 months x 9 nodes, while a 12-month x 9-node fetch returned all 108 features. The two '+
          'windows are still sliced out of the merged series client-side by real timestamp; AC1/variance/'+
          'correlation are still computed client-side in JS.');
        rows.push('');
        rows.push('=== v10.154 SIGNIFICANCE (permutation, 500 shuffles, pairing preserved) ===');
        rows.push('S7D previously had NO significance test - its verdict came from fixed cutoffs');
        rows.push('(\u0394AC1>0.01, \u0394corr>0.10) measured firing on up to 80% of windows at a site');
        rows.push('where nothing happened. Those are replaced by real p-values above.');
        // v10.161 S6b: both tallies used to render as "0 of 0" when nothing was
        // testable. An empty denominator is not a null result.
        rows.push('Coupling changes significant at p<0.05 : '+
          countOfTotal(nCorrSig, nCorrTested, 'on-reef pairs tested',
            'NO on-reef pair produced a p-value (not enough valid months) - nothing was tested, which is not the same as nothing being significant'));
        rows.push('AC1 changes significant at p<0.05      : '+
          countOfTotal(nAc1Sig, nAc1Tested, 'nodes tested',
            'NO node produced a p-value (not enough valid months) - nothing was tested, which is not the same as nothing being significant'));
        // v10.161 S6c: the bar is derived from the tests that ACTUALLY returned
        // a p-value, not from the 17 that were fired. When none did, there is no
        // multiple-comparisons problem to correct and saying there is one
        // manufactures a family out of thin air.
        BONF = 0.05/Math.max(1,_nPUsable);
        var _bonfHits=0;
        if(_nPUsable===0){
          rows.push('MULTIPLE COMPARISONS: none. '+_nTests+' tests were fired (8 pairs + 9 nodes) but NOT ONE');
          rows.push('returned a p-value at this site/window, so there is no family of results to correct.');
          rows.push('No Bonferroni bar is quoted, because correcting a family of zero tests is meaningless.');
        } else {
          rows.push('MULTIPLE COMPARISONS: '+_nTests+' tests were fired (8 pairs + 9 nodes) and '+_nPUsable+' of them');
          rows.push('returned a p-value, so the Bonferroni-corrected bar over the family that actually');
          rows.push('exists is p<'+BONF.toFixed(4)+'. At the uncorrected 0.05 level you would expect roughly');
          rows.push((0.05*_nPUsable).toFixed(1)+' hit(s) by chance alone across '+_nPUsable+' real tests.');
          nodes.forEach(function(nd){
            var e=s7dPerm[nd.label];
            if(e&&permUsable(e.corr)&&e.corr.pValue<BONF) _bonfHits++;
            if(e&&permUsable(e.ac1)&&e.ac1.pValue<BONF) _bonfHits++;
          });
          rows.push('Tests surviving the corrected bar: '+_bonfHits+
            (_bonfHits===0?'  <- nothing here is distinguishable from noise':''));
        }
        // v10.159 W-01 item 2 + W-02: the two columns above used to print a bare
        // p-value, and jsNodeStatsFixed()'s climatologySource / climatologyNote /
        // ac1PairsUsed / ac1PairsDropped / ac1MaxGapMonths were computed for every
        // node and read by nobody. Both are now on screen.
        // v10.160 NIT: this reported nodes[0] only. The nine nodes have different
        // masking, so they can have different permStatus values - one node
        // deseasonalized and eight NOT TESTABLE printed as if all nine were the
        // first one. Every DISTINCT note is now listed, with the nodes it applies to.
        var _s7dNoteMap={}, _s7dNoteOrder=[];
        nodes.forEach(function(nd){
          var _n=permSeriesNote(s7dPerm[nd.label]?s7dPerm[nd.label].ac1:null);
          if(!_n) _n='(no note returned)';
          if(!_s7dNoteMap[_n]){ _s7dNoteMap[_n]=[]; _s7dNoteOrder.push(_n); }
          _s7dNoteMap[_n].push(nd.label);
        });
        rows.push('SERIES USED (per-node AC1 p-values)'+(_s7dNoteOrder.length>1?
          ' - '+_s7dNoteOrder.length+' DIFFERENT notes across the '+nodes.length+' nodes:':':'));
        _s7dNoteOrder.forEach(function(_n){
          rows.push('  ['+_s7dNoteMap[_n].join(', ')+'] '+_n);
        });
        var _s7dDisc=[];
        nodes.forEach(function(nd){
          _s7dDisc.push({label:nd.label+' BEFORE', st:perNodeStats[nd.label].before});
          _s7dDisc.push({label:nd.label+' AFTER',  st:perNodeStats[nd.label].after});
        });
        var _s7dLines=nodeStatsDisclosureLines(_s7dDisc);
        if(_s7dLines.length>0){
          rows.push('SERIES QUALITY (v10.159 W-02 - computed since v10.158, never shown until now):');
          _s7dLines.forEach(function(d){ rows.push(d); });
        } else {
          rows.push('SERIES QUALITY: every node deseasonalized against a complete climatology, no gapped lag-1 pairs.');
        }
        // v10.108 NEW: raw feature counts visible on-screen, not just console
        // - if these are 0, the batched fetch itself returned nothing (a
        // real query/data problem); if they are >0 but the table above is
        // still all n/a, the problem is in property extraction instead -
        // these two failure modes need different fixes and this line tells
        // you which one you're looking at without opening the console.
        var combinedFeatCount=(s7dData.combined&&s7dData.combined.features)?s7dData.combined.features.length:0;
        var ndviFeatCount=(s7dData.ndvi&&s7dData.ndvi.features)?s7dData.ndvi.features.length:0;
        // v10.162 S1: this line reported BEFORE and AFTER separately because
        // they WERE separate calls. There is now one call, so it reports the
        // combined fetch and then what the client-side timestamp slice pulled
        // out of it - which is the number that can actually be short now.
        var _sliceB=(beforeByNode['Center']||[]).length, _sliceA=(afterByNode['Center']||[]).length;
        rows.push('Raw features returned: COMBINED='+combinedFeatCount+' | NDVI='+ndviFeatCount+
          ' (expect COMBINED='+(_s7dGrid.nMonths*nodes.length)+' = '+_s7dGrid.nMonths+'mo x '+nodes.length+' nodes across '+
          _s7dSeriesCalls+' chunked call(s), NDVI='+nodes.length+' if fully populated)');
        rows.push('Client-side timestamp slice (Center node): BEFORE='+_sliceB+'/'+beforeMonths+' months, AFTER='+_sliceA+'/'+afterMonths+
          ' months. A shortfall here is a data gap in the combined series, not a failed second call - there is no second call.');
        if(nOffReef>0) rows.push('NOTE: '+nOffReef+' of 9 nodes flagged LIKELY NOT on-reef (NDVI-water <= -0.10) - their rows above are informational only, not trusted algae-dynamics comparisons.');
        if(s7dErrors>0) rows.push('NOTE: '+s7dErrors+' of 2 batched call groups returned no usable data. Check the Console for the exact error text (search for "S7D [" lines).');
        if(_pre && _pre.note) rows.push(_pre.note);   // v10.161 S4
        s7dResultV.setValue(rows.join('\n'));

        var headline, hCol, hBg;
        if(nOnReefTotal===0){
          headline='COULD NOT ASSESS COUPLING - no on-reef ring points to compare against Center';
          hCol='#888888'; hBg='#eeeeee';
        } else if(nOnReefRisingCorr>=Math.ceil(nOnReefTotal*0.5)){
          // v10.154: nOnReefRisingCorr now counts pairs that are SIGNIFICANT
          // AND rising, not merely above a fixed cutoff. A direction alone
          // no longer produces a signal headline.
          headline='HYPER-SYNCHRONIZATION SIGNAL: '+nOnReefRisingCorr+' of '+nOnReefTotal+
            ' on-reef pairs show a SIGNIFICANT rise in correlation with Center (p<0.05, permutation). '+
            (_nPUsable===0?'No Bonferroni bar applies - not one of the '+_nTests+' tests fired returned a p-value.'
             :_bonfHits>0?_bonfHits+' test(s) survive the Bonferroni bar p<'+BONF.toFixed(4)+'.'
                        :'NONE survives the Bonferroni bar p<'+BONF.toFixed(4)+' - consistent with chance across the '+_nPUsable+' tests that returned a p-value.')+
            ' AC1 significant at '+countOfTotal(nAc1Sig,nAc1Tested,'nodes','no node returned an AC1 p-value')+'.';
          hCol=(_bonfHits>0)?'#880000':'#886600'; hBg=(_bonfHits>0)?'#ffd0d0':'#fff6cc';
        } else if(nOnReefRisingCorr>0){
          headline='PARTIAL SIGNAL: '+nOnReefRisingCorr+' of '+nOnReefTotal+
            ' on-reef pairs significant at p<0.05 - not a majority. '+
            (_nPUsable===0?'No Bonferroni bar applies - not one of the '+_nTests+' tests fired returned a p-value. '
             :_bonfHits>0?'':'None survives the corrected bar p<'+BONF.toFixed(4)+', so this is what '+
             (0.05*_nPUsable).toFixed(1)+' expected chance hits across '+_nPUsable+' real tests looks like. ')+
            'AC1 significant at '+countOfTotal(nAc1Sig,nAc1Tested,'nodes','no node returned an AC1 p-value')+'.';
          hCol='#886600'; hBg='#fff6cc';
        } else {
          headline='NO SYNCHRONIZATION SIGNAL: 0 of '+nOnReefTotal+
            ' on-reef pairs show a significant rise in correlation with Center (permutation test, p>=0.05). '+
            'AC1 significant at '+countOfTotal(nAc1Sig,nAc1Tested,'nodes','no node returned an AC1 p-value')+'. '+
            (nCorrTested>0?'This is a real null result, not just a failure to cross an uncalibrated threshold.'
                          :'CAVEAT: none of those on-reef pairs actually produced a p-value, so this is an '+
                           'UNTESTED null, not a measured one.');
          hCol='#115511'; hBg='#d4f5df';
        }
        s7dStatusV.setValue(headline);
        s7dStatusV.style().set('color',hCol); s7dStatusV.style().set('backgroundColor',hBg);
        s7dStatusV.style().set('border','2px solid '+hCol); s7dStatusV.style().set('whiteSpace','pre'); s7dStatusV.style().set('fontWeight','bold');

        print('=== S7D FULL 9-NODE ALGAE COUPLING NETWORK (v10.107 batched) ===');
        print(headline);
        print(rows.join('\n'));
      } catch(errFinal){
        s7dStatusV.setValue(friendlyEEError(errFinal));
        s7dStatusV.style().set('color','#cc0000'); s7dStatusV.style().set('backgroundColor','#ffd0d0');
        s7dStatusV.style().set('border','2px solid #cc0000'); s7dStatusV.style().set('whiteSpace','pre');
        print('=== S7D FINAL ERROR === '+errFinal);
      }
    }
    // v10.108 NEW: real diagnostics for each batched call (v10.162: 2, not 3), instead
    // of only an aggregate "N errored" counter. A run came back with EVERY
    // node showing n/a on EVERY field, which the aggregate counter alone
    // can't explain (it only reported 1 of 3 calls as errored, but the
    // table looked like all 3 failed) - this makes each call's real outcome
    // directly visible in the console: the exact error text if one failed,
    // or the feature count + first feature's raw property names if it
    // succeeded (confirms whether reduceRegions() is actually naming its
    // output the way extractReduceRegionsValue() assumes).
    function s7dDiagnose(label, v, e){
      if(e){
        print('=== S7D ['+label+'] ERROR ==='); print(e);
        return;
      }
      var nFeat = (v&&v.features)?v.features.length:0;
      print('=== S7D ['+label+'] OK - '+nFeat+' feature(s) returned ===');
      if(nFeat>0){
        print('First feature raw properties: '+JSON.stringify(v.features[0].properties));
      } else {
        print('WARNING: 0 features returned - reduceRegions/flatten produced an empty table.');
      }
    }
    // v10.167 FIX 20 / S1: the series arrives as _s7dSeriesCalls sequential
    // chunks. Any chunk that errors, returns 0 features or blows the deadline
    // refuses the whole run on screen instead of leaving the counter frozen.
    fetchFaiSeriesChunked({
      gridStartStr:_s7dGrid.startDateStr, nMonths:_s7dGrid.nMonths, ptsFC:ptsFC,
      nRegions:nodes.length, band:'fai', scale:20, tag:'S7D',
      isCurrent:function(){ return s7dMyRun===s7dRunSeq && !s7dDead; },
      onProgress:function(i,total,ch){
        if(s7dMyRun!==s7dRunSeq || s7dDead) return;
        s7dStatusV.setValue('Running: series chunk '+(i+1)+' / '+total+' ('+ch.start.substring(0,7)+' + '+
          ch.months+' months x '+nodes.length+' nodes = '+ch.expected+' features), plus the NDVI check.\n'+
          S7_STALL_HINT+' (search "S7D [" in the Console.)\n'+S7_DEADLINE_NOTE);
      }
    }, function(res){
      if(!res.ok){ s7dRefuseChunks(res); return; }
      if(res.shortChunks && res.shortChunks.length>0){
        print('=== S7D NOTE: '+res.shortChunks.length+' chunk(s) returned fewer features than expected ===');
      }
      s7dDiagnose('combined BEFORE..AFTER series ('+res.nCalls+' chunked call(s))', res.fc, null);
      s7dBump('combined', res.fc, null);
    });
    rNdviAll.evaluate(function(v,e){ s7dDiagnose('NDVI check', v, e); s7dBump('ndvi', v, e); });
    });  // end faiPrecheckThenRun callback (v10.161 S4)
  }
});
panel.add(s7dRunBtn);
panel.add(s7dStatusV);
panel.add(s7dResultV);
panel.add(lbl('CAVEAT: correlation is scored vs Center only (8 pairs), not the full 36-pair matrix. This is an empirical correlation network, not a mechanistic J_ij interaction matrix - shared external forcing (a heatwave hitting the whole area) will raise correlation with or without any real internal coupling change.',7,'#886600'));
panel.add(legDiv());

// ============================================================
// S7E - LOCAL vs REGIONAL AUTO-CLASSIFICATION (v10.111 NEW)
// The missing piece S7D didn't have: S7D's 9 nodes all sit within 0.3-3km
// of each other - they test spatial coupling WITHIN one reef, but every
// node is still local to that same reef, so "all 9 spike together" can't
// actually distinguish a local event big enough to blanket the reef from
// a genuine regional signal. This adds a real, independent reference:
// auto-searches outward in expanding rings (20/40/70/110/160km) for the
// nearest point that is genuinely shallow-water (GEBCO -50 to 0m, the
// same threshold used for shallowMask elsewhere in this tool), then runs
// the SAME FAI-based BEFORE/AFTER AC1/variance extraction there, and
// applies an explicit decision rule comparing the study reef to that
// reference - mirroring STEP 3's already-proven LOCAL/GLOBAL/ANOMALOUS/
// NO SIGNAL classification for SST, just applied to algae with a real
// reef reference instead of open ocean (open ocean has no algae signal
// to compare against at all).
// DISCLOSED LIMIT: "GEBCO says it's shallow" is not the same as "this is
// a real reef with comparable ecology" - it could be a sandbar or a bare
// shoal with no algae community at all. Partially mitigated (not solved)
// by checking the reference site's own data density as a proxy for
// whether it has a real, trackable satellite algae signal.
// ============================================================
panel.add(sHead('S7E - LOCAL vs REGIONAL AUTO-CLASSIFICATION (v10.124)','#5a1a2a'));
panel.add(lbl('Auto-finds a genuinely distant shallow-water reef (GEBCO search, 20-160km out) as a real regional reference, then applies an explicit decision rule: does the study reef show a change the reference reef does NOT (LOCAL), or do both change together (REGIONAL)? This is what actually separates local degradation from a regional climate shock - S7D alone could not do this, since all its nodes sit on the same reef.',7,'#883344'));
panel.add(lbl('v10.124: also runs a real permutation test (500 shuffles, same engine as STEP 3 COMPARE) on both study and reference sites - a genuine p-value alongside the threshold-based verdict above, at no extra Earth Engine cost (reuses the raw FAI data already fetched for the classification).',7,'#552266'));
panel.add(lbl('DISCLOSED LIMIT: a GEBCO shallow-water match is not guaranteed to be a real reef with comparable ecology (could be a bare sandbar). Partially checked (not solved) via the reference site\'s own data density - a very sparse signal there is flagged as low-confidence, not silently trusted.',7,'#886600'));
panel.add(lbl('Lat, Lon:',7,'#334466'));
var s7eCoordInput = ui.Textbox({placeholder:'lat, lon  e.g. -23.51, 152.09',style:{stretch:'horizontal',margin:'2px 4px',fontSize:'11px'}});
panel.add(s7eCoordInput);
var s7eUseLastClickBtn = ui.Button({
  label:'Use last clicked location (from map above)',
  style:{fontSize:'9px',margin:'2px 4px',backgroundColor:'#e8f4ff',color:'#225588',stretch:'horizontal',padding:'4px 4px',border:'1px solid #4488cc'},
  onClick:function(){
    if(lastClickLat===null||lastClickLon===null){
      s7eStatusV.setValue('No location clicked yet - click the map or use GO TO COORDINATES first.');
      s7eStatusV.style().set('color','#aa3300'); return;
    }
    s7eCoordInput.setValue(lastClickLat.toFixed(4)+', '+lastClickLon.toFixed(4));
    s7eStatusV.setValue('Location filled in. Fill in BEFORE/AFTER dates, then press RUN.');
    s7eStatusV.style().set('color','#115511');
  }
});
panel.add(s7eUseLastClickBtn);
panel.add(lbl('BEFORE start date + months:',7,'#115511'));
var s7eBeforeStartInput = ui.Textbox({placeholder:'e.g. 2021-06-01',style:{stretch:'horizontal',margin:'2px 4px',fontSize:'11px'}});
panel.add(s7eBeforeStartInput);
// v10.160 S5: default BEFORE raised 18 -> 24. MEASURED variance-ratio
// false-positive rate (seasonal amplitude 3 and 10, smooth / sawtooth /
// summer-spike cycles, noise SD 1, gap 0 and gap uniform 0-3, nPerm=300,
// 2000 draws/cell, nominal 5%): 18+12 runs 5.5-7.0%, 24+12 runs 4.5-5.9%.
// 24+12 also leaves 10 months of slack above CLIM_MIN_TOTAL_SAMPLES instead
// of 4, which matters because FAI is cloud-masked: measured emission rate of the
// p-value at 10 / 20 / 25% uniform per-month masking, under the v10.160 floor of
// 26 and with 3000 draws per cell, is 83.5 / 25.9 / 8.8% at 18+12 against
// 100 / 91.6 / 74.1% at 24+12; at 15% seasonally-clustered masking, 21.8%
// against 93.1%.
var s7eBeforeMonthsInput = ui.Textbox({placeholder:'months, e.g. 24',value:'24',style:{stretch:'horizontal',margin:'2px 4px',fontSize:'11px'}});
panel.add(s7eBeforeMonthsInput);
panel.add(lbl('AFTER start date + months:',7,'#aa3300'));
var s7eAfterStartInput = ui.Textbox({placeholder:'e.g. 2023-11-01',style:{stretch:'horizontal',margin:'2px 4px',fontSize:'11px'}});
panel.add(s7eAfterStartInput);
var s7eAfterMonthsInput = ui.Textbox({placeholder:'months, e.g. 12',value:'12',style:{stretch:'horizontal',margin:'2px 4px',fontSize:'11px'}});
panel.add(s7eAfterMonthsInput);
var s7eStatusV = ui.Label('Fill in the fields above, then press RUN. v10.167: 1 pre-check + 1 GEBCO reference search + ceil(span/12) chunked series calls, where span is the calendar months the two windows jointly cover (4 calls at a 24-month span, 5 at 31, 10 at the 95-month maximum). This is the panel whose single unchunked 36-month fetch NEVER RETURNED in a live run; each chunk now has a 4-minute deadline and refuses on screen rather than waiting forever.',
  {fontSize:'11px',fontWeight:'bold',color:'#555555',backgroundColor:'#eeeeee',padding:'6px 8px',margin:'2px 0',whiteSpace:'pre',border:'2px solid #aaaaaa'});
var s7eResultV = ui.Label('',{fontSize:'8px',color:'#5a1020',backgroundColor:'#faeef2',padding:'4px 6px',margin:'2px 0',whiteSpace:'pre'});
var s7eRunSeq = 0;   // v10.161 S6a
var s7eRunBtn = ui.Button({
  label:'RUN LOCAL vs REGIONAL CLASSIFICATION',
  style:{fontSize:'11px',fontWeight:'bold',margin:'2px 4px',backgroundColor:'#f0d0d8',color:'#5a1020',stretch:'horizontal',padding:'6px 4px',border:'2px solid #883344'},
  onClick:function(){
    var coordTxt=(s7eCoordInput.getValue()||'').trim();
    var beforeStartTxt=(s7eBeforeStartInput.getValue()||'').trim();
    var beforeMonthsTxt=(s7eBeforeMonthsInput.getValue()||'').trim();
    var afterStartTxt=(s7eAfterStartInput.getValue()||'').trim();
    var afterMonthsTxt=(s7eAfterMonthsInput.getValue()||'').trim();
    if(!coordTxt||!beforeStartTxt||!beforeMonthsTxt||!afterStartTxt||!afterMonthsTxt){
      s7eStatusV.setValue('MISSING - fill in Lat/Lon and both BEFORE/AFTER date+months fields.');
      s7eStatusV.style().set('color','#cc0000'); s7eStatusV.style().set('backgroundColor','#ffd0d0'); return;
    }
    var rawParts=coordTxt.split(',');
    if(rawParts.length!==2){s7eStatusV.setValue('Invalid format - use: lat, lon'); s7eStatusV.style().set('color','#cc0000'); return;}
    var latIn=parseCoordPart(rawParts[0]), lonIn=parseCoordPart(rawParts[1]);
    if(isNaN(latIn)||isNaN(lonIn)){s7eStatusV.setValue('Invalid format - use: lat, lon'); s7eStatusV.style().set('color','#cc0000'); return;}
    var beforeMonths=parseInt(beforeMonthsTxt,10), afterMonths=parseInt(afterMonthsTxt,10);
    // v10.159 W-01 item 4 set a floor of 12 months per box and claimed "the
    // pooled record is always >= CLIM_MIN_TOTAL_SAMPLES and the shipped defaults
    // always produce a properly deseasonalized, calibrated p-value". v10.160 S5:
    // that sentence was false on BOTH halves and is replaced rather than edited.
    //  - "always >= CLIM_MIN_TOTAL_SAMPLES": that floor counts VALID months, and
    //    12+12 sat exactly on it, so one masked month refused the whole test.
    //    Sentinel-2 FAI is cloud-masked. Measured p-value emission at 12+12 under
    //    the v10.159 floor of 24: 100% unmasked, 8.7% at 10% per-month masking,
    //    0.3% at 20%, 0.1% at 25%, and 0.0% at 25% seasonally-clustered
    //    (3000 draws/cell).
    //  - "calibrated": at 12+12 the measured variance-ratio false-positive rate
    //    was 1.1-4.1% at a fixed 0-month gap and 3.9-4.7% at a random 0-3 month
    //    gap, i.e. gap-dependent and conservative, with 21.7-24.8% power at gap 0.
    // FIXED by raising the DEFAULTS (see the month boxes above) and by checking
    // the POOLED total here, not just the per-box minimum. The per-box floor of
    // 12 stays - below one full annual cycle per window there is nothing to
    // estimate a seasonal cycle from - and the pooled total must now clear
    // CLIM_MIN_TOTAL_SAMPLES before the run starts, instead of the test
    // discovering it later and reporting NOT TESTABLE. Note what this check
    // CANNOT do: it counts NOMINAL months, and the floor counts VALID ones, so a
    // heavily masked record can still fall under it. That is why the defaults now
    // sit 10 months clear of the floor rather than on it.
    if(isNaN(beforeMonths)||beforeMonths<12||beforeMonths>36||isNaN(afterMonths)||afterMonths<12||afterMonths>36){
      s7eStatusV.setValue('BEFORE/AFTER months must each be 12-36 (v10.159: raised from 4 - below one full annual cycle per window there is nothing to estimate the seasonal cycle from).');
      s7eStatusV.style().set('color','#cc0000'); return;
    }
    // v10.160 S5: the POOLED total is what the climatology floor is applied to.
    if((beforeMonths+afterMonths) < CLIM_MIN_TOTAL_SAMPLES){
      s7eStatusV.setValue('BEFORE + AFTER must total at least '+CLIM_MIN_TOTAL_SAMPLES+' months (you asked for '+(beforeMonths+afterMonths)+'). '+
        'Below that the seasonal cycle cannot be estimated well enough to remove, and no p-value is reported. MEASURED at a 24-month pooled record '+
        '(seasonal amplitude 3, noise SD 1, 3000 draws): a real five-fold rise in the AFTER window noise is detected only 21.7-24.8% of the time at a '+
        '0-month BEFORE/AFTER gap. Note this check counts NOMINAL months; the floor counts VALID ones, so on a cloud-masked record leave real slack - '+
        'the shipped default of 24+12 sits 10 months clear of the floor.');
      s7eStatusV.style().set('color','#cc0000'); return;
    }
    // v10.162 S1: combined-span cap, checked before any EE call is spent.
    var _s7eSpanPre = combinedWindowSpan(beforeStartTxt, beforeMonths, afterStartTxt, afterMonths);
    var _s7eSpanRefusal = combinedSpanRefusal(_s7eSpanPre, beforeMonths, afterMonths);
    if(_s7eSpanRefusal){ s7eStatusV.setValue(_s7eSpanRefusal); s7eStatusV.style().set('color','#cc0000');
      s7eStatusV.style().set('backgroundColor','#ffd0d0'); s7eStatusV.style().set('whiteSpace','pre'); return; }
    s7eRunSeq++; var s7eMyRun=s7eRunSeq;   // v10.161 S6a
    recordStudySite(latIn, lonIn, 'S7E');

    // v10.161 S4: cheap FAI data-density gate BEFORE the GEBCO reference search
    // and the 2 heavy FAI fetches. Checked at the STUDY point only - the
    // reference reef is not known yet at this stage, and a study site that
    // cannot produce 4 valid months makes the whole comparison impossible
    // regardless of what the reference turns out to be.
    faiPrecheckThenRun({lat:latIn, lon:lonIn, moduleName:'S7E', statusLbl:s7eStatusV, resultLbl:s7eResultV,
      windows:[{name:'BEFORE',start:beforeStartTxt,months:beforeMonths},
               {name:'AFTER', start:afterStartTxt, months:afterMonths}],
      cannotRunTxt:'S7C-S7F cannot run here.'}, function(_pre){

    function destinationPoint(lat, lon, bearingDeg, distKm){
      var R=6371, brng=bearingDeg*Math.PI/180, lat1=lat*Math.PI/180, lon1=lon*Math.PI/180;
      var lat2=Math.asin(Math.sin(lat1)*Math.cos(distKm/R)+Math.cos(lat1)*Math.sin(distKm/R)*Math.cos(brng));
      var lon2=lon1+Math.atan2(Math.sin(brng)*Math.sin(distKm/R)*Math.cos(lat1),Math.cos(distKm/R)-Math.sin(lat1)*Math.sin(lat2));
      return {lat:lat2*180/Math.PI, lon:lon2*180/Math.PI};
    }
    var searchRadiiKm=[20,40,70,110,160];
    var candidates=[];
    searchRadiiKm.forEach(function(rKm){
      for(var b=0;b<360;b+=45){
        var d=destinationPoint(latIn,lonIn,b,rKm);
        candidates.push({lat:d.lat,lon:d.lon,radiusKm:rKm,bearing:b});
      }
    });
    var candFeats = candidates.map(function(c,idx){
      return ee.Feature(ee.Geometry.Point([c.lon,c.lat]), {idx:idx, radiusKm:c.radiusKm});
    });
    var candFC = ee.FeatureCollection(candFeats);
    var rCandidates = GEBCO.reduceRegions({collection:candFC, reducer:ee.Reducer.first(), scale:500});

    s7eStatusV.setValue('Step 1/2: Searching 20-160km out for a genuine shallow-water reference reef (1 batched GEBCO call)...');
    s7eStatusV.style().set('color','#334466'); s7eStatusV.style().set('backgroundColor','#eeeeee');
    s7eStatusV.style().set('border','2px solid #aaaaaa'); s7eStatusV.style().set('whiteSpace','pre');
    s7eResultV.setValue('');

    rCandidates.evaluate(function(candResult, candErr){
      if(candErr){
        s7eStatusV.setValue(friendlyEEError(candErr));
        s7eStatusV.style().set('color','#cc0000'); s7eStatusV.style().set('backgroundColor','#ffd0d0');
        s7eStatusV.style().set('border','2px solid #cc0000');
        print('=== S7E candidate search error === '+candErr);
        return;
      }
      try {
        var feats = (candResult&&candResult.features)?candResult.features:[];
        var best=null;
        // v10.116 NEW: exclude candidates that coincide with a site already
        // tested as a STUDY location this session (S7B/S7C/S7D/S7E) - a
        // reference is supposed to be an uninvolved baseline, not a site
        // that has already tested positive for its own change. Caught from
        // a real run where the auto-found reference landed on Low Isles,
        // which had already been tested (and shown a real signal) as a
        // study site earlier in the same session.
        var EXCLUDE_RADIUS_KM = 5;
        var excludedByHistoryCount = 0;
        var shallowCandidateCount = 0;
        // v10.168 S7E-01: tally WHY each of the 40 probes was rejected. Through
        // v10.167 a failed search printed only "no GEBCO shallow-water match",
        // which is indistinguishable from a broken search. At Kona the search is
        // in fact CORRECT to fail - Hawaii is a volcanic island with no shelf,
        // so every probe is either dry land or already abyssal - but the user
        // could not tell that from the message and reasonably asked whether it
        // was a bug. These counters cost nothing (the elevations are already in
        // hand) and turn a bare refusal into evidence for it.
        var nLand=0, nTooDeep=0, nNoData=0;
        var shallowestOceanElev=null, shallowestOceanKm=null;
        for(var i=0;i<feats.length;i++){
          var p=feats[i].properties;
          var elev=extractReduceRegionsValue(p,'elevation');
          if(elev===null){ nNoData++; }
          else if(elev>=0){ nLand++; }
          else {
            if(elev<=-50) nTooDeep++;
            // shallowest (least negative) ocean probe, whatever ring it came from
            if(shallowestOceanElev===null || elev>shallowestOceanElev){
              shallowestOceanElev=elev; shallowestOceanKm=p.radiusKm;
            }
          }
          if(elev!==null && elev>-50 && elev<0){
            shallowCandidateCount++;
            var candLat=candidates[p.idx].lat, candLon=candidates[p.idx].lon;
            var tooCloseToHistory=false;
            for(var h=0;h<s7StudySiteHistory.length;h++){
              if(haversineKm(candLat,candLon,s7StudySiteHistory[h].lat,s7StudySiteHistory[h].lon) < EXCLUDE_RADIUS_KM){
                tooCloseToHistory=true; break;
              }
            }
            if(tooCloseToHistory){ excludedByHistoryCount++; continue; }
            if(!best || p.radiusKm<best.radiusKm) best={radiusKm:p.radiusKm, idx:p.idx, elev:elev,
              lat:candLat, lon:candLon};
          }
        }
        if(!best){
          var noRefMsg = shallowCandidateCount>0 && excludedByHistoryCount===shallowCandidateCount ?
            'NO REFERENCE REEF FOUND within 160km - '+shallowCandidateCount+' shallow-water candidate(s) found, but ALL of them '+
            'coincide with a site already tested as a STUDY location this session (within '+EXCLUDE_RADIUS_KM+'km). '+
            'Try a different study site, or clear the session by reloading if you want to allow reuse.' :
            ('NO REFERENCE REEF FOUND within 160km (no GEBCO shallow-water match at 20/40/70/110/160km, 8 bearings each).\n' +
             'Of the '+feats.length+' probes: '+nLand+' on dry land, '+nTooDeep+' already deeper than 50 m, '+nNoData+' no GEBCO value.\n' +
             (shallowestOceanElev!==null ?
               'Shallowest water found anywhere in the search: '+Math.round(-shallowestOceanElev)+' m, at the '+shallowestOceanKm+' km ring.\n' :
               'No probe returned a below-sea-level GEBCO value at all.\n') +
             'If almost every probe is land-or-abyssal with nothing in between, that is the expected answer for an oceanic volcanic island ' +
             '(Hawaii, the Marquesas, Reunion): the seafloor drops from the shoreline to abyssal depth with no shelf, so there is no distant ' +
             'shallow reference reef to find and S7E genuinely cannot run here - it is not a failed lookup.\n' +
             'S7D (within-reef nodes) still works at such a site; what you lose is only the local-vs-regional split, which needs a second reef.');
          s7eStatusV.setValue(noRefMsg);
          s7eStatusV.style().set('color','#cc0000'); s7eStatusV.style().set('backgroundColor','#ffd0d0');
          s7eStatusV.style().set('border','2px solid #cc0000'); s7eStatusV.style().set('whiteSpace','pre');
          print('=== S7E: no reference reef candidate found within 160km ('+excludedByHistoryCount+' excluded as prior study sites) ===');
          // v10.168 S7E-01: the same tally to the console, so it survives in the
          // run log after the on-screen label is overwritten by the next run.
          print('  S7E probe tally: '+feats.length+' probed | '+nLand+' land | '+nTooDeep+' deeper than 50m | '+
                nNoData+' no GEBCO value | shallowest water '+
                (shallowestOceanElev!==null?(Math.round(-shallowestOceanElev)+'m at the '+shallowestOceanKm+'km ring'):'none'));
          return;
        }

        s7eStatusV.setValue('Step 2/2: Reference reef found '+best.radiusKm+'km away (depth '+best.elev.toFixed(1)+'m)'+
          (excludedByHistoryCount>0?' ['+excludedByHistoryCount+' closer candidate(s) skipped - already tested as a study site]':'')+'. '+
          'Fetching the combined BEFORE..AFTER FAI series at study + reference, in chunks of at most '+
          S7_FAI_MAX_MONTHS_PER_CALL+' months (v10.167)...');

        var studyPtBuf=ee.Geometry.Point([lonIn,latIn]).buffer(150);
        var refPtBuf=ee.Geometry.Point([best.lon,best.lat]).buffer(150);
        var pairFC=ee.FeatureCollection([
          ee.Feature(studyPtBuf,{label:'Study'}),
          ee.Feature(refPtBuf,{label:'Reference'})
        ]);
        // v10.162 S1: ONE combined BEFORE..AFTER series for study + reference,
        // sliced client-side by timestamp. This is the call that returned
        // nothing in the live Bocas del Toro run and left this panel parked on
        // "Still waiting on: BEFORE FAI series" with no way to time out.
        var _s7eSpan = combinedWindowSpan(beforeStartTxt, beforeMonths, afterStartTxt, afterMonths);
        // v10.167 FIX 20 / S1 + S2: this is the fetch that NEVER RETURNED in the
        // live 36-month runs. Chunked to the same 12-months-per-call bound as
        // S7D (2 regions here, so the 108-feature ceiling is not the binding
        // one - the 12-month one is), and guarded by the per-call deadline, so
        // a call that does not answer becomes a visible refusal instead of a
        // panel parked on "Still waiting on: ..." with nothing able to clear it.
        var _s7eGrid = s7FaiGridSpan(beforeStartTxt, beforeMonths, afterStartTxt, afterMonths);
        var _s7eRegions = 2;
        var _s7ePlan = s7FaiChunkPlan(_s7eGrid.startDateStr, _s7eGrid.nMonths, _s7eRegions);
        var _s7eSeriesCalls = _s7ePlan.length;

        var s7ePending=1, s7eErrors=0, s7eData={}, s7eDead=false;
        var s7eWaiting=['combined BEFORE..AFTER FAI series ('+_s7eSeriesCalls+' chunked call(s))'];
        var s7eCallName={combined:'combined BEFORE..AFTER FAI series ('+_s7eSeriesCalls+' chunked call(s))'};
        function s7eBump(key,v,e){
          if(s7eMyRun!==s7eRunSeq || s7eDead) return;   // v10.161 S6a
          s7eData[key]=e?null:v;
          if(e) s7eErrors++;
          s7ePending--;
          var _wait=s7Outstanding(s7eWaiting, s7eCallName[key]||key);
          s7eStatusV.setValue('Step '+(3-s7ePending)+'/2: '+(1-s7ePending)+' / 1 batched call group done...\n'+_wait+
            (s7ePending>0?('\n'+S7_STALL_HINT+' (search "S7E [" in the Console.)'):''));
          if(s7ePending===0) s7eFinish();
        }
        // v10.167 FIX 20 / S2: S7E now refuses exactly the way S7D does.
        function s7eRefuseChunks(res){
          if(s7eMyRun!==s7eRunSeq || s7eDead) return;
          s7eDead=true;
          var txt=s7ChunkRefusalText('S7E', res, _s7eRegions);
          s7eStatusV.setValue('CANNOT CLASSIFY\n'+txt);
          s7eStatusV.style().set('color','#cc0000'); s7eStatusV.style().set('backgroundColor','#ffd0d0');
          s7eStatusV.style().set('border','2px solid #cc0000'); s7eStatusV.style().set('whiteSpace','pre');
          s7eStatusV.style().set('fontWeight','bold');
          s7eResultV.setValue('Chunk plan was '+_s7eSeriesCalls+' call(s) over '+_s7eGrid.nMonths+
            ' month(s) x '+_s7eRegions+' sites, starting '+_s7eGrid.startDateStr+'.'+(_pre&&_pre.note?'\n'+_pre.note:''));
          print('=== S7E REFUSED (v10.167 chunked fetch: '+res.reason+') === '+(res.detail||''));
        }
        function s7eFinish(){
          if(s7eMyRun!==s7eRunSeq) return;   // v10.161 S6a
          try {
            // v10.162 S1: slice the ONE combined series by real timestamp.
            var combinedByNode=groupSeriesByLabel(s7eData.combined,'fai');
            var beforeByNode=sliceSeriesMapByWindow(combinedByNode, beforeStartTxt, beforeMonths);
            var afterByNode =sliceSeriesMapByWindow(combinedByNode, afterStartTxt,  afterMonths);
            // Refuse with the existing insufficient-data wording if the combined
            // series does not actually cover both windows at the study site.
            var _s7eShort = combinedSliceShortfall(beforeByNode['Study']||[], afterByNode['Study']||[], 4);
            if(_s7eShort){
              s7eStatusV.setValue('CANNOT CLASSIFY (insufficient data in at least one period)\n'+_s7eShort);
              s7eStatusV.style().set('color','#cc0000'); s7eStatusV.style().set('backgroundColor','#ffd0d0');
              s7eStatusV.style().set('border','2px solid #cc0000'); s7eStatusV.style().set('whiteSpace','pre');
              s7eResultV.setValue('Chunked fetch returned '+((s7eData.combined&&s7eData.combined.features)?s7eData.combined.features.length:0)+
                ' raw feature(s) across '+_s7eGrid.nMonths+' month(s) x '+_s7eRegions+' sites in '+_s7eSeriesCalls+
                ' call(s).'+(_pre&&_pre.note?'\n'+_pre.note:''));
              print('=== S7E REFUSED (v10.162 S1 combined-slice shortfall) === '+_s7eShort);
              return;
            }
            // v10.160 S6: pooled climatology per site, shared across its two windows.
            var _eStudyClim=pooledClimFor(beforeByNode['Study']||[], afterByNode['Study']||[]);
            var _eRefClim  =pooledClimFor(beforeByNode['Reference']||[], afterByNode['Reference']||[]);
            var studyB=jsNodeStatsFixed(beforeByNode['Study']||[], _eStudyClim);
            var studyA=jsNodeStatsFixed(afterByNode['Study']||[], _eStudyClim);
            var refB=jsNodeStatsFixed(beforeByNode['Reference']||[], _eRefClim);
            var refA=jsNodeStatsFixed(afterByNode['Reference']||[], _eRefClim);

            var dAC1_study=(studyB.realAC1!==null&&studyA.realAC1!==null)?(studyA.realAC1-studyB.realAC1):null;
            var dVar_study=(studyB.varTrendRatio!==null&&studyA.varTrendRatio!==null)?(studyA.varTrendRatio-studyB.varTrendRatio):null;
            var dAC1_ref=(refB.realAC1!==null&&refA.realAC1!==null)?(refA.realAC1-refB.realAC1):null;
            var dVar_ref=(refB.varTrendRatio!==null&&refA.varTrendRatio!==null)?(refA.varTrendRatio-refB.varTrendRatio):null;

            // v10.111: refValidity is a proxy, not proof, that the auto-
            // found GEBCO match is a real reef with a trackable algae
            // signal - low data density there means "shallow" but not
            // necessarily "ecologically comparable".
            var refDataDensity = (refB.nValidMonths+refA.nValidMonths)/(beforeMonths+afterMonths);
            var refLowConfidence = refDataDensity<0.4;

            // v10.153 FIX 10: THIS is the rule that was measured firing on
            // 80% of no-event windows (AC1 OR variance, at 0.01 / 0.15x).
            // Now uses the calibrated cutoffs for the actual window length.
            var _s7eThrB = getCalibratedThresholds(beforeMonths);
            var _s7eThrA = getCalibratedThresholds(afterMonths);
            var _s7eAc1 = Math.max(_s7eThrB.ac1, _s7eThrA.ac1);
            var _s7eVar = Math.max(_s7eThrB.varr, _s7eThrA.varr);
            // v10.170 FAI-01b: S7E had NO artifact check at all, and unlike S7F
            // (which gates on permutation p-values, so a degenerate denominator
            // cannot reach its verdict) this rule thresholds ΔVar DIRECTLY. A
            // degenerate FAI variance ratio could therefore drive a headline of
            // "LOCAL ANOMALY DETECTED" off division by near-nothing. S7C and S7D
            // flagged the same condition on screen; here it silently decided.
            // The BEFORE window is the denominator of ΔVar, so the BEFORE halves
            // are the right scale, and the guard is per SITE - the study site's
            // artifact must not suppress the reference's variance term or vice
            // versa. Following the v10.157 precedent, an artifact removes only
            // the VARIANCE term; the AC1 term is measured separately and stands.
            var studyVarDegenerate = isVarRatioArtifact(studyB.varFirstHalf, dVar_study,
                                       varScaleRefOf(studyB.varFirstHalf, studyB.varSecondHalf));
            var refVarDegenerate   = isVarRatioArtifact(refB.varFirstHalf, dVar_ref,
                                       varScaleRefOf(refB.varFirstHalf, refB.varSecondHalf));
            var studySignal = (dAC1_study!==null&&dAC1_study>_s7eAc1) ||
                              (!studyVarDegenerate && dVar_study!==null && dVar_study>_s7eVar);
            var refSignal = (dAC1_ref!==null&&dAC1_ref>_s7eAc1) ||
                            (!refVarDegenerate && dVar_ref!==null && dVar_ref>_s7eVar);

            function fmtN(v,d){ return (v!==null&&v!==undefined&&!isNaN(v))?v.toFixed(d):'n/a'; }

            // v10.114 FIX: a real run showed "LOCAL ANOMALY DETECTED" when
            // the reference site's dAC1/dVar were BOTH null (n/a) - not
            // because the reference was tested and found stable, but
            // because it had no computable data (one of its two periods
            // had <4 valid months, even though its COMBINED density of 55%
            // looked fine and wasn't flagged low-confidence). "Untested"
            // and "tested and stable" are very different findings, but the
            // old rule collapsed both into refSignal=false, so a real
            // signal at the study site got labelled a confirmed LOCAL
            // ANOMALY against a reference that was never actually able to
            // confirm anything. Now checked per-period (not just combined
            // density) and given its own explicit "CANNOT CLASSIFY" state
            // instead of silently defaulting to "no signal".
            var refInsufficient = (refB.nValidMonths<4 || refA.nValidMonths<4);
            var studyInsufficient = (studyB.nValidMonths<4 || studyA.nValidMonths<4);

            var verdict, vCol, vBg;
            if(refInsufficient && studyInsufficient){
              verdict='CANNOT CLASSIFY - both study and reference have insufficient valid months (<4) in at least one period - not enough data to compare, not a confirmed finding either way.';
              vCol='#888888'; vBg='#eeeeee';
            } else if(refInsufficient){
              verdict='CANNOT CLASSIFY - reference site has insufficient valid months (<4) in '+
                (refB.nValidMonths<4&&refA.nValidMonths<4?'BOTH periods':refB.nValidMonths<4?'the BEFORE period':'the AFTER period')+
                '. The study site\'s own signal ('+(studySignal?'SIGNAL':'no signal')+') cannot be confirmed as local vs regional without a reference that could actually be tested - do not treat this as a confirmed local anomaly.';
              vCol='#886600'; vBg='#fff6cc';
            } else if(studyInsufficient){
              verdict='CANNOT CLASSIFY - study site has insufficient valid months (<4) in '+
                (studyB.nValidMonths<4&&studyA.nValidMonths<4?'BOTH periods':studyB.nValidMonths<4?'the BEFORE period':'the AFTER period')+
                ' - cannot assess whether the study site changed at all.';
              vCol='#888888'; vBg='#eeeeee';
            } else if(studySignal && !refSignal){
              verdict='LOCAL ANOMALY DETECTED - study reef shows a change the regional reference does NOT';
              vCol='#880000'; vBg='#ffd0d0';
            } else if(studySignal && refSignal){
              verdict='REGIONAL SIGNAL - both study AND reference reef show similar changes, not specific to your study site';
              vCol='#886600'; vBg='#fff6cc';
            } else if(!studySignal && refSignal){
              verdict='ANOMALOUS - reference reef shows change, study site does NOT (study may be locally buffered/protected)';
              vCol='#115511'; vBg='#d4f5df';
            } else {
              verdict='NO SIGNAL AT EITHER SITE';
              vCol='#226644'; vBg='#e8f4ff';
              // v10.113 FIX: the same gap already caught and fixed for
              // STEP 5 in v10.97 ("no significant trend" was hiding a real
              // significant DECLINE) existed here too, uncaught until a
              // real run showed it directly: study AC1 fell -0.675,
              // reference fell -0.636 - nearly identical, a coherent
              // regional pattern - but the SIGNAL check only looks for
              // RISING AC1/variance (correctly, per Dakos et al. - a
              // decline isn't a CSD warning), so this got silently folded
              // into a bare "NO SIGNAL" with no mention of the pattern
              // underneath it. Now surfaced explicitly when both sites
              // show a similar, substantial AC1 decline.
              if(dAC1_study!==null && dAC1_ref!==null && dAC1_study<-0.1 && dAC1_ref<-0.1 &&
                 Math.abs(dAC1_study-dAC1_ref)<0.15){
                verdict += ' - but note: AC1 fell similarly at both sites (study '+dAC1_study.toFixed(2)+
                  ', reference '+dAC1_ref.toFixed(2)+') - a coherent REGIONAL DECLINE, not a CSD warning direction '+
                  '(Dakos et al. 2012: rising AC1 is the meaningful signal, not falling), but worth noting as '+
                  'consistent regional behaviour rather than pure noise.';
              }
            }
            // v10.112 FIX: reference density was shown, but STUDY's own
            // data density never was - so a real run showing STUDY n/a
            // gave no way to tell whether the study site itself had sparse
            // Sentinel-2 coverage (likely at cloudy sites, e.g. Daintree/
            // Cape Tribulation rainforest coast) versus some other cause.
            var studyDataDensity = (studyB.nValidMonths+studyA.nValidMonths)/(beforeMonths+afterMonths);
            var studyLowConfidence = studyDataDensity<0.4;
            if(refLowConfidence) verdict += ' [LOW CONFIDENCE: reference site has sparse data - '+
              Math.round(refDataDensity*100)+'% coverage - may not be a real algae-bearing reef]';
            if(studyLowConfidence) verdict += ' [STUDY SITE ALSO SPARSE: '+Math.round(studyDataDensity*100)+
              '% coverage - likely heavy cloud cover at this location/window, not a real "no signal" finding]';

            // v10.124 NEW: real permutation-test p-values for S7E, porting
            // the SAME engine already validated in STEP 3 COMPARE and FIND
            // SWEET SPOT (v10.122/123) to the algae-based local/regional
            // classification - closing the gap directly flagged in
            // discussion: "the permutation-testing claim needs a caveat -
            // it protects the SST-based findings right now, not yet the
            // algae-based ones." Requires ZERO new EE calls: the raw FAI
            // series for study and reference were already fetched above
            // (beforeByNode/afterByNode) to compute studyB/studyA/refB/
            // refA - this just runs the existing permutationTestDelta()
            // engine on that same already-fetched data.
            var studyAC1Test = permutationTestDeltaFixed(beforeByNode['Study']||[], afterByNode['Study']||[], statAC1ForPerm, 500);
            var studyVarTest = permutationTestDeltaFixed(beforeByNode['Study']||[], afterByNode['Study']||[], statVarRatioForPerm, 500);
            var refAC1Test = permutationTestDeltaFixed(beforeByNode['Reference']||[], afterByNode['Reference']||[], statAC1ForPerm, 500);
            var refVarTest = permutationTestDeltaFixed(beforeByNode['Reference']||[], afterByNode['Reference']||[], statVarRatioForPerm, 500);


            var lines=[];
            lines.push('Reference reef: '+best.lat.toFixed(4)+', '+best.lon.toFixed(4)+' ('+best.radiusKm+'km away, depth='+best.elev.toFixed(1)+'m), data density='+Math.round(refDataDensity*100)+'%'+
              (refLowConfidence?' (LOW - treat with caution)':''));
            if(excludedByHistoryCount>0) lines.push('NOTE: '+excludedByHistoryCount+' closer shallow-water candidate(s) were skipped because they coincide with a site already tested as a STUDY location this session (v10.116).');
            lines.push('Study site data density: '+Math.round(studyDataDensity*100)+'% ('+studyB.nValidMonths+'/'+beforeMonths+' BEFORE, '+
              studyA.nValidMonths+'/'+afterMonths+' AFTER valid months)'+(studyLowConfidence?' (LOW - likely cloud-limited, not a real null result)':''));
            // v10.161 S4: same independence note as S7F - see the long comment there.
            if(studyB.nValidMonths===refB.nValidMonths && studyA.nValidMonths===refA.nValidMonths){
              lines.push('NOTE: study and reference report IDENTICAL valid-month counts. They ARE measured '+
                'separately (two labelled regions, bucketed strictly by label - there is no path by which '+
                'one can inherit the other). Sentinel-2 scene availability is a per-granule property and a '+
                'granule is ~110km across, so two sites this close normally share the same scene list.');
            }
            lines.push(repeatChar('\u2500',50));
            lines.push('STUDY  : \u0394AC1='+fmtN(dAC1_study,3)+' \u0394Var='+fmtN(dVar_study,2)+'x'+
              (studyVarDegenerate?' \u26A0ARTIFACT (variance term EXCLUDED from this verdict)':'')+
              ' -> '+(studySignal?'SIGNAL':'no signal'));
            lines.push('REFERENCE: \u0394AC1='+fmtN(dAC1_ref,3)+' \u0394Var='+fmtN(dVar_ref,2)+'x'+
              (refVarDegenerate?' \u26A0ARTIFACT (variance term EXCLUDED from this verdict)':'')+
              ' -> '+(refSignal?'SIGNAL':'no signal'));
            if(studyVarDegenerate||refVarDegenerate) lines.push(CSD_VAR_ARTIFACT_MSG_RELATIVE);
            lines.push(repeatChar('\u2500',50));
            lines.push('BEFORE: '+beforeStartTxt+' + '+beforeMonths+'mo | AFTER: '+afterStartTxt+' + '+afterMonths+'mo');
            lines.push('Decision rule (v10.153 CALIBRATED): study signal (\u0394AC1>'+_s7eAc1.toFixed(3)+
              ' OR \u0394Var>'+_s7eVar.toFixed(2)+'x) vs reference signal, same cutoffs.');
            lines.push('These replace the old 0.01 / 0.15x values, which were MEASURED firing on 80% of');
            lines.push('windows at a site with no regime shift (Scripps Pier CTD, 13.6yr, 104-176 splits).');
            lines.push('Expect far fewer LOCAL ANOMALY verdicts than before.');
            // v10.159 W-01 item 3: v10.158 said the p-values below were "the only
            // figures here with a known false-positive rate". At the shipped 18+12
            // month boxes v10.158 ran them on a RAW, non-deseasonalized series at a
            // MEASURED 10.4-39.8% false-positive rate against a nominal 5%, so that
            // sentence asserted the opposite of the truth. Corrected, not deleted:
            // the claim is now true only for a p-value that says so.
            lines.push('The permutation p-values below are the only figures here with a known false-');
            lines.push('positive rate, AND ONLY WHERE ONE IS ACTUALLY REPORTED. Where the seasonal');
            lines.push('cycle cannot be removed this panel reports NOT TESTABLE and a reason, instead');
            lines.push('of the uncalibrated number v10.158 printed there.');
            lines.push('v10.160 CORRECTION: v10.159 quoted "4.5-6.2% across every configuration" here.');
            lines.push('That was measured on the VARIANCE statistic only. MEASURED separately, the');
            lines.push('variance p-value runs 4.3-7.0% against a nominal 5% across the shipped window');
            lines.push('lengths, seasonal shapes and gap policies; the AC1 p-value ran 0.2-3.2% - a DEAD');
            lines.push('statistic, not a safe one - below '+CSD_AC1_MIN_POOLED_MONTHS+' pooled valid months, and is now refused');
            lines.push('there rather than reported. At this panel\'s '+beforeMonths+'+'+afterMonths+' month boxes that means');
            lines.push((beforeMonths+afterMonths>=CSD_AC1_MIN_POOLED_MONTHS?'the AC1 p-value IS reported.':'the AC1 p-value is NOT reported - only the variance one.'));
            if(s7eErrors>0) lines.push('NOTE: the batched series group returned no usable data (v10.167: '+_s7eSeriesCalls+
              ' chunked BEFORE..AFTER call(s), merged client-side).');
            lines.push(repeatChar('\u2500',50));
            lines.push('=== PERMUTATION TEST (real p-value, 500 shuffles, algae/FAI) ===');
            lines.push('Same engine as STEP 3 COMPARE (v10.122), applied here to algae instead of SST -');
            lines.push('answers whether the >0.01/>0.15 threshold verdict above reflects a genuinely rare');
            lines.push('pattern, or one ordinary random noise would produce anyway. Zero extra EE calls -');
            lines.push('reuses the raw FAI series already fetched for the classification above.');
            // v10.159 W-01 item 2: these four went out bare. They now go through
            // permP()/permVerdictTag(), which refuse to attach significance
            // wording to anything that is not a p-value from a properly
            // deseasonalized series, and the reason is printed underneath.
            lines.push('Study AC1     '+permP(studyAC1Test)+permVerdictTag(studyAC1Test));
            lines.push('Study Var     '+permP(studyVarTest)+permVerdictTag(studyVarTest));
            lines.push('Reference AC1 '+permP(refAC1Test)+permVerdictTag(refAC1Test));
            lines.push('Reference Var '+permP(refVarTest)+permVerdictTag(refVarTest));
            lines.push('SERIES USED: '+permSeriesNote(studyAC1Test,'study'));
            lines.push('             '+permSeriesNote(refAC1Test,'reference'));
            var _s7eDisc=nodeStatsDisclosureLines([{label:'study BEFORE',st:studyB},{label:'study AFTER',st:studyA},
                                                   {label:'reference BEFORE',st:refB},{label:'reference AFTER',st:refA}]);
            if(_s7eDisc.length>0){
              lines.push('SERIES QUALITY (v10.159 W-02 - these were computed and never shown before):');
              _s7eDisc.forEach(function(d){ lines.push(d); });
            }
            if(_pre && _pre.note) lines.push('STUDY-SITE '+_pre.note);   // v10.161 S4
            s7eResultV.setValue(lines.join('\n'));

            s7eStatusV.setValue(verdict);
            s7eStatusV.style().set('color',vCol); s7eStatusV.style().set('backgroundColor',vBg);
            s7eStatusV.style().set('border','2px solid '+vCol); s7eStatusV.style().set('whiteSpace','pre'); s7eStatusV.style().set('fontWeight','bold');

            print('=== S7E LOCAL vs REGIONAL AUTO-CLASSIFICATION ===');
            print(verdict);
            print(lines.join('\n'));
          } catch(errFinal2){
            s7eStatusV.setValue(friendlyEEError(errFinal2));
            s7eStatusV.style().set('color','#cc0000'); s7eStatusV.style().set('backgroundColor','#ffd0d0');
            s7eStatusV.style().set('border','2px solid #cc0000'); s7eStatusV.style().set('whiteSpace','pre');
            print('=== S7E FINISH ERROR === '+errFinal2);
          }
        }
        // v10.125 NEW: real diagnostics on S7E's series call (v10.162: one
        // combined call, not two), porting
        // the exact pattern already proven for S7D in v10.108. Caught from
        // a real run that stayed stuck at "1/2 batched calls done" even
        // after a page reload (ruling out an expired session) AND after
        // shortening to 12/10-month windows (ruling out the window-length
        // slowness already fixed for S7D at 18/12mo) - a genuinely new,
        // undiagnosed failure mode. Rather than guess a third fix blind,
        // this makes the NEXT run tell us exactly which of the two calls
        // (BEFORE or AFTER FAI fetch) is failing and why.
        fetchFaiSeriesChunked({
          gridStartStr:_s7eGrid.startDateStr, nMonths:_s7eGrid.nMonths, ptsFC:pairFC,
          nRegions:_s7eRegions, band:'fai', scale:20, tag:'S7E',
          isCurrent:function(){ return s7eMyRun===s7eRunSeq && !s7eDead; },
          onProgress:function(i,total,ch){
            if(s7eMyRun!==s7eRunSeq || s7eDead) return;
            s7eStatusV.setValue('Step 2/2: series chunk '+(i+1)+' / '+total+' ('+ch.start.substring(0,7)+' + '+
              ch.months+' months x '+_s7eRegions+' sites).\n'+S7_STALL_HINT+' (search "S7E [" in the Console.)\n'+
              S7_DEADLINE_NOTE);
          }
        }, function(res){
          if(!res.ok){ s7eRefuseChunks(res); return; }
          print('=== S7E [combined BEFORE..AFTER series] OK - '+
            ((res.fc&&res.fc.features)?res.fc.features.length:0)+' feature(s) across '+res.nCalls+' chunked call(s) ===');
          s7eBump('combined', res.fc, null);
        });
      } catch(errFinal){
        s7eStatusV.setValue(friendlyEEError(errFinal));
        s7eStatusV.style().set('color','#cc0000'); s7eStatusV.style().set('backgroundColor','#ffd0d0');
        s7eStatusV.style().set('border','2px solid #cc0000'); s7eStatusV.style().set('whiteSpace','pre');
        print('=== S7E CANDIDATE PROCESSING ERROR === '+errFinal);
      }
    });
    });  // end faiPrecheckThenRun callback (v10.161 S4)
  }
});
panel.add(s7eRunBtn);
panel.add(s7eStatusV);
panel.add(s7eResultV);
panel.add(legDiv());

// ============================================================
// S7F - RUN ALL: S7D + S7E COMBINED (v10.116 NEW)
// Direct response to a real request: enter Lat/Lon + one BEFORE/AFTER
// window ONCE, get both the within-reef coupling picture (S7D) and the
// local-vs-regional classification (S7E) together, tabulated in one
// summary - instead of re-typing the same coordinates and dates into two
// separate forms.
// SCOPE NOTE (deliberate, explained to the user before building): this
// does NOT auto-try multiple window lengths, and does NOT chain in S7B/
// S7C/S13. Both were considered and declined: this session directly
// demonstrated why - a single S7D call with too-long a window hung for
// 5+ minutes with no way to cancel it (no setTimeout in this sandbox),
// and Earth Engine's account-level concurrency quota was hit once
// already this session, requiring a manual tier upgrade. An orchestrator
// that tries several window lengths across every S7 tool would multiply
// both the hang risk and the quota load severalfold, with no reliable
// way to know if a huge combined run is progressing or stuck. This
// version fires a bounded call budget (v10.162: 4 - each site fetched ONE
// combined BEFORE..AFTER series and sliced the two windows out of it
// client-side; under v10.116-v10.161 it was 6). v10.167 FIX 20: both of those
// combined fetches are the shape that returned 0 features (S7D, 24-32 months x
// 9 nodes) or never returned at all (S7E/S7F, 36 months), so each is now
// CHUNKED at 12 months per call and the budget is
//   1 pre-check + 1 GEBCO search + 1 NDVI + ceil(span/12) x 9-node calls
//   + ceil(span/12) x 2-site calls
// which is 9 for the 24+12 windows in the live runs (a 31-month span -> 3 + 3),
// 7 whenever the span is 24 months or less, and 19 at the 95-month widest span
// the span gate accepts. Still
// bounded, still the same proven functions - not a new, riskier
// reimplementation.
// ============================================================
panel.add(sHead('S7F - RUN ALL: S7D + S7E COMBINED (v10.116)','#1a3a5a'));
panel.add(lbl('Runs S7D (within-reef coupling) and S7E (local vs regional) together from ONE shared Lat/Lon + BEFORE/AFTER input, tabulating both verdicts side by side. Does NOT try multiple window lengths automatically - see the note below for why.',7,'#224466'));
panel.add(lbl('SCOPE: still just ONE window length per run, chosen by you (the same window-tuning process from S7D/S7E still applies - this only removes re-typing coordinates/dates twice). Does not include S7B/S7C/S13. v10.167 call budget: 1 pre-check + 1 GEBCO reference search + 1 NDVI check + ceil(span/12) chunked 9-node series calls + ceil(span/12) chunked 2-site series calls, where span is the calendar months the two windows jointly cover - 9 calls for the 24+12 windows in the live runs (a 31-month span), 7 whenever the span is 24 months or less, 19 at the 95-month maximum. v10.162 sent 4 unchunked calls and v10.116-v10.161 sent 6; the unchunked ones are the calls that returned 0 features or never returned in live runs, so the higher count here buys a fetch that can actually complete AND a deadline that refuses instead of hanging.',7,'#886600'));
panel.add(lbl('Lat, Lon:',7,'#334466'));
var s7fCoordInput = ui.Textbox({placeholder:'lat, lon  e.g. -23.51, 152.09',style:{stretch:'horizontal',margin:'2px 4px',fontSize:'11px'}});
panel.add(s7fCoordInput);
var s7fUseLastClickBtn = ui.Button({
  label:'Use last clicked location (from map above)',
  style:{fontSize:'9px',margin:'2px 4px',backgroundColor:'#e8f4ff',color:'#225588',stretch:'horizontal',padding:'4px 4px',border:'1px solid #4488cc'},
  onClick:function(){
    if(lastClickLat===null||lastClickLon===null){
      s7fStatusV.setValue('No location clicked yet - click the map or use GO TO COORDINATES first.');
      s7fStatusV.style().set('color','#aa3300'); return;
    }
    s7fCoordInput.setValue(lastClickLat.toFixed(4)+', '+lastClickLon.toFixed(4));
    s7fStatusV.setValue('Location filled in. Fill in radius + BEFORE/AFTER, then press RUN.');
    s7fStatusV.style().set('color','#115511');
  }
});
panel.add(s7fUseLastClickBtn);
panel.add(lbl('Ring radius (km, 0.3-3, for S7D within-reef nodes):',7,'#334466'));
var s7fRadiusInput = ui.Textbox({placeholder:'e.g. 0.5',value:'0.5',style:{stretch:'horizontal',margin:'2px 4px',fontSize:'11px'}});
panel.add(s7fRadiusInput);
panel.add(lbl('BEFORE start date + months:',7,'#115511'));
var s7fBeforeStartInput = ui.Textbox({placeholder:'e.g. 2021-06-01',style:{stretch:'horizontal',margin:'2px 4px',fontSize:'11px'}});
panel.add(s7fBeforeStartInput);
// v10.160 S5 FIX: default BEFORE raised 12 -> 24, so the shipped default is
// 24+12 (36 pooled months) rather than 12+12 (24). 12+12 was bad in three
// measured ways: (1) its false-positive rate was gap-dependent and
// conservative - 1.1-4.1% at a fixed 0-month BEFORE/AFTER gap, 3.9-4.7% at a
// random 0-3 month gap, against a nominal 5%; (2) power against a REAL x5
// rise in the AFTER window's noise was 21.7-24.8% at gap 0; and (3) it pooled
// exactly CLIM_MIN_TOTAL_SAMPLES months, which counts VALID months, so on
// cloud-masked Sentinel-2 FAI - the module this serves - a single masked
// month refused the whole test. Measured emission rate of the p-value at
// 0 / 10 / 20 / 25% uniform per-month masking, 3000 draws per cell:
//   12+12, v10.160 floor of 26     0 / 0 / 0 / 0%   - pools 24, below the floor
//   12+12, v10.159 floor of 24   100 / 8.7 / 0.3 / 0.1%
//   18+12, v10.160 floor of 26   100 / 83.5 / 25.9 / 8.8%
//   24+12, v10.160 floor of 26   100 / 100 / 91.6 / 74.1%   <- new default
// and with seasonally-CLUSTERED masking (Nov-Mar dropped at 3x the base rate,
// the rest at 0.2x) at a 15% base rate, under the v10.160 floor: 93.1% at 24+12
// against 21.8% at 18+12.
var s7fBeforeMonthsInput = ui.Textbox({placeholder:'months, e.g. 24',value:'24',style:{stretch:'horizontal',margin:'2px 4px',fontSize:'11px'}});
panel.add(s7fBeforeMonthsInput);
panel.add(lbl('AFTER start date + months:',7,'#aa3300'));
var s7fAfterStartInput = ui.Textbox({placeholder:'e.g. 2023-11-01',style:{stretch:'horizontal',margin:'2px 4px',fontSize:'11px'}});
panel.add(s7fAfterStartInput);
// v10.159 W-01 item 4 raised the AFTER default 10 -> 12. v10.160 S5 leaves AFTER
// at 12 and raises BEFORE 12 -> 24; see the BEFORE box above for the measurements.
// The v10.159 claim quoted here - "12+12 ... variance-ratio false-positive rate
// 4.3-6.9% across every seasonal shape tested" - did not reproduce and is
// withdrawn: re-measured at 12+12 the rate is 1.1-4.1% at a fixed 0-month gap and
// 3.9-4.7% at a random 0-3 month gap, i.e. CONSERVATIVE and strongly
// gap-dependent, with power against a real 5x variance change of only 21.7-24.8%
// at gap 0. 12+12 pooled 24 months, which is below the v10.160 floor of 26, so it
// no longer produces a p-value at all.
var s7fAfterMonthsInput = ui.Textbox({placeholder:'months, e.g. 12',value:'12',style:{stretch:'horizontal',margin:'2px 4px',fontSize:'11px'}});
panel.add(s7fAfterMonthsInput);
var s7fStatusV = ui.Label('Fill in the fields above, then press RUN. 4 batched calls total (v10.162: was 6 - the separate BEFORE fetches are gone), expect ~30-90 seconds.',
  {fontSize:'11px',fontWeight:'bold',color:'#555555',backgroundColor:'#eeeeee',padding:'6px 8px',margin:'2px 0',whiteSpace:'pre',border:'2px solid #aaaaaa'});
var s7fResultV = ui.Label('',{fontSize:'8px',color:'#1a2a4a',backgroundColor:'#eef2fa',padding:'4px 6px',margin:'2px 0',whiteSpace:'pre'});
var s7fRunSeq = 0;   // v10.161 S6a
var s7fRunBtn = ui.Button({
  label:'RUN ALL (S7D + S7E COMBINED)',
  style:{fontSize:'11px',fontWeight:'bold',margin:'2px 4px',backgroundColor:'#cfe0f5',color:'#1a3a5a',stretch:'horizontal',padding:'6px 4px',border:'2px solid #1a3a5a'},
  onClick:function(){
    var coordTxt=(s7fCoordInput.getValue()||'').trim();
    var radiusTxt=(s7fRadiusInput.getValue()||'').trim();
    var beforeStartTxt=(s7fBeforeStartInput.getValue()||'').trim();
    var beforeMonthsTxt=(s7fBeforeMonthsInput.getValue()||'').trim();
    var afterStartTxt=(s7fAfterStartInput.getValue()||'').trim();
    var afterMonthsTxt=(s7fAfterMonthsInput.getValue()||'').trim();
    if(!coordTxt||!beforeStartTxt||!beforeMonthsTxt||!afterStartTxt||!afterMonthsTxt){
      s7fStatusV.setValue('MISSING - fill in Lat/Lon and both BEFORE/AFTER date+months fields.');
      s7fStatusV.style().set('color','#cc0000'); s7fStatusV.style().set('backgroundColor','#ffd0d0'); return;
    }
    var rawParts=coordTxt.split(',');
    if(rawParts.length!==2){s7fStatusV.setValue('Invalid format - use: lat, lon'); s7fStatusV.style().set('color','#cc0000'); return;}
    var latIn=parseCoordPart(rawParts[0]), lonIn=parseCoordPart(rawParts[1]);
    if(isNaN(latIn)||isNaN(lonIn)){s7fStatusV.setValue('Invalid format - use: lat, lon'); s7fStatusV.style().set('color','#cc0000'); return;}
    var radiusKm=parseFloat(radiusTxt);
    if(isNaN(radiusKm)||radiusKm<0.3||radiusKm>3){s7fStatusV.setValue('Ring radius must be 0.3-3 km.'); s7fStatusV.style().set('color','#cc0000'); return;}
    var beforeMonths=parseInt(beforeMonthsTxt,10), afterMonths=parseInt(afterMonthsTxt,10);
    // v10.159 W-01 item 4 set a floor of 12 months per box and claimed "the
    // pooled record is always >= CLIM_MIN_TOTAL_SAMPLES and the shipped defaults
    // always produce a properly deseasonalized, calibrated p-value". v10.160 S5:
    // that sentence was false on BOTH halves and is replaced rather than edited.
    //  - "always >= CLIM_MIN_TOTAL_SAMPLES": that floor counts VALID months, and
    //    12+12 sat exactly on it, so one masked month refused the whole test.
    //    Sentinel-2 FAI is cloud-masked. Measured p-value emission at 12+12 under
    //    the v10.159 floor of 24: 100% unmasked, 8.7% at 10% per-month masking,
    //    0.3% at 20%, 0.1% at 25%, and 0.0% at 25% seasonally-clustered
    //    (3000 draws/cell).
    //  - "calibrated": at 12+12 the measured variance-ratio false-positive rate
    //    was 1.1-4.1% at a fixed 0-month gap and 3.9-4.7% at a random 0-3 month
    //    gap, i.e. gap-dependent and conservative, with 21.7-24.8% power at gap 0.
    // FIXED by raising the DEFAULTS (see the month boxes above) and by checking
    // the POOLED total here, not just the per-box minimum. The per-box floor of
    // 12 stays - below one full annual cycle per window there is nothing to
    // estimate a seasonal cycle from - and the pooled total must now clear
    // CLIM_MIN_TOTAL_SAMPLES before the run starts, instead of the test
    // discovering it later and reporting NOT TESTABLE. Note what this check
    // CANNOT do: it counts NOMINAL months, and the floor counts VALID ones, so a
    // heavily masked record can still fall under it. That is why the defaults now
    // sit 10 months clear of the floor rather than on it.
    if(isNaN(beforeMonths)||beforeMonths<12||beforeMonths>36||isNaN(afterMonths)||afterMonths<12||afterMonths>36){
      s7fStatusV.setValue('BEFORE/AFTER months must each be 12-36 (v10.159: raised from 4 - below one full annual cycle per window there is nothing to estimate the seasonal cycle from).');
      s7fStatusV.style().set('color','#cc0000'); return;
    }
    // v10.160 S5: the POOLED total is what the climatology floor is applied to.
    if((beforeMonths+afterMonths) < CLIM_MIN_TOTAL_SAMPLES){
      s7fStatusV.setValue('BEFORE + AFTER must total at least '+CLIM_MIN_TOTAL_SAMPLES+' months (you asked for '+(beforeMonths+afterMonths)+'). '+
        'Below that the seasonal cycle cannot be estimated well enough to remove, and no p-value is reported. MEASURED at a 24-month pooled record '+
        '(seasonal amplitude 3, noise SD 1, 3000 draws): a real five-fold rise in the AFTER window noise is detected only 21.7-24.8% of the time at a '+
        '0-month BEFORE/AFTER gap. Note this check counts NOMINAL months; the floor counts VALID ones, so on a cloud-masked record leave real slack - '+
        'the shipped default of 24+12 sits 10 months clear of the floor.');
      s7fStatusV.style().set('color','#cc0000'); return;
    }
    // v10.162 S1: combined-span cap, checked before any EE call is spent.
    var _s7fSpanPre = combinedWindowSpan(beforeStartTxt, beforeMonths, afterStartTxt, afterMonths);
    var _s7fSpanRefusal = combinedSpanRefusal(_s7fSpanPre, beforeMonths, afterMonths);
    if(_s7fSpanRefusal){ s7fStatusV.setValue(_s7fSpanRefusal); s7fStatusV.style().set('color','#cc0000');
      s7fStatusV.style().set('backgroundColor','#ffd0d0'); s7fStatusV.style().set('whiteSpace','pre'); return; }
    s7fRunSeq++; var s7fMyRun=s7fRunSeq;   // v10.161 S6a
    recordStudySite(latIn, lonIn, 'S7F');

    // v10.161 S4: cheap FAI data-density gate BEFORE the call budget
    // (v10.162 S1: 4 calls, down from 6; v10.167 FIX 20: chunked, so the budget
    // is now 3 fixed calls + 2 x ceil(span/12) series calls - 9 at a 31-month span).
    faiPrecheckThenRun({lat:latIn, lon:lonIn, moduleName:'S7F', statusLbl:s7fStatusV, resultLbl:s7fResultV,
      windows:[{name:'BEFORE',start:beforeStartTxt,months:beforeMonths},
               {name:'AFTER', start:afterStartTxt, months:afterMonths}],
      cannotRunTxt:'S7C-S7F cannot run here.'}, function(_pre){

    function destinationPoint(lat, lon, bearingDeg, distKm){
      var R=6371, brng=bearingDeg*Math.PI/180, lat1=lat*Math.PI/180, lon1=lon*Math.PI/180;
      var lat2=Math.asin(Math.sin(lat1)*Math.cos(distKm/R)+Math.cos(lat1)*Math.sin(distKm/R)*Math.cos(brng));
      var lon2=lon1+Math.atan2(Math.sin(brng)*Math.sin(distKm/R)*Math.cos(lat1),Math.cos(distKm/R)-Math.sin(lat1)*Math.sin(lat2));
      return {lat:lat2*180/Math.PI, lon:lon2*180/Math.PI};
    }
    var bearings8=[{b:0,label:'N'},{b:45,label:'NE'},{b:90,label:'E'},{b:135,label:'SE'},
      {b:180,label:'S'},{b:225,label:'SW'},{b:270,label:'W'},{b:315,label:'NW'}];
    var nodes=[{label:'Center',lat:latIn,lon:lonIn}];
    bearings8.forEach(function(br){
      var d=destinationPoint(latIn,lonIn,br.b,radiusKm);
      nodes.push({label:br.label,lat:d.lat,lon:d.lon});
    });
    nodes.forEach(function(nd){ nd.buf=ee.Geometry.Point([nd.lon,nd.lat]).buffer(150); });

    var ptsFC = ee.FeatureCollection(nodes.map(function(nd,idx){
      return ee.Feature(nd.buf, {label:nd.label, idx:idx});
    }));
    // v10.162 S1: ONE combined BEFORE..AFTER collection, shared by the S7D
    // 9-node fetch and the S7E study/reference fetch below.
    var _s7fSpan = combinedWindowSpan(beforeStartTxt, beforeMonths, afterStartTxt, afterMonths);
    // v10.167 FIX 20 / S1 + S2: both of S7F's series fetches are chunked and
    // deadline-guarded, exactly as S7D's and S7E's now are. S7F is where the
    // 36-month hang was first seen, and it is the module with the most calls in
    // flight, so it is the one that most needed a failure path that ends.
    var _s7fGrid = s7FaiGridSpan(beforeStartTxt, beforeMonths, afterStartTxt, afterMonths);
    var _s7fDCalls = s7FaiCallCount(_s7fGrid.startDateStr, _s7fGrid.nMonths, nodes.length);
    var _s7fERegions = 2;
    var _s7fECalls = s7FaiCallCount(_s7fGrid.startDateStr, _s7fGrid.nMonths, _s7fERegions);
    var _s7fTotalCalls = _s7fDCalls + 1 /*NDVI*/ + 1 /*GEBCO search*/ + _s7fECalls;
    var ndviWaterMaskedF=ndviWater.updateMask(oceanMask).rename('ndviW');
    var ndviBufMF = Math.max(80, Math.min(250, radiusKm*1000*0.3));
    var ptsFCForNdviF = ee.FeatureCollection(nodes.map(function(nd,idx){
      return ee.Feature(ee.Geometry.Point([nd.lon,nd.lat]).buffer(ndviBufMF), {label:nd.label, idx:idx});
    }));

    // S7D's calls - the series is now _s7fDCalls chunked call(s) (v10.167), plus NDVI.
    var rD_ndvi = ndviWaterMaskedF.reduceRegions({collection:ptsFCForNdviF, reducer:ee.Reducer.max(), scale:20});

    // S7E's candidate search (1 call, must resolve before its other 2)
    var searchRadiiKmF=[20,40,70,110,160];
    var candidatesF=[];
    searchRadiiKmF.forEach(function(rKm){
      for(var b=0;b<360;b+=45){
        var d=destinationPoint(latIn,lonIn,b,rKm);
        candidatesF.push({lat:d.lat,lon:d.lon,radiusKm:rKm,bearing:b});
      }
    });
    var candFeatsF = candidatesF.map(function(c,idx){
      return ee.Feature(ee.Geometry.Point([c.lon,c.lat]), {idx:idx, radiusKm:c.radiusKm});
    });
    var candFCF = ee.FeatureCollection(candFeatsF);
    var rCandidatesF = GEBCO.reduceRegions({collection:candFCF, reducer:ee.Reducer.first(), scale:500});

    s7fStatusV.setValue('Running: the S7D series as '+_s7fDCalls+' chunked call(s) over '+_s7fGrid.nMonths+
      ' months x '+nodes.length+' nodes, alongside the NDVI check and the reference search,\n'+
      'then '+_s7fECalls+' more chunked call(s) once the reference is found - '+_s7fTotalCalls+' EE calls in total '+
      '(v10.162 sent 4, unchunked; both of its series fetches are the shape that returned 0 features or never\n'+
      'returned in live runs). The two windows are still sliced out of the merged series client-side by real\n'+
      'timestamp. Expect roughly '+((_s7fDCalls+_s7fECalls)*30)+'-'+((_s7fDCalls+_s7fECalls)*60)+' seconds.\n'+
      S7_DEADLINE_NOTE);
    s7fStatusV.style().set('color','#334466'); s7fStatusV.style().set('backgroundColor','#eeeeee');
    s7fStatusV.style().set('border','2px solid #aaaaaa'); s7fStatusV.style().set('whiteSpace','pre');
    s7fResultV.setValue('');

    var s7fData={}, s7fPending=3, s7fErrors=0, s7fDead=false;
    // v10.162 S1: three first-stage call GROUPS, not four. v10.167: the first of
    // them is _s7fDCalls chunked calls run in sequence, not one. The v10.161 S6a
    // run-sequence guard and stall-explaining progress text are unchanged.
    var s7fWaiting=['S7D combined BEFORE..AFTER series ('+_s7fDCalls+' chunked call(s))','S7D NDVI check','reference-site GEBCO search'];
    var s7fCallName={dCombined:'S7D combined BEFORE..AFTER series ('+_s7fDCalls+' chunked call(s))',
                     dNdvi:'S7D NDVI check', candidates:'reference-site GEBCO search'};
    function s7fBump(key,v,e){
      if(s7fMyRun!==s7fRunSeq || s7fDead) return;   // v10.161 S6a
      s7fData[key]=e?null:v;
      if(e) s7fErrors++;
      s7fPending--;
      var _wait=s7Outstanding(s7fWaiting, s7fCallName[key]||key);
      s7fStatusV.setValue('Running: '+(3-s7fPending)+' / 3 first-stage call groups done'+(s7fErrors>0?' ('+s7fErrors+' errored)':'')+'...\n'+_wait+
        (s7fPending>0?('\n'+S7_STALL_HINT):''));
      if(s7fPending===0) s7fStage2();
    }
    // v10.167 FIX 20 / S2: S7F refuses like S7D and S7E. Two entry points -
    // stage 1 (the 9-node series) kills the whole run; stage 2 (the study/
    // reference series) falls back to the S7D-only summary, which is a real
    // partial result rather than a blank panel.
    function s7fRefuseChunks(res, which, nRegions, fallbackD){
      if(s7fMyRun!==s7fRunSeq || s7fDead) return;
      var txt=s7ChunkRefusalText('S7F ('+which+')', res, nRegions);
      if(fallbackD){
        s7fStatusV.setValue('S7E half REFUSED - S7D results are shown below.\n'+txt);
        s7fStatusV.style().set('color','#886600'); s7fStatusV.style().set('backgroundColor','#fff6cc');
        s7fStatusV.style().set('border','2px solid #886600'); s7fStatusV.style().set('whiteSpace','pre');
        print('=== S7F REFUSED (v10.167 chunked fetch, '+which+': '+res.reason+') === '+(res.detail||''));
        s7fFinishD_only('REFUSED - the study/reference series fetch did not complete ('+res.reason+
          '). The reference reef WAS found; it is the FAI fetch at it that failed. See the status box above.');
        return;
      }
      s7fDead=true;
      s7fStatusV.setValue(txt);
      s7fStatusV.style().set('color','#cc0000'); s7fStatusV.style().set('backgroundColor','#ffd0d0');
      s7fStatusV.style().set('border','2px solid #cc0000'); s7fStatusV.style().set('whiteSpace','pre');
      s7fStatusV.style().set('fontWeight','bold');
      s7fResultV.setValue('Chunk plan was '+_s7fDCalls+' call(s) over '+_s7fGrid.nMonths+' month(s) x '+
        nodes.length+' nodes, starting '+_s7fGrid.startDateStr+'.'+(_pre&&_pre.note?'\n'+_pre.note:''));
      print('=== S7F REFUSED (v10.167 chunked fetch, '+which+': '+res.reason+') === '+(res.detail||''));
    }
    function s7fStage2(){
      if(s7fMyRun!==s7fRunSeq) return;   // v10.161 S6a
      try {
        var candResult = s7fData.candidates;
        var feats = (candResult&&candResult.features)?candResult.features:[];
        var best=null, excludedCount=0, shallowCount=0;
        var EXCL_KM=5;
        for(var i=0;i<feats.length;i++){
          var p=feats[i].properties;
          var elev=extractReduceRegionsValue(p,'elevation');
          if(elev!==null && elev>-50 && elev<0){
            shallowCount++;
            var cLat=candidatesF[p.idx].lat, cLon=candidatesF[p.idx].lon;
            var tooClose=false;
            for(var h=0;h<s7StudySiteHistory.length;h++){
              if(haversineKm(cLat,cLon,s7StudySiteHistory[h].lat,s7StudySiteHistory[h].lon) < EXCL_KM){ tooClose=true; break; }
            }
            if(tooClose){ excludedCount++; continue; }
            if(!best || p.radiusKm<best.radiusKm) best={radiusKm:p.radiusKm, elev:elev, lat:cLat, lon:cLon};
          }
        }
        if(!best){
          s7fStatusV.setValue('S7D data is ready, but NO REFERENCE REEF FOUND within 160km for S7E'+
            (shallowCount>0&&excludedCount===shallowCount?' (all '+shallowCount+' shallow candidates coincide with prior study sites)':'')+
            ' - showing S7D results only below.');
          s7fStatusV.style().set('color','#886600'); s7fStatusV.style().set('backgroundColor','#fff6cc');
          s7fFinishD_only();
          return;
        }
        s7fData.refSite = best;
        var studyPtBufF=ee.Geometry.Point([lonIn,latIn]).buffer(150);
        var refPtBufF=ee.Geometry.Point([best.lon,best.lat]).buffer(150);
        var pairFCF=ee.FeatureCollection([
          ee.Feature(studyPtBufF,{label:'Study'}), ee.Feature(refPtBufF,{label:'Reference'})
        ]);
        var s7fPending2=1;
        var s7fWaiting2=['S7E study/reference combined BEFORE..AFTER series ('+_s7fECalls+' chunked call(s))'];
        var s7fCallName2={eCombined:'S7E study/reference combined BEFORE..AFTER series ('+_s7fECalls+' chunked call(s))'};
        function s7fBump2(key,v,e){
          if(s7fMyRun!==s7fRunSeq || s7fDead) return;   // v10.161 S6a
          s7fData[key]=e?null:v; if(e) s7fErrors++;
          s7fPending2--;
          var _wait2=s7Outstanding(s7fWaiting2, s7fCallName2[key]||key);
          s7fStatusV.setValue('Running: second-stage '+(1-s7fPending2)+' / 1 call group done...\n'+_wait2+
            (s7fPending2>0?('\n'+S7_STALL_HINT):''));
          if(s7fPending2===0) s7fFinishAll(excludedCount);
        }
        fetchFaiSeriesChunked({
          gridStartStr:_s7fGrid.startDateStr, nMonths:_s7fGrid.nMonths, ptsFC:pairFCF,
          nRegions:_s7fERegions, band:'fai', scale:20, tag:'S7F-E',
          isCurrent:function(){ return s7fMyRun===s7fRunSeq && !s7fDead; },
          onProgress:function(i,total,ch){
            if(s7fMyRun!==s7fRunSeq || s7fDead) return;
            s7fStatusV.setValue('Running: second-stage series chunk '+(i+1)+' / '+total+' ('+
              ch.start.substring(0,7)+' + '+ch.months+' months x '+_s7fERegions+' sites).\n'+
              S7_STALL_HINT+'\n'+S7_DEADLINE_NOTE);
          }
        }, function(res){
          if(!res.ok){ s7fRefuseChunks(res, 'S7E study/reference series', _s7fERegions, true); return; }
          s7fBump2('eCombined', res.fc, null);
        });
      } catch(errStage2){
        s7fStatusV.setValue(friendlyEEError(errStage2));
        s7fStatusV.style().set('color','#cc0000'); s7fStatusV.style().set('backgroundColor','#ffd0d0');
        print('=== S7F STAGE 2 ERROR === '+errStage2);
      }
    }
    function fmtNF(v,d){ return (v!==null&&v!==undefined&&!isNaN(v))?v.toFixed(d):'n/a'; }
    function buildS7DSummary(){
      // v10.162 S1: one combined series, sliced by real timestamp.
      var combinedByNode = groupSeriesByLabel(s7fData.dCombined, 'fai');
      var beforeByNode = sliceSeriesMapByWindow(combinedByNode, beforeStartTxt, beforeMonths);
      var afterByNode = sliceSeriesMapByWindow(combinedByNode, afterStartTxt, afterMonths);
      var ndviByLabel = {};
      if(s7fData.dNdvi && s7fData.dNdvi.features){
        s7fData.dNdvi.features.forEach(function(f){
          var p=f.properties||{}; ndviByLabel[p.label]=extractReduceRegionsValue(p,'ndviW');
        });
      }
      var nOnReefRisingCorr=0, nOnReefTotal=0, nAc1Rising=0, nAc1Avail=0;
      // v10.159 W-02: jsNodeStatsFixed's climatologySource / climatologyNote /
      // ac1Pairs* were computed here and thrown away. Collected and returned.
      var s7fDDisc=[];
      var centerBeforeVals=(beforeByNode['Center']||[]), centerAfterVals=(afterByNode['Center']||[]);
      for(var idx=0;idx<nodes.length;idx++){
        var nd=nodes[idx];
        // v10.160 S6: pooled climatology per node, shared across its two windows.
        var _fdClim=pooledClimFor(beforeByNode[nd.label]||[], afterByNode[nd.label]||[]);
        var stB=jsNodeStatsFixed(beforeByNode[nd.label]||[], _fdClim);
        var stA=jsNodeStatsFixed(afterByNode[nd.label]||[], _fdClim);
        s7fDDisc.push({label:nd.label+' BEFORE',st:stB});
        s7fDDisc.push({label:nd.label+' AFTER',st:stA});
        var ndviV=(ndviByLabel[nd.label]!==undefined)?ndviByLabel[nd.label]:null;
        var onReef = ndviV!==null?(ndviV>-0.10):null;
        var dAC1=(stB.realAC1!==null&&stA.realAC1!==null)?(stA.realAC1-stB.realAC1):null;
        if(dAC1!==null){ nAc1Avail++; if(dAC1>0.01) nAc1Rising++; }
        if(idx>0 && onReef===true){
          var pcB=jsPairCorrelation(centerBeforeVals, beforeByNode[nd.label]);
          var pcA=jsPairCorrelation(centerAfterVals, afterByNode[nd.label]);
          nOnReefTotal++;
          if(pcB.corr!==null&&pcA.corr!==null&&(pcA.corr-pcB.corr)>0.10) nOnReefRisingCorr++;
        }
      }
      var headline;
      if(nOnReefTotal===0) headline='S7D: could not assess (no on-reef ring points)';
      else if(nOnReefRisingCorr>=Math.ceil(nOnReefTotal*0.5)) headline='S7D: HYPER-SYNCHRONIZATION ('+nOnReefRisingCorr+'/'+nOnReefTotal+' on-reef rising)';
      else if(nOnReefRisingCorr>0) headline='S7D: PARTIAL SIGNAL ('+nOnReefRisingCorr+'/'+nOnReefTotal+' on-reef rising)';
      else headline='S7D: NO SYNCHRONIZATION SIGNAL (0/'+nOnReefTotal+' on-reef rising)';
      return {headline:headline, nAc1Rising:nAc1Rising, nAc1Avail:nAc1Avail,
              disclosureLines:nodeStatsDisclosureLines(s7fDDisc)};
    }
    // v10.167 FIX 20 / S2: eNote says WHY the S7E half is missing. It used to
    // hardcode "no usable reference site found", which was the only way this
    // path could be reached before; a refused study/reference fetch now reaches
    // it too, and saying the reference was not found there would be false.
    function s7fFinishD_only(eNote){
      if(s7fMyRun!==s7fRunSeq) return;   // v10.161 S6a
      try {
        var dSum = buildS7DSummary();
        var lines=['=== COMBINED SUMMARY ==='];
        // v10.161 S6b: was 'AC1 rising at '+nAc1Rising+'/'+nAc1Avail+' nodes', which
        // rendered as "0/0 nodes" at a cloud-limited site. See countOfTotal().
        lines.push(dSum.headline+' | AC1 rising at '+
          countOfTotal(dSum.nAc1Rising, dSum.nAc1Avail, 'nodes',
            'AC1: no node had a computable \u0394AC1 in BOTH windows, so no node was tested'));
        lines.push('S7E: '+(eNote||'not run this time (no usable reference site found)'));
        if(dSum.disclosureLines.length>0){
          lines.push('SERIES QUALITY (v10.159 W-02):');
          dSum.disclosureLines.forEach(function(d){ lines.push(d); });
        }
        lines.push(repeatChar('\u2500',50));
        lines.push('BEFORE: '+beforeStartTxt+' + '+beforeMonths+'mo | AFTER: '+afterStartTxt+' + '+afterMonths+'mo | radius='+radiusKm+'km');
        if(_pre && _pre.note) lines.push(_pre.note);   // v10.161 S4
        s7fResultV.setValue(lines.join('\n'));
        print('=== S7F COMBINED (S7D only) ==='); print(lines.join('\n'));
      } catch(eF){ print('=== S7F D-only finish error === '+eF); }
    }
    function s7fFinishAll(excludedCount){
      if(s7fMyRun!==s7fRunSeq) return;   // v10.161 S6a
      try {
        var dSum = buildS7DSummary();
        // v10.162 S1: one combined series, sliced by real timestamp.
        var eCombinedByNode = groupSeriesByLabel(s7fData.eCombined, 'fai');
        var eBeforeByNode = sliceSeriesMapByWindow(eCombinedByNode, beforeStartTxt, beforeMonths);
        var eAfterByNode = sliceSeriesMapByWindow(eCombinedByNode, afterStartTxt, afterMonths);
        // Refuse with the existing insufficient-data wording if the combined
        // series does not cover both windows at the study site.
        var _s7fShort = combinedSliceShortfall(eBeforeByNode['Study']||[], eAfterByNode['Study']||[], 4);
        if(_s7fShort){
          s7fStatusV.setValue('S7E: CANNOT CLASSIFY (insufficient data in at least one period)\n'+_s7fShort);
          s7fStatusV.style().set('color','#cc0000'); s7fStatusV.style().set('backgroundColor','#ffd0d0');
          s7fStatusV.style().set('border','2px solid #cc0000'); s7fStatusV.style().set('whiteSpace','pre');
          print('=== S7F REFUSED (v10.162 S1 combined-slice shortfall) === '+_s7fShort);
          s7fFinishD_only();
          return;
        }
        // v10.160 S6: pooled climatology per site, shared across its two windows.
        var _feStudyClim=pooledClimFor(eBeforeByNode['Study']||[], eAfterByNode['Study']||[]);
        var _feRefClim  =pooledClimFor(eBeforeByNode['Reference']||[], eAfterByNode['Reference']||[]);
        var studyB=jsNodeStatsFixed(eBeforeByNode['Study']||[], _feStudyClim);
        var studyA=jsNodeStatsFixed(eAfterByNode['Study']||[], _feStudyClim);
        var refB=jsNodeStatsFixed(eBeforeByNode['Reference']||[], _feRefClim);
        var refA=jsNodeStatsFixed(eAfterByNode['Reference']||[], _feRefClim);
        var dAC1_study=(studyB.realAC1!==null&&studyA.realAC1!==null)?(studyA.realAC1-studyB.realAC1):null;
        var dVar_study=(studyB.varTrendRatio!==null&&studyA.varTrendRatio!==null)?(studyA.varTrendRatio-studyB.varTrendRatio):null;
        var dAC1_ref=(refB.realAC1!==null&&refA.realAC1!==null)?(refA.realAC1-refB.realAC1):null;
        var dVar_ref=(refB.varTrendRatio!==null&&refA.varTrendRatio!==null)?(refA.varTrendRatio-refB.varTrendRatio):null;
        var refInsufficient=(refB.nValidMonths<4||refA.nValidMonths<4);
        var studyInsufficient=(studyB.nValidMonths<4||studyA.nValidMonths<4);
        // v10.154 FIX 11: S7F now runs the real permutation test too, using
        // the raw series it has already fetched (eBeforeByNode/eAfterByNode).
        // Zero new EE calls. The calibrated cutoffs below are kept only as a
        // direction check; the p-values decide.
        var _s7fAc1=Math.max(getCalibratedThresholds(beforeMonths).ac1, getCalibratedThresholds(afterMonths).ac1);
        var _s7fVar=Math.max(getCalibratedThresholds(beforeMonths).varr, getCalibratedThresholds(afterMonths).varr);
        var sAC1T=permutationTestDeltaFixed(eBeforeByNode['Study']||[], eAfterByNode['Study']||[], statAC1ForPerm, 500);
        var sVarT=permutationTestDeltaFixed(eBeforeByNode['Study']||[], eAfterByNode['Study']||[], statVarRatioForPerm, 500);
        var rAC1T=permutationTestDeltaFixed(eBeforeByNode['Reference']||[], eAfterByNode['Reference']||[], statAC1ForPerm, 500);
        var rVarT=permutationTestDeltaFixed(eBeforeByNode['Reference']||[], eAfterByNode['Reference']||[], statVarRatioForPerm, 500);
        // v10.159 W-01 item 2: permUsable() replaces the bare pValue!==null test.
        // v10.160 BLOCKER 4 FIX (REGRESSION THIS SERIES INTRODUCED). This used to
        // take `d` - the DISPLAYED delta from jsNodeStatsFixed - as the direction,
        // while t.pValue came from permutationTestDeltaFixed. In v10.158 both
        // sides were RAW so they agreed. v10.159 deseasonalized the TEST and left
        // the DISPLAY raw, so a two-sided p-value earned by a significant FALL in
        // deseasonalized AC1 could be paired with a RAW rise and reported as a
        // rising signal. MEASURED against the shipped functions in Node - seasonal
        // amplitude 3 smooth sine, noise SD 1, gap 0, nPerm=300, 1500 draws per
        // cell - the displayed delta and the tested delta disagree in SIGN on:
        //   18+12  unmasked 38.3%   10% masked 40.4%
        //   24+24  unmasked 35.2%   10% masked 41.0%
        //   36+12  unmasked 63.4%
        // and among only the runs that actually reached p<0.05, on 7.4% at 24+24
        // (n=76 such runs) and 75.0% at 36+12 (n=76). Worst single case seen:
        // displayed dAC1 -0.5729 against a tested delta of +0.7090. The two
        // effects compound - S6 below makes the displayed number the same
        // quantity as the tested one, and this makes the DECISION read the tested
        // one regardless. The direction now comes
        // from the same object as the p-value - observedDelta is exactly the
        // statistic the null was built around - so the two cannot disagree.
        // The `d` argument is kept only so the caller's displayed delta is still
        // required to EXIST; it no longer decides the direction.
        function _sig(t, d){ return permUsable(t) && t.pValue<0.05 &&
          t.observedDelta!==null && t.observedDelta!==undefined && t.observedDelta>0; }
        // signal now requires SIGNIFICANCE AND a rising direction
        var studySignal=_sig(sAC1T, dAC1_study)||_sig(sVarT, dVar_study);
        var refSignal=_sig(rAC1T, dAC1_ref)||_sig(rVarT, dVar_ref);
        // direction-only read, kept for comparison against the old behaviour
        var studyDirOnly=(dAC1_study!==null&&dAC1_study>_s7fAc1)||(dVar_study!==null&&dVar_study>_s7fVar);
        var eHeadline;
        if(refInsufficient||studyInsufficient) eHeadline='S7E: CANNOT CLASSIFY (insufficient data in at least one period)';
        else if(studySignal&&!refSignal) eHeadline='S7E: LOCAL ANOMALY DETECTED';
        else if(studySignal&&refSignal) eHeadline='S7E: REGIONAL SIGNAL';
        else if(!studySignal&&refSignal) eHeadline='S7E: ANOMALOUS (reference changed, study did not)';
        else eHeadline='S7E: NO SIGNAL AT EITHER SITE';

        // v10.117 FIX: data density was already computed here (needed for
        // the CANNOT CLASSIFY check above) but never actually displayed -
        // S7D and S7E each show it in their own individual output, S7F's
        // combined summary silently dropped it. Caught directly: a user
        // asked to see S7F's density numbers and there were none to show.
        var studyDataDensityF = (studyB.nValidMonths+studyA.nValidMonths)/(beforeMonths+afterMonths);
        var refDataDensityF = (refB.nValidMonths+refA.nValidMonths)/(beforeMonths+afterMonths);

        var lines=['=== COMBINED SUMMARY ==='];
        // v10.161 S6b: see countOfTotal() - this is the exact line that printed
        // "AC1 rising at 0/0 nodes" in the live Bocas del Toro run.
        lines.push(dSum.headline+' | AC1 rising at '+
          countOfTotal(dSum.nAc1Rising, dSum.nAc1Avail, 'nodes',
            'AC1: no node had a computable \u0394AC1 in BOTH windows, so no node was tested'));
        lines.push(eHeadline+' | Study \u0394AC1='+fmtNF(dAC1_study,3)+' | Reference \u0394AC1='+fmtNF(dAC1_ref,3));
        lines.push('Study data density: '+Math.round(studyDataDensityF*100)+'% ('+studyB.nValidMonths+'/'+beforeMonths+' BEFORE, '+
          studyA.nValidMonths+'/'+afterMonths+' AFTER valid months)'+(studyInsufficient?' - INSUFFICIENT in at least one period':''));
        lines.push('Reference data density: '+Math.round(refDataDensityF*100)+'% ('+refB.nValidMonths+'/'+beforeMonths+' BEFORE, '+
          refA.nValidMonths+'/'+afterMonths+' AFTER valid months)'+(refInsufficient?' - INSUFFICIENT in at least one period':''));
        // v10.161 S4 (asked directly: can the reference density silently INHERIT
        // the study's?). TRACED THROUGH THE CODE - IT CANNOT. Study and Reference
        // are two distinct labelled features of ONE FeatureCollection; reduceRegions
        // evaluates each separately and carries its own `label` through the flatten;
        // groupSeriesByLabel() buckets strictly on that label, has no default bucket
        // and no copy-from-sibling path, and a feature with no label is DROPPED, not
        // merged. If the Reference series were missing entirely the lookup would give
        // [] and 0 valid months - which would DIFFER from the study, not match it.
        // So identical densities are a real, independent measurement at both sites.
        // WHY THEY MATCH ANYWAY, at Bocas del Toro 20 km apart: mkMoFAIRange() applies
        // NO per-pixel cloud mask, so a month is valid iff Sentinel-2 has a scene with
        // CLOUDY_PIXEL_PERCENTAGE < 20 over the point. That is a per-granule property,
        // and an S2 granule is ~110 km across - two sites 20 km apart normally sit in
        // the same granule(s) and therefore share the SAME scene list, month for month.
        // Identical counts are the expected result, not a copied number. Said on
        // screen so the next reader does not have to re-derive it.
        if(studyB.nValidMonths===refB.nValidMonths && studyA.nValidMonths===refA.nValidMonths){
          lines.push('NOTE: study and reference report IDENTICAL valid-month counts. These ARE measured '+
            'separately (two labelled regions, one reduceRegions each, bucketed strictly by label - no '+
            'inheritance path exists). They match because Sentinel-2 scene availability is a per-granule '+
            'property and a granule is ~110km across, so two sites this close normally share the same '+
            'scene list month for month. Expected, not a copied number.');
        }
        if(excludedCount>0) lines.push('NOTE: '+excludedCount+' closer reference candidate(s) excluded (already tested as a study site this session).');
        lines.push(repeatChar('\u2500',50));
        lines.push('Reference reef: '+s7fData.refSite.lat.toFixed(4)+', '+s7fData.refSite.lon.toFixed(4)+
          ' ('+s7fData.refSite.radiusKm+'km away, depth='+s7fData.refSite.elev.toFixed(1)+'m)');
        lines.push('BEFORE: '+beforeStartTxt+' + '+beforeMonths+'mo | AFTER: '+afterStartTxt+' + '+afterMonths+'mo | radius='+radiusKm+'km');
        lines.push('For full node-by-node / study-vs-reference detail, run S7D and S7E individually above with these same inputs.');
        lines.push('');
        lines.push('=== v10.154 SIGNIFICANCE (permutation, 500 shuffles) ===');
        // v10.159 W-01 item 2: these four went out bare. permP()/permVerdictTag()
        // now gate every one of them on the machine-readable deseasonalized flag.
        lines.push('Study     AC1 '+permP(sAC1T)+permVerdictTag(sAC1T)+'  |  Var '+permP(sVarT)+permVerdictTag(sVarT));
        lines.push('Reference AC1 '+permP(rAC1T)+permVerdictTag(rAC1T)+'  |  Var '+permP(rVarT)+permVerdictTag(rVarT));
        lines.push('SERIES USED: '+permSeriesNote(sAC1T,'study'));
        lines.push('             '+permSeriesNote(rAC1T,'reference'));
        var _s7fDisc=nodeStatsDisclosureLines([{label:'study BEFORE',st:studyB},{label:'study AFTER',st:studyA},
                                               {label:'reference BEFORE',st:refB},{label:'reference AFTER',st:refA}]);
        if(dSum.disclosureLines && dSum.disclosureLines.length>0){
          lines.push('SERIES QUALITY, S7D nodes (v10.159 W-02):');
          dSum.disclosureLines.forEach(function(d){ lines.push(d); });
        }
        if(_s7fDisc.length>0){
          lines.push('SERIES QUALITY (v10.159 W-02 - computed since v10.158, never shown until now):');
          _s7fDisc.forEach(function(d){ lines.push(d); });
        }
        lines.push('A site now counts as showing a signal only if a p-value is BELOW 0.05 AND the');
        lines.push('direction is rising. Under v10.153 the direction alone was enough, and those');
        lines.push('cutoffs were measured firing on up to 80% of no-event windows.');
        lines.push('Direction-only read (old behaviour), study site: '+(studyDirOnly?'would have flagged':'would not have flagged')+
          ' | significance-gated: '+(studySignal?'flags':'does not flag'));
        lines.push('Calibrated cutoffs still shown for reference: \u0394AC1>'+_s7fAc1.toFixed(3)+', \u0394Var>'+_s7fVar.toFixed(2)+'x');
        // v10.161 FIX 19 / S6c - THIS LINE CORRECTED FOR A FAMILY OF ZERO TESTS.
        // OBSERVED IN A LIVE BROWSER RUN: "NOTE: 4 tests fired here; the
        // Bonferroni bar is p<0.0125." printed verbatim while all four of
        // Study AC1 / Study Var / Reference AC1 / Reference Var had come back
        // NOT TESTABLE. Both numbers were hardcoded, so neither could notice.
        // The family is now the tests that actually returned a p-value, the bar
        // is derived from that count, and when the count is zero the line says
        // so instead of quoting a correction for tests that never ran.
        var _s7fPUsable=0;
        [sAC1T,sVarT,rAC1T,rVarT].forEach(function(_t){ if(permUsable(_t)) _s7fPUsable++; });
        if(_s7fPUsable===0){
          lines.push('MULTIPLE COMPARISONS: none. 4 tests were fired here (study/reference x AC1/Var)');
          lines.push('and NOT ONE returned a p-value, so there is no family of results to correct and');
          lines.push('no Bonferroni bar is quoted. Nothing above was tested at this site/window.');
        } else {
          lines.push('MULTIPLE COMPARISONS: 4 tests were fired here and '+_s7fPUsable+' returned a p-value, so the');
          lines.push('Bonferroni bar over the family that actually exists is p<'+(0.05/_s7fPUsable).toFixed(4)+'.');
        }
        if(_pre && _pre.note) lines.push(_pre.note);   // v10.161 S4
        s7fResultV.setValue(lines.join('\n'));

        var vCol = (dSum.headline.indexOf('HYPER')===0||eHeadline.indexOf('LOCAL ANOMALY')>=0)?'#880000':
                   (eHeadline.indexOf('CANNOT')>=0)?'#886600':'#226644';
        var vBg = vCol==='#880000'?'#ffd0d0':vCol==='#886600'?'#fff6cc':'#e8f4ff';
        s7fStatusV.setValue(dSum.headline+'\n'+eHeadline);
        s7fStatusV.style().set('color',vCol); s7fStatusV.style().set('backgroundColor',vBg);
        s7fStatusV.style().set('border','2px solid '+vCol); s7fStatusV.style().set('whiteSpace','pre'); s7fStatusV.style().set('fontWeight','bold');

        print('=== S7F COMBINED SUMMARY (S7D + S7E) ==='); print(lines.join('\n'));
      } catch(eF2){
        s7fStatusV.setValue(friendlyEEError(eF2));
        s7fStatusV.style().set('color','#cc0000'); s7fStatusV.style().set('backgroundColor','#ffd0d0');
        print('=== S7F finishAll error === '+eF2);
      }
    }
    fetchFaiSeriesChunked({
      gridStartStr:_s7fGrid.startDateStr, nMonths:_s7fGrid.nMonths, ptsFC:ptsFC,
      nRegions:nodes.length, band:'fai', scale:20, tag:'S7F-D',
      isCurrent:function(){ return s7fMyRun===s7fRunSeq && !s7fDead; },
      onProgress:function(i,total,ch){
        if(s7fMyRun!==s7fRunSeq || s7fDead) return;
        s7fStatusV.setValue('Running: S7D series chunk '+(i+1)+' / '+total+' ('+ch.start.substring(0,7)+' + '+
          ch.months+' months x '+nodes.length+' nodes = '+ch.expected+' features), alongside the NDVI check\n'+
          'and the reference search.\n'+S7_STALL_HINT+'\n'+S7_DEADLINE_NOTE);
      }
    }, function(res){
      if(!res.ok){ s7fRefuseChunks(res, 'S7D 9-node series', nodes.length, false); return; }
      s7fBump('dCombined', res.fc, null);
    });
    rD_ndvi.evaluate(function(v,e){ s7fBump('dNdvi', v, e); });
    rCandidatesF.evaluate(function(v,e){ s7fBump('candidates', v, e); });
    });  // end faiPrecheckThenRun callback (v10.161 S4)
  }
});
panel.add(s7fRunBtn);
panel.add(s7fStatusV);
panel.add(s7fResultV);
panel.add(legDiv());

// ============================================================
// S7G - CROSS-INDEX SCATTER PANEL (v10.167 NEW)
// WHY: every algae/water number in this tool is currently TABULATED. A table
// answers "how big is FAI at N?"; it does not answer "do FAI and NDCI move
// together across this reef, or is one of them being driven by something the
// other is not?" - which is the question that makes spatial and oceanographic
// drift visible. S7B already samples three indices at nine points around a
// site in ONE call; plotting them against each other costs nothing more.
//
// HARD CONSTRAINT, and what it excluded: ZERO new Earth Engine calls. Every
// value plotted here was already fetched and is read from s7bScanStore (S7B's
// 9-point scan) or lastClickIndexStore (the current click). That constraint
// removed one of the three charts originally asked for:
//   SST x Chl-a ACROSS THE 9 SCAN POINTS IS NOT PLOTTED, AND CANNOT BE.
//   S7B reduces ONE image over its nine buffers - faiImg + ndciImg +
//   ndviWater - so it has no SST and no Chl-a at any of the nine points. The
//   only SST and Chl-a in hand are the SINGLE pair at the clicked point
//   (5 km / 1 km buffers, MODIS-era OISST and Copernicus ocean colour). One
//   point is not a scatter, and drawing it as one would be a lie about what
//   was measured. It is shown as a numeric row instead, and the chart slot
//   says why it is empty. Plotting it properly needs a 9-point SST/Chl-a
//   fetch, which is a new EE call and is therefore out of scope here.
//
// CHARTING DECISIONS, and which ones are deliberate refusals:
//  - NOT nine categorical series. Nine generated hues across nine compass
//    nodes would be nine colours carrying no order and no meaning. Colour
//    instead encodes the ON-REEF / OFF-REEF binary that S7D already computes
//    from NDVI-water (> -0.10 = on-reef) - two series, both named in the
//    legend, a distinction that actually changes how a point should be read.
//    CHOSEN FOR: the FAI x NDCI chart.
//  - The NDVI-water x FAI chart uses the OTHER permitted option - one series
//    with the centre point marked - because there colouring by an NDVI-water
//    cut would be colouring by a threshold on the x axis itself: the legend
//    would tell you only which side of x = -0.10 each point sits on, which
//    the axis already says. That is decoration, not information.
//  - NO dual-axis chart anywhere. Two measures of different scale get two
//    charts. Every axis carries one measure and its unit.
//  - Grid and axes recessive (#e6e6e6 gridlines, 8px grey tick text); marks
//    prominent (9px points, 14px for the marked centre).
//  - A single-series chart gets no legend box; its title names the series.
//  - Fewer than 3 plottable points after nulls are dropped renders an
//    explicit message, never an empty chart frame.
//  - ui.Chart(dataTable, ...) - the client-side DataTable constructor - is
//    used rather than ui.Chart.array.values() or ui.Chart.feature.byFeature().
//    Those two take ee.Array / ee.FeatureCollection arguments and evaluate
//    them server-side, which is an Earth Engine call. The constraint above
//    forbids one, so the values go in as a plain client-side table.
// ============================================================
var S7G_MIN_POINTS = 3;
// Canonical series order, so a series always gets the same colour whatever
// order the points happen to arrive in.
var S7G_SERIES_REEF = ['On-reef (NDVI-water > -0.10)','Off-reef (NDVI-water <= -0.10)','On-reef status unknown'];
var S7G_SERIES_CENTRE = ['Ring point','Centre (your click)'];
var S7G_COLORS_REEF = ['#2166ac','#c0392b','#9aa0a6'];
var S7G_COLORS_CENTRE = ['#4a6fa5','#b8422a'];

// Pure: drop every point that has no number on BOTH axes, and carry the
// on-reef flag along. Unit-tested in Node.
function s7gPairs(points, xKey, yKey){
  var out=[];
  (points||[]).forEach(function(p){
    if(!p) return;
    var x=p[xKey], y=p[yKey];
    if(x===null||x===undefined||typeof x!=='number'||isNaN(x)) return;
    if(y===null||y===undefined||typeof y!=='number'||isNaN(y)) return;
    var nw=p.ndviW;
    var onReef=(nw===null||nw===undefined||typeof nw!=='number'||isNaN(nw))?null:(nw>S7G_ONREEF_NDVI);
    out.push({label:p.label, x:x, y:y, ndviW:(typeof nw==='number'&&!isNaN(nw))?nw:null, onReef:onReef});
  });
  return out;
}
function s7gEnoughPoints(pairs){ return ((pairs||[]).length) >= S7G_MIN_POINTS; }
function s7gSeriesOf(pair, mode){
  if(mode==='centre') return (pair.label==='Center')?S7G_SERIES_CENTRE[1]:S7G_SERIES_CENTRE[0];
  if(pair.onReef===null) return S7G_SERIES_REEF[2];
  return pair.onReef?S7G_SERIES_REEF[0]:S7G_SERIES_REEF[1];
}
// Pure: a Google-Charts DataTable - [[xTitle, series1, series2, ...],
// [x, y|null, y|null], ...] - with the series in canonical order so colours
// are stable. Returns {table, seriesNames}.
function s7gDataTable(pairs, xTitle, mode){
  var canon=(mode==='centre')?S7G_SERIES_CENTRE:S7G_SERIES_REEF;
  var present={}, names=[], i;
  (pairs||[]).forEach(function(p){ present[s7gSeriesOf(p,mode)]=true; });
  for(i=0;i<canon.length;i++){ if(present[canon[i]]) names.push(canon[i]); }
  var header=[xTitle];
  for(i=0;i<names.length;i++) header.push(names[i]);
  var idx={};
  for(i=0;i<names.length;i++) idx[names[i]]=i;
  var rows=[header];
  (pairs||[]).forEach(function(p){
    var row=[p.x], k;
    for(k=0;k<names.length;k++) row.push(null);
    row[1+idx[s7gSeriesOf(p,mode)]]=p.y;
    rows.push(row);
  });
  return {table:rows, seriesNames:names};
}
// Pure: which canonical colours the present series map to.
function s7gColorsFor(seriesNames, mode){
  var canon=(mode==='centre')?S7G_SERIES_CENTRE:S7G_SERIES_REEF;
  var pal=(mode==='centre')?S7G_COLORS_CENTRE:S7G_COLORS_REEF;
  return (seriesNames||[]).map(function(n){
    var i=canon.indexOf(n);
    return (i>=0)?pal[i]:'#666666';
  });
}
// Recessive grid, prominent marks, one measure per axis, legend only when
// there is more than one series to name.
function s7gChartOptions(title, xTitle, yTitle, seriesNames, mode){
  var colors=s7gColorsFor(seriesNames, mode);
  var opts={
    title:title,
    titleTextStyle:{fontSize:11, bold:true, color:'#222222'},
    width:238, height:210,
    chartArea:{left:50, top:36, width:'68%', height:'58%'},
    pointSize:9,
    dataOpacity:0.95,
    colors:colors,
    backgroundColor:{fill:'#ffffff'},
    hAxis:{title:xTitle, titleTextStyle:{fontSize:9, italic:false, color:'#555555'},
           textStyle:{fontSize:8, color:'#777777'},
           gridlines:{color:'#e8e8e8', count:5}, minorGridlines:{count:0}, baselineColor:'#c0c0c0'},
    vAxis:{title:yTitle, titleTextStyle:{fontSize:9, italic:false, color:'#555555'},
           textStyle:{fontSize:8, color:'#777777'},
           gridlines:{color:'#e8e8e8', count:5}, minorGridlines:{count:0}, baselineColor:'#c0c0c0'},
    legend:(seriesNames&&seriesNames.length>1)?
      {position:'bottom', textStyle:{fontSize:8, color:'#444444'}} : {position:'none'}
  };
  // The marked centre point is the one mark that must read as different in
  // size, not only in hue.
  if(mode==='centre'){
    var ci=(seriesNames||[]).indexOf(S7G_SERIES_CENTRE[1]);
    if(ci>=0){ opts.series={}; opts.series[ci]={pointSize:15, pointShape:'diamond'}; }
  }
  return opts;
}
// Pure: the numbers, as text, because GEE's chart rendering is limited and a
// reader needs to be able to read the values off.
function s7gTextTable(pairs, xName, yName, mode){
  var w=8, lines=[];
  function pad(s2,n){ s2=String(s2); while(s2.length<n) s2+=' '; return s2; }
  lines.push(pad('Point',8)+'| '+pad(xName,w)+'| '+pad(yName,w)+'| '+(mode==='centre'?'Role':'On-reef?'));
  lines.push(repeatChar('─', 8+2+w+2+w+2+10));
  (pairs||[]).forEach(function(p){
    var third=(mode==='centre')?((p.label==='Center')?'CENTRE':'ring')
      :(p.onReef===null?'unknown':(p.onReef?'yes':'NO ('+p.ndviW.toFixed(2)+')'));
    lines.push(pad(p.label,8)+'| '+pad(p.x.toFixed(3),w)+'| '+pad(p.y.toFixed(3),w)+'| '+third);
  });
  return lines.join('\n');
}
// Pure: the message shown INSTEAD of a chart frame when there is not enough to plot.
function s7gNotEnoughText(nPlottable, nTotal, xName, yName){
  return 'NOT ENOUGH VALID POINTS to plot '+yName+' against '+xName+': '+nPlottable+
    ' of '+nTotal+' scanned point(s) had a number on BOTH axes, against a floor of '+S7G_MIN_POINTS+
    '. Nothing is drawn - an empty chart frame would look like a measured null.'+
    (nTotal>0&&nPlottable<nTotal?' The missing points are masked (cloud, land or outside the ocean mask), not zero.':'');
}

