        for(var ti=0;ti<trResult.episodes.length;ti++){
          var tep=trResult.episodes[ti];
          print('  Episode '+(ti+1)+': '+tep.startDate+' to '+tep.endDate+' - '+tep.months+' month(s), peak '+tep.peakSST.toFixed(2)+' deg C');
        }
